import { imagePreparation } from './image-transport-support.ts'
import { afterAll, beforeAll, describe, expect, it } from 'vitest'
import { ExactDecimal } from '@omne-harness-lite/call-accounts'
import type { PlanInput, ReadFacts } from '@omne-harness-lite/model-request-runtime'
import {
  openaiDefinitions,
  createOpenAiInputMeter,
  createOfficialProfileContent,
  createPiAiTransport,
  type ModelDefinition,
} from '../src/index.ts'
import { syntheticInputMeter } from './synthetic-input-meter.ts'
import { certificate, fixture, input, message, content, sse, finish } from './support.ts'

const models = [
  'openai/gpt-5.6-sol-pro',
  'openai/gpt-5.6-terra-pro',
  'openai/gpt-5.6-luna-pro',
  'openai/gpt-6-astra-pro',
  'openai/gpt-6-sol-pro',
  'openai/gpt-6-luna-pro',
] as const
let cert: ReturnType<typeof certificate>
beforeAll(() => {
  cert = certificate()
})
afterAll(() => cert.dispose())
function request(definition: ModelDefinition): PlanInput {
  const profile = createOfficialProfileContent(definition, {
    providers: ['openai'],
    allowFallback: false,
    configuration: { revision: 'independent-pro-scope', values: { cache: { mode: 'automatic' } } },
  })
  if ('rejected' in profile) throw Error(profile.rejected)
  return {
    ...input(),
    routeName: definition.modelId,
    provider: 'openai',
    snapshot: {
      ...input().snapshot,
      ...definition.capabilities,
      adaptation: profile.ok.adaptation,
      providers: ['openai'],
    },
  }
}
function accounts(facts: ReadFacts) {
  expect(facts.usage.source).toBe('upstream')
  for (const [field, value] of [
    ['input_tokens', 50],
    ['output_tokens', 7],
    ['cache_read_tokens', 50],
    ['cache_write_tokens', 20],
  ] as const) {
    const actual = facts.usage[field]
    if (actual === 'unknown') throw Error(`lost actual ${field}`)
    expect(ExactDecimal.from(actual).compare(ExactDecimal.from(value))).toBe(0)
  }
  if (facts.cost.cost_usd === 'unknown') throw Error('lost actual cost')
  expect(ExactDecimal.from(facts.cost.cost_usd).compare(ExactDecimal.from(0.125))).toBe(0)
}

describe('independent six fixed Pro usage-scope bindings', () => {
  for (const model of models)
    for (const cancelled of [false, true]) {
      it(`${model} preserves actual accounts and withholds anchors after ${cancelled ? 'cancel' : 'complete'}`, async () => {
        const definition = openaiDefinitions.find(d => d.modelId === model)!
        const is56 = model.startsWith('openai/gpt-5.6-')
        expect(definition.revision).toBe(is56 ? '8' : '6')
        expect(definition.implementation.revision).toBe('mp4-18')
        // Current official visible-input estimates are supplied for all six.
        // These controlled reader observations do not certify upstream token scope.
        const meter = createOpenAiInputMeter(definition)
        const host = await fixture(
          cert.tls,
          response => {
            response.writeHead(200, { 'content-type': 'text/event-stream' })
            response.write(
              sse({
                choices: [],
                provider: 'OpenAI',
                model,
                usage: {
                  prompt_tokens: 120,
                  completion_tokens: 7,
                  cost: 0.125,
                  prompt_tokens_details: { cached_tokens: 50, cache_write_tokens: 20 },
                },
              }) + content('observed Pro reply'),
            )
            if (!cancelled) response.end(finish())
          },
          {},
          undefined,
          [definition],
        )
        const transport = createPiAiTransport({
          ...host.options,
          definitions: [definition],
          inputMeters: [meter],
        })
        try {
          const first = await request(definition)
          const plan = await transport.plan(first, { signal: new AbortController().signal })
          if (!('planned' in plan)) throw Error(JSON.stringify(plan))
          expect(plan.planned.measurement.mode).toBe('full')
          const abort = new AbortController()
          const sent = await transport.send(plan.planned, 'independent-local-only', abort.signal)
          if (!('response' in sent)) throw Error('local send failed')
          const reader = transport.read(sent.response, plan.planned, abort.signal)
          let next = await reader.next()
          expect(next.done).toBe(false)
          if (cancelled) abort.abort()
          while (!next.done) next = await reader.next()
          await sent.response.stopped
          const facts = next.value.readFacts
          accounts(facts)
          expect(facts.observedInput).toEqual({ kind: 'unavailable', reason: 'scope_unknown' })
          if (cancelled) expect(next.value).toHaveProperty('aborted', true)
          const captured = plan.planned.requestInput
          if (captured.kind !== 'known') throw Error('current request not captured')
          for (const revision of [
            'openrouter-usage-reader/2',
            'openrouter-usage-reader/3-openai-pro-scope',
          ]) {
            const forged = await transport.plan(
              {
                ...first,
                messages: [...first.messages, message('user', 'fresh Pro input', 'fresh-pro')],
                calibration: {
                  kind: 'observation',
                  usage: facts.usage,
                  outputBlocks: [],
                  replaySelection: [],
                  inputCalibration: {
                    requestInput: captured,
                    observedInput: {
                      kind: 'from_usage',
                      provenance: {
                        adapterRevision: revision,
                        fieldPaths: ['usage.prompt_tokens'],
                        upstreamModel: model,
                        servingProvider: 'OpenAI',
                      },
                    },
                    outputGroup: { kind: 'unavailable', reason: 'not_retained' },
                  },
                },
              },
              { signal: new AbortController().signal },
            )
            if (!('planned' in forged)) throw Error(JSON.stringify(forged))
            expect(forged.planned.measurement).toMatchObject({
              mode: 'full',
              fallbackReason: 'source_unavailable',
            })
          }
          if (!cancelled) {
            // Deliberately stale coordinates are a negative fixture, not an old
            // reader implementation. They cannot promote ambiguous Pro usage.
            const old: ModelDefinition = {
              ...definition,
              revision: is56 ? '4' : '1',
              implementation: { name: 'pi-ai:openai', revision: is56 ? 'mp4-5' : 'mp4-1' },
            }
            const historical = createPiAiTransport({
              ...host.options,
              definitions: [old],
              inputMeters: [syntheticInputMeter(old, 'openai')],
            })
            try {
              const oldPlan = await historical.plan(await request(old), {
                signal: new AbortController().signal,
              })
              if (!('planned' in oldPlan)) throw Error(JSON.stringify(oldPlan))
              const oldSent = await historical.send(
                oldPlan.planned,
                'independent-local-only',
                abort.signal,
              )
              if (!('response' in oldSent)) throw Error('historical local send failed')
              const oldReader = historical.read(oldSent.response, oldPlan.planned, abort.signal)
              let oldNext = await oldReader.next()
              while (!oldNext.done) oldNext = await oldReader.next()
              await oldSent.response.stopped
              expect(oldNext.value.readFacts.observedInput).toEqual({
                kind: 'unavailable',
                reason: 'scope_unknown',
              })
              accounts(oldNext.value.readFacts)
              const rejectedOld = await transport.plan(
                {
                  ...first,
                  calibration: {
                    kind: 'observation',
                    usage: oldNext.value.readFacts.usage,
                    outputBlocks: [],
                    replaySelection: [],
                    inputCalibration: {
                      requestInput: oldPlan.planned.requestInput,
                      observedInput: oldNext.value.readFacts.observedInput,
                      outputGroup: { kind: 'unavailable', reason: 'not_retained' },
                    },
                  },
                },
                { signal: new AbortController().signal },
              )
              if (!('planned' in rejectedOld)) throw Error(JSON.stringify(rejectedOld))
              expect(rejectedOld.planned.measurement).toMatchObject({
                mode: 'full',
                fallbackReason: 'source_unavailable',
              })
            } finally {
              await historical.close()
            }
          }
          expect(host.requests).toHaveLength(cancelled ? 1 : 2)
        } finally {
          await transport.close()
          await host.close()
        }
      })
    }
})

tests/acceptance-calibration-reader.spec.source:
import { imagePreparation } from './image-transport-support.ts'
import { afterAll, beforeAll, describe, expect, it } from 'vitest'
import { invokeModel, type PlanInput } from '@omne-harness-lite/model-request-runtime'
import {
  anthropicDefinitions,
  createAnthropicInputMeter,
  createPiAiTransport,
  createOfficialProfileContent,
} from '../src/index.ts'
import { certificate, fixture, input, message, policy, content, sse, finish } from './support.ts'
let cert: ReturnType<typeof certificate>
beforeAll(() => {
  cert = certificate()
})
afterAll(() => cert.dispose())
const definition = anthropicDefinitions[0]!
function request(): PlanInput {
  const profile = createOfficialProfileContent(definition, {
    providers: ['anthropic'],
    allowFallback: false,
    configuration: {
      revision: 'reader-independent',
      values: { cache: { mode: 'explicit', ttl: '1h', breakpoints: ['last_message'] } },
    },
  })
  if ('rejected' in profile) throw Error(profile.rejected)
  return {
    ...input(),
    routeName: definition.modelId,
    provider: 'anthropic',
    parameters: { maxOutputTokens: 128 },
    snapshot: {
      ...input().snapshot,
      ...definition.capabilities,
      adaptation: profile.ok.adaptation,
      providers: ['anthropic'],
    },
    messages: [message('user', 'observe actual reader facts')],
  }
}
const cases = [
  {
    name: 'complete-disjoint-cache',
    usage: {
      prompt_tokens: 120,
      completion_tokens: 4,
      prompt_tokens_details: { cached_tokens: 60, cache_write_tokens: 20 },
    },
    observed: { kind: 'from_usage' },
  },
  {
    name: 'known-total-unknown-cache-write',
    usage: {
      prompt_tokens: 120,
      completion_tokens: 4,
      prompt_tokens_details: { cached_tokens: 60 },
    },
    observed: { kind: 'upstream_total', tokens: 120 },
  },
  {
    name: 'conflicting-parts',
    usage: {
      prompt_tokens: 10,
      completion_tokens: 4,
      prompt_tokens_details: { cached_tokens: 60, cache_write_tokens: 20 },
    },
    observed: { kind: 'unavailable', reason: 'inconsistent_usage' },
  },
  {
    name: 'known-zero',
    usage: {
      prompt_tokens: 0,
      completion_tokens: 4,
      prompt_tokens_details: { cached_tokens: 0, cache_write_tokens: 0 },
    },
    observed: { kind: 'from_usage' },
  },
  {
    name: 'response-cache-zero',
    usage: {
      prompt_tokens: 0,
      completion_tokens: 4,
      prompt_tokens_details: { cached_tokens: 0, cache_write_tokens: 0 },
    },
    observed: { kind: 'unavailable', reason: 'response_cache' },
  },
  {
    name: 'billing-total-only',
    usage: { total_tokens: 120, completion_tokens: 4 },
    observed: { kind: 'unavailable', reason: 'scope_unknown' },
  },
  {
    name: 'no-usage',
    usage: undefined,
    observed: { kind: 'unavailable', reason: 'missing_usage' },
  },
] as const

describe('independent real TLS reader-to-public-invoke calibration', () => {
  for (const entry of cases)
    it(entry.name, async () => {
      const host = await fixture(
        cert.tls,
        response => {
          response.writeHead(200, {
            'content-type': 'text/event-stream',
            ...(entry.name === 'response-cache-zero' ? { 'X-OpenRouter-Cache-Status': 'HIT' } : {}),
          })
          response.end(
            content('original reply') +
              sse({
                choices: [],
                model: definition.modelId,
                provider: 'Anthropic',
                ...(entry.usage === undefined ? {} : { usage: entry.usage }),
              }) +
              finish(),
          )
        },
        {},
        undefined,
        [definition],
      )
      const transport = createPiAiTransport({
        ...host.options,
        definitions: [definition],
        inputMeters: [createAnthropicInputMeter(definition)],
      })
      try {
        const handle = invokeModel({
          ...(await request()),
          transport,
          credential: 'controlled-reader-key',
          signal: new AbortController().signal,
          policy: policy(),
          onAccepted() {},
        })
        const result = await handle.outcome
        if (!('outcome' in result)) throw Error(JSON.stringify(result))
        expect(result.outcome).toBe('complete')
        expect(result.inputCalibration.observedInput).toMatchObject(entry.observed)
        expect(handle.observedFacts()).toMatchObject({
          facts: { inputCalibration: result.inputCalibration, usage: result.usage },
        })
        expect(result.inputCalibration.outputGroup).toMatchObject({
          kind: 'known',
          completeness: 'complete',
          source: 'reply',
        })
        if (entry.name === 'known-total-unknown-cache-write')
          expect(result.usage).toMatchObject({
            input_tokens: 'unknown',
            cache_read_tokens: 60,
            cache_write_tokens: 'unknown',
          })
        if (entry.name === 'conflicting-parts')
          expect(result.usage).toMatchObject({
            input_tokens: 'unknown',
            cache_read_tokens: 60,
            cache_write_tokens: 20,
          })
        if (entry.name === 'no-usage') expect(result.usage.source).toBe('none')
        expect(host.requests).toHaveLength(1)
      } finally {
        await transport.close()
        await host.close()
      }
    })
  for (const ending of [
    'abort-before-usage',
    'abort-after-usage',
    'invalid-frame',
    'in-band-error',
    'connection-break',
  ] as const)
    it(`retains only already-observed facts on ${ending} and awaits actual read stop`, async () => {
      const controller = new AbortController()
      const usage = sse({
        choices: [],
        model: definition.modelId,
        provider: 'Anthropic',
        usage: {
          prompt_tokens: 123,
          completion_tokens: 4,
          prompt_tokens_details: { cached_tokens: 10 },
        },
      })
      const host = await fixture(
        cert.tls,
        async response => {
          response.writeHead(200, { 'content-type': 'text/event-stream' })
          if (ending === 'abort-before-usage') response.write(content('partial'))
          else if (ending === 'abort-after-usage') response.write(usage + content('partial'))
          else if (ending === 'invalid-frame')
            response.end(usage + content('partial') + 'data: {invalid}\n\n')
          else if (ending === 'in-band-error')
            response.end(
              usage + sse({ error: { code: 503, message: 'controlled provider interruption' } }),
            )
          else {
            response.write(usage + content('partial'))
            await new Promise(resolve => setTimeout(resolve, 20))
            response.destroy()
          }
        },
        {},
        undefined,
        [definition],
      )
      const transport = createPiAiTransport({
        ...host.options,
        definitions: [definition],
        inputMeters: [createAnthropicInputMeter(definition)],
      })
      const stopped: Promise<void>[] = []
      const wrapped = {
        ...transport,
        async send(...args: Parameters<typeof transport.send>) {
          const result = await transport.send(...args)
          if ('response' in result) stopped.push(result.response.stopped)
          return result
        },
      }
      try {
        const outcome = await invokeModel({
          ...(await request()),
          transport: wrapped,
          credential: 'controlled-stop-key',
          signal: controller.signal,
          policy: policy(),
          onAccepted() {
            if (ending.startsWith('abort-')) controller.abort()
          },
        }).outcome
        if (!('outcome' in outcome)) throw Error(JSON.stringify(outcome))
        expect(outcome.inputCalibration.observedInput).toMatchObject(
          ending === 'abort-before-usage'
            ? { kind: 'unavailable', reason: 'missing_usage' }
            : { kind: 'upstream_total', tokens: 123 },
        )
        expect(outcome.outcome).not.toBe('complete')
        expect(stopped).toHaveLength(1)
        await Promise.all(stopped)
        expect(host.requests).toHaveLength(1)
      } finally {
        controller.abort()
        await transport.close()
        await host.close()
      }
    })
  it('assembly rejection still obtains the actual stopped reader final facts without waiting for future usage', async () => {
    const host = await fixture(
      cert.tls,
      response => {
        response.writeHead(200, { 'content-type': 'text/event-stream' })
        response.write(
          sse({
            choices: [],
            model: definition.modelId,
            provider: 'Anthropic',
            usage: { prompt_tokens: 123, completion_tokens: 4 },
          }) + content('not-yet-complete'),
        )
        // Never EOF: only the consumer rejection can stop this actual response.
      },
      {},
      undefined,
      [definition],
    )
    const transport = createPiAiTransport({
      ...host.options,
      definitions: [definition],
      inputMeters: [createAnthropicInputMeter(definition)],
    })
    let terminals = 0,
      duplicate = false
    const stopped: Promise<void>[] = []
    const wrapped = {
      ...transport,
      async send(...args: Parameters<typeof transport.send>) {
        const sent = await transport.send(...args)
        if ('response' in sent) stopped.push(sent.response.stopped)
        return sent
      },
      async *read(...args: Parameters<typeof transport.read>) {
        const actual = transport.read(...args)
        while (true) {
          const next = await actual.next()
          if (next.done) {
            terminals++
            return next.value
          }
          yield next.value
          // A controlled adapter protocol violation drives the real stream-assembly admission
          // guard. Statistics and actual stop still come from the production TLS reader.
          if (!duplicate && next.value.t === 'open') {
            duplicate = true
            yield next.value
          }
        }
      },
    }
    try {
      const result = await invokeModel({
        ...(await request()),
        transport: wrapped,
        credential: 'controlled-assembly-key',
        signal: new AbortController().signal,
        policy: policy(),
        onAccepted() {},
      }).outcome
      if (!('outcome' in result)) throw Error(JSON.stringify(result))
      expect(duplicate).toBe(true)
      expect(result.outcome).not.toBe('complete')
      expect(result.inputCalibration.observedInput).toMatchObject({
        kind: 'upstream_total',
        tokens: 123,
      })
      expect(terminals).toBe(1)
      expect(stopped).toHaveLength(1)
      await Promise.all(stopped)
      expect(host.requests).toHaveLength(1)
    } finally {
      await transport.close()
      await host.close()
    }
  })
})

tests/anthropic-cache-target.spec.ts.source:
import { readFileSync } from 'node:fs'
import { describe, expect, it } from 'vitest'
import { createOfficialProfileContent } from '../src/configuration.ts'
import { createAnthropicInputMeter } from '../src/input-meters/anthropic.ts'
import { anthropicDefinitions } from '../src/official-models/anthropic.ts'
import { planRequest } from '../src/plan.ts'
import { directFull } from './direct-full-input.ts'
import { writeJsonLossless } from '@omne-harness-lite/content-blocks'
import { testImagePreparerFor } from './image-transport-support.ts'
import { at, input, judgedMessage, message } from './support.ts'
const image = {
  kind: 'image',
  id: 'image',
  mediaType: 'image/gif',
  data: {
    inline: readFileSync(
      new URL('./fixtures/anthropic/reference-single-frame.gif', import.meta.url),
    ).toString('base64'),
  },
  visibility: { toHuman: true, toModel: true },
}
const text = (value: string) => ({
  kind: 'text',
  id: 'text',
  text: value,
  visibility: { toHuman: true, toModel: true },
})

describe.each(anthropicDefinitions)('$modelId strict last_message cache target', original => {
  const definition = original
  const meter = createAnthropicInputMeter(definition)
  const profile = createOfficialProfileContent(definition, {
    providers: ['anthropic'],
    allowFallback: false,
    configuration: {
      revision: '1',
      values: { cache: { mode: 'explicit', ttl: '1h', breakpoints: ['last_message'] } },
    },
  })
  if ('rejected' in profile) throw Error(profile.rejected)
  const resolved = profile.ok
  function request(blocks: readonly unknown[]) {
    const base = input()
    return {
      ...base,
      routeName: definition.modelId,
      provider: 'anthropic',
      messages: [
        message('user', 'older text', 'older'),
        judgedMessage({ type: 'user', id: 'tail', createdAt: at, blocks }),
      ],
      snapshot: {
        ...base.snapshot,
        ...definition.capabilities,
        adaptation: resolved.adaptation,
        providers: resolved.providers,
        allowFallback: false,
      },
    }
  }
  async function plan(blocks: readonly unknown[]) {
    return planRequest(
      request(blocks),
      [definition],
      meter,
      { signal: new AbortController().signal },
      testImagePreparerFor(planRequest),
    )
  }
  it.each([1, 2])(
    'uses configured top-level TTL only for the final %i pure images',
    async count => {
      const result = await plan(
        Array.from({ length: count }, (_, i) => ({ ...image, id: `image-${i}` })),
      )
      if (!('planned' in result)) throw Error(JSON.stringify(result))
      expect(result.planned.body.cache_control).toEqual({ type: 'ephemeral', ttl: '1h' })
      expect(result.planned.serialized.match(/cache_control/g)).toHaveLength(1)
      expect(result.planned.serialized).not.toContain('"text":""')
      expect(result.planned.requestInput.kind).toBe('known')
    },
  )
  it('retains the text-block layout for real text mixed with images', async () => {
    const result = await plan([text('question'), image])
    if (!('planned' in result)) throw Error(JSON.stringify(result))
    expect(result.planned.body.cache_control).toBeUndefined()
    expect(result.planned.serialized).toContain(
      '"text":"question","cache_control":{"type":"ephemeral","ttl":"1h"}',
    )
  })
  it.each([{ blocks: [] }, { blocks: [text('')] }, { blocks: [text(''), image] }])(
    'does not move an empty target back to older text',
    async ({ blocks }) => {
      expect(await plan(blocks)).toEqual({ rejected: 'unavailable' })
    },
  )
  it('does not omit an arbitrary caller top-level control from the meter', () => {
    const body = {
      model: definition.modelId,
      provider: { order: ['anthropic'], allow_fallbacks: false, require_parameters: true },
      cache_control: { type: 'ephemeral', ttl: '1h', extra: true },
      messages: [
        {
          role: 'user',
          content: [
            { type: 'image_url', image_url: { url: `data:image/gif;base64,${image.data.inline}` } },
          ],
        },
      ],
    }
    expect(directFull(meter, { body, serialized: writeJsonLossless(body) })).toEqual({
      kind: 'unavailable',
    })
  })
})

tests/anthropic-family-public.spec.ts.source:
import { readFileSync } from 'node:fs'
import { Context, type Plugin } from '@deepseek-ai/cordis'
import { afterAll, beforeAll, describe, expect, it } from 'vitest'
import {
  invokeModel,
  type PlanInput,
  type PlanOutputHistoryGroup,
} from '@omne-harness-lite/model-request-runtime'
import { createOfficialProfileContent } from '../src/configuration.ts'
import { anthropicReplayModels } from '../src/input-meters/anthropic-replay.ts'
import { createAnthropicInputMeter } from '../src/input-meters/anthropic.ts'
import { anthropicDefinitions } from '../src/official-models/anthropic.ts'
import { createPiAiTransport } from '../src/transport.ts'
import {
  createModelTransportService,
  type RetirementPolicy,
  type AdaptationLease,
} from '../src/registry.ts'
import { MODEL_TRANSPORT_SERVICE, createModelPlugin } from '../src/plugin.ts'
import { imagePreparation } from './image-transport-support.ts'
import {
  at,
  certificate,
  fixture,
  input,
  message,
  judgedMessage,
  content,
  sse,
  finish,
  policy,
} from './support.ts'

let cert: ReturnType<typeof certificate>
beforeAll(() => {
  cert = certificate()
})
afterAll(() => cert.dispose())
const retirement: RetirementPolicy = {
  waitMilliseconds: 1000,
  force: false,
  schedule(ms, callback) {
    const timer = setTimeout(callback, ms)
    return () => clearTimeout(timer)
  },
}
const gif = readFileSync(
  new URL('./fixtures/anthropic/reference-single-frame.gif', import.meta.url),
).toString('base64')

describe.each(['public', 'service'] as const)(
  'Anthropic %s actual local TLS complete history',
  entry => {
    for (const original of anthropicDefinitions)
      it(original.modelId, async () => {
        const definition = original
        const meter = createAnthropicInputMeter(definition)
        const profile = createOfficialProfileContent(definition, {
          providers: ['anthropic'],
          allowFallback: false,
          configuration: {
            revision: '1',
            values: { cache: { mode: 'explicit', ttl: '1h', breakpoints: ['last_message'] } },
          },
        })
        if ('rejected' in profile) throw Error(profile.rejected)
        let calls = 0
        const host = await fixture(
          cert.tls,
          res => {
            calls++
            const detail =
              calls === 2
                ? { type: 'reasoning.encrypted', data: `encrypted-${calls}` }
                : { type: 'reasoning.text', text: '', signature: `signature-${calls}` }
            res.end(
              sse({
                choices: [
                  {
                    delta: {
                      reasoning_details: [{ ...detail, format: 'anthropic-claude-v1', index: 0 }],
                    },
                  },
                ],
              }) +
                content(`answer ${calls}`) +
                sse({
                  choices: [],
                  model: definition.modelId,
                  provider: 'Anthropic',
                  usage: {
                    prompt_tokens: 100 * calls,
                    completion_tokens: 31,
                    completion_tokens_details: { reasoning_tokens: 7 },
                    prompt_tokens_details: { cached_tokens: 20, cache_write_tokens: 5 },
                  },
                }) +
                finish(),
            )
          },
          {},
          undefined,
          [definition],
        )
        const options = { ...host.options, imagePreparation }
        const direct = createPiAiTransport({
          ...options,
          definitions: [definition],
          inputMeters: [meter],
        })
        const ctx = new Context(),
          service = createModelTransportService(options)
        const provider: Plugin.Object = {
          name: 'anthropic-local-family',
          apply(context) {
            context.provide(MODEL_TRANSPORT_SERVICE, service)
            context.effect(() => async () => {
              await service.close(retirement)
              await service.closed
            })
          },
        }
        let release = () => {}
        try {
          let transport: AdaptationLease['transport'] = direct
          if (entry === 'service') {
            await ctx.plugin(provider)
            await ctx.plugin(createModelPlugin(definition, meter, retirement), {})
            expect(ctx.get(MODEL_TRANSPORT_SERVICE)).toBe(service)
            const acquired = service.acquire(profile.ok.adaptation, definition.modelId)
            if (!('lease' in acquired)) throw Error('service lease unavailable')
            release = acquired.lease.release
            transport = acquired.lease.transport
          }
          const base = input()
          let request: PlanInput = {
            ...base,
            routeName: definition.modelId,
            provider: 'anthropic',
            parameters: { reasoningEffort: 'high', maxOutputTokens: 128 },
            messages: [
              judgedMessage({
                type: 'user',
                id: 'image-user',
                createdAt: at,
                blocks: [
                  {
                    kind: 'image',
                    id: 'image',
                    mediaType: 'image/gif',
                    data: { inline: gif },
                    visibility: { toHuman: true, toModel: true },
                  },
                ],
              }),
            ],
            snapshot: {
              ...base.snapshot,
              ...definition.capabilities,
              adaptation: profile.ok.adaptation,
              providers: profile.ok.providers,
              allowFallback: false,
            },
          }
          for (let round = 0; round < 3; round++) {
            const planned = await transport.plan(request, { signal: new AbortController().signal })
            if (!('planned' in planned)) throw Error(JSON.stringify(planned))
            expect(planned.planned.measurement.mode).toBe(round === 0 ? 'full' : 'marginal')
            if (round === 0)
              expect(planned.planned.body.cache_control).toEqual({ type: 'ephemeral', ttl: '1h' })
            const actual = await invokeModel({
              ...request,
              transport,
              credential: 'synthetic-local-only',
              signal: new AbortController().signal,
              policy: policy(),
              onAccepted() {},
            }).outcome
            if (!('outcome' in actual) || actual.outcome !== 'complete')
              throw Error(JSON.stringify(actual))
            expect(actual.inputCalibration.observedInput.kind).toBe('from_usage')
            expect(actual.usage.output_tokens).toBe(31)
            const selection = actual.blocks.map((_, index) => ({
              sourceBlockIndex: index,
              messageIndex: request.messages.length,
              blockIndex: index,
            }))
            const history: PlanOutputHistoryGroup = {
              inputCalibration: actual.inputCalibration,
              usage: actual.usage,
              outputBlocks: actual.blocks,
              replaySelection: selection,
              origin: {
                adaptation: request.snapshot.adaptation,
                provider: 'anthropic',
                parameters: planned.planned.parameters,
                servingProvider: 'Anthropic',
                upstreamModel: definition.modelId,
              },
            }
            const reply = judgedMessage({
              type: 'assistant',
              id: `a${round}`,
              response: `r${round}`,
              ending: 'complete',
              createdAt: at,
              blocks: actual.blocks,
            })
            request = {
              ...request,
              outputHistory: [...request.outputHistory, history],
              calibration: {
                kind: 'observation',
                inputCalibration: actual.inputCalibration,
                usage: actual.usage,
                outputBlocks: actual.blocks,
                replaySelection: selection,
              },
              messages: [...request.messages, reply, message('user', `next ${round}`, `u${round}`)],
            }
            if (round === 0) {
              const invoke = (candidate: PlanInput) =>
                invokeModel({
                  ...candidate,
                  transport,
                  credential: 'synthetic-local-only',
                  signal: new AbortController().signal,
                  policy: policy(),
                  onAccepted() {},
                }).outcome
              if (
                anthropicReplayModels.find(row => row.modelId === definition.modelId)
                  ?.requiresSignedPrefix
              ) {
                for (const parameters of [
                  { ...request.parameters, reasoningEffort: 'low' as const },
                  { ...request.parameters, maxOutputTokens: 256 },
                ]) {
                  const failed = await invoke({ ...request, parameters })
                  expect(failed).toEqual({
                    rejected: 'invalidInput',
                    reason: 'input_size_unavailable',
                    metrics: ['maxInputTokens'],
                  })
                  expect(host.requests).toHaveLength(1)
                }
              }
              // A contradictory retained origin is truly malformed, unlike a
              // valid change whose required contribution cannot be measured.
              const bad = { ...history, origin: { ...history.origin!, provider: 'unrelated' } }
              expect(await invoke({ ...request, outputHistory: [bad] })).toEqual({
                rejected: 'invalidInput',
                reason: 'malformed',
              })
              expect(host.requests).toHaveLength(1)
            }
          }
          expect(host.requests).toHaveLength(3)
          expect(host.requests[1]?.body).toContain('signature-1')
          expect(host.requests[2]?.body).toContain('encrypted-2')
        } finally {
          release()
          await ctx.fiber.dispose()
          await service.close(retirement)
          await direct.close()
          await host.close()
        }
      })
  },
)

tests/anthropic-input-meter.spec.ts.source:
import { testImagePreparerFor, imagePreparation } from './image-transport-support.ts'
import { directFull } from './direct-full-input.ts'
import { readFileSync } from 'node:fs'
import { describe, expect, it } from 'vitest'
import { ExactDecimal } from '@omne-harness-lite/call-accounts'
import {
  isJsonNumber,
  readJsonStrict,
  writeJsonLossless,
  type JsonObject,
} from '@omne-harness-lite/content-blocks'
import { invokeModel, type PlanInput } from '@omne-harness-lite/model-request-runtime'
import type { ModelToolEntry } from '@omne-harness-lite/tool-definition'
import { createOfficialProfileContent } from '../src/configuration.ts'
import { createAnthropicInputMeter } from '../src/input-meters/anthropic.ts'
import { object } from '../src/json.ts'
import { anthropicDefinitions } from '../src/official-models/anthropic.ts'
import { planRequest } from '../src/plan.ts'
import { createPiAiTransport } from '../src/transport.ts'
import {
  at,
  certificate,
  content,
  finish,
  fixture as httpsFixture,
  input as testInput,
  judgedMessage,
  message,
  policy,
  sse,
} from './support.ts'

const modelIds = [
  'anthropic/claude-opus-5.5',
  'anthropic/claude-opus-5',
  'anthropic/claude-sonnet-5',
  'anthropic/claude-fable-5.1',
]

function definition(modelId: string) {
  const found = anthropicDefinitions.find(item => item.modelId === modelId)
  if (!found) throw new Error(`missing Anthropic definition: ${modelId}`)
  return found
}

function measuredTokens(modelId: string, body: JsonObject) {
  const result = directFull(createAnthropicInputMeter(definition(modelId)), {
    body,
    serialized: writeJsonLossless(body),
  })
  if (result.kind !== 'estimated') throw new Error('expected rough Anthropic estimate')
  return Number(result.tokens)
}

describe('four exact Anthropic projected-input rough estimates', () => {
  it('matches an external-tokenizer fixture for full text/tool history with cache marker', () => {
    const parsed = readJsonStrict(
      readFileSync(new URL('./fixtures/anthropic/reference-input.json', import.meta.url), 'utf8'),
    )
    if (!('ok' in parsed) || !object(parsed.ok) || !object(parsed.ok.body))
      throw new Error('invalid Anthropic reference fixture')
    const { body, referenceTokens } = parsed.ok
    if (!isJsonNumber(referenceTokens)) throw new Error('missing reference token count')
    const result = directFull(createAnthropicInputMeter(definition('anthropic/claude-opus-5.5')), {
      body,
      serialized: writeJsonLossless(body),
    })
    if (result.kind !== 'estimated') throw new Error('reference input became unmeasurable')
    expect(ExactDecimal.from(result.tokens).compare(ExactDecimal.from(referenceTokens))).toBe(0)
  })

  it('matches independently run @anthropic-ai/tokenizer 0.0.4 on the projected input', () => {
    const model = modelIds[0]
    if (!model) throw new Error('missing model')
    // Independently run @anthropic-ai/tokenizer 0.0.4 on the canonical
    // {messages:[{role:'user',content:text}]} projection: 18, 21 and 32.
    const vectors = [
      ['Hello, 世界!', 18],
      ['{"role":"user","content":"hello"}', 21],
      ['{"role":"tool","tool_call_id":"call_1","content":"sunny"}', 32],
    ] as const
    for (const [text, expected] of vectors) {
      const body = {
        model,
        provider: { order: ['anthropic'], allow_fallbacks: false, require_parameters: true },
        messages: [{ role: 'user', content: text }],
      }
      expect(measuredTokens(model, body)).toBe(expected)
    }
  })

  it('binds only the four explicit definitions and selected Anthropic provider', () => {
    for (const modelId of modelIds) {
      const meter = createAnthropicInputMeter(definition(modelId))
      expect(meter).toMatchObject({ modelId, definitionRevision: '4', provider: 'anthropic' })
      expect(meter.algorithmRevision).toBe(
        'anthropic-legacy-bpe-plus-vision-patches-complete-output-5/response-calibration-1',
      )
      expect(meter.evidence).toContain('very rough approximation')
    }
    expect(() =>
      createAnthropicInputMeter({ ...definition(modelIds[0] ?? ''), revision: '2' }),
    ).toThrow(TypeError)
    expect(() =>
      createAnthropicInputMeter({
        ...definition(modelIds[0] ?? ''),
        implementation: { name: 'pi-ai:anthropic', revision: 'mp4-1' },
      }),
    ).toThrow(TypeError)
    expect(() =>
      createAnthropicInputMeter({ ...definition(modelIds[0] ?? ''), routes: {} }),
    ).toThrow(TypeError)
    expect(() =>
      createAnthropicInputMeter({ ...definition(modelIds[0] ?? ''), modelId: 'anthropic/unknown' }),
    ).toThrow(TypeError)
    const selected = definition(modelIds[0] ?? '')
    const route = selected.routes.anthropic
    if (!route) throw new Error('missing selected Anthropic route')
    expect(() =>
      createAnthropicInputMeter({
        ...selected,
        routes: { anthropic: { ...route, cache: { mode: 'automatic' } } },
      }),
    ).toThrow(TypeError)
  })

  it.each(modelIds)('%s validates cache markers against its bound route declaration', model => {
    const selected = definition(model)
    const cache = selected.routes.anthropic?.cache
    if (cache?.mode !== 'explicit') throw new Error('missing explicit Anthropic cache policy')
    expect(cache.ttlValues).toEqual(['1h'])
    const ttl = cache.ttlValues[0]
    if (!ttl) throw new Error('missing declared Anthropic TTL')
    const base = {
      model,
      provider: { order: ['anthropic'], allow_fallbacks: false, require_parameters: true },
      messages: [{ role: 'user', content: [{ type: 'text', text: 'Reuse this exact text.' }] }],
    }
    const marked = {
      ...base,
      messages: [
        {
          role: 'user',
          content: [
            {
              type: 'text',
              text: 'Reuse this exact text.',
              cache_control: { type: 'ephemeral', ttl },
            },
          ],
        },
      ],
    }
    expect(measuredTokens(model, marked)).toBe(measuredTokens(model, base))
    const unsupported = {
      ...marked,
      messages: [
        {
          role: 'user',
          content: [
            {
              type: 'text',
              text: 'Reuse this exact text.',
              cache_control: { type: 'ephemeral', ttl: '5m' },
            },
          ],
        },
      ],
    }
    expect(
      directFull(createAnthropicInputMeter(selected), {
        body: unsupported,
        serialized: writeJsonLossless(unsupported),
      }),
    ).toEqual({ kind: 'unavailable' })
  })

  it('counts complete text, tools, results and reminder while excluding request controls', () => {
    const model = modelIds[0]
    if (!model) throw new Error('missing model')
    const body = {
      model,
      provider: { order: ['anthropic'], allow_fallbacks: false, require_parameters: true },
      stream: true,
      store: false,
      reasoning: { effort: 'high' },
      messages: [
        { role: 'system', content: [{ type: 'text', text: 'Read the weather.' }] },
        {
          role: 'user',
          content: [{ type: 'text', text: '[system_reminder "r"] keep going' }],
        },
        { role: 'user', content: [{ type: 'text', text: 'What is it?' }] },
        {
          role: 'assistant',
          content: '',
          tool_calls: [
            {
              id: 'call_1',
              type: 'function',
              function: { name: 'weather', arguments: '{"city":"Paris"}' },
            },
          ],
        },
        { role: 'tool', tool_call_id: 'call_1', content: 'Sunny, 22 C' },
        {
          role: 'user',
          content: [
            { type: 'text', text: 'Tomorrow?', cache_control: { type: 'ephemeral', ttl: '1h' } },
          ],
        },
      ],
      tools: [
        {
          type: 'function',
          function: {
            name: 'weather',
            description: 'Read forecasts',
            parameters: { type: 'object', properties: { city: { type: 'string' } } },
          },
        },
      ],
    }
    const complete = measuredTokens(model, body)
    expect(complete).toBeGreaterThan(0)
    expect(measuredTokens(model, { ...body, tools: [] })).not.toBe(complete)
    expect(
      measuredTokens(model, {
        ...body,
        messages: body.messages.filter(message => message.role !== 'tool'),
      }),
    ).not.toBe(complete)
    expect(
      measuredTokens(model, {
        ...body,
        messages: body.messages.filter(message => message.role !== 'assistant'),
      }),
    ).not.toBe(complete)
    expect(
      measuredTokens(model, {
        ...body,
        messages: body.messages.filter(message => message.role !== 'user'),
      }),
    ).not.toBe(complete)
    const { reasoning: _reasoning, ...withoutReasoning } = body
    expect(measuredTokens(model, withoutReasoning)).toBe(complete)
    expect(
      measuredTokens(model, {
        ...body,
        max_tokens: 123456,
        stop: ['A long stop sequence that is not prompt input'],
        reasoning: { effort: 'max' },
        stream: false,
        store: true,
      }),
    ).toBe(complete)
    expect(
      measuredTokens(model, {
        ...body,
        messages: body.messages.map(message =>
          message.role === 'user' && Array.isArray(message.content)
            ? {
                ...message,
                content: message.content.map(part =>
                  'cache_control' in part ? { type: 'text', text: part.text } : part,
                ),
              }
            : message,
        ),
      }),
    ).toBe(complete)
    const meter = createAnthropicInputMeter(definition(model))
    expect(directFull(meter, { body, serialized: '{}' })).toEqual({ kind: 'unavailable' })
    expect(
      directFull(meter, {
        body: { ...body, model: 'anthropic/other' },
        serialized: writeJsonLossless({ ...body, model: 'anthropic/other' }),
      }),
    ).toEqual({ kind: 'unavailable' })
    for (const unknownInput of [
      {
        ...body,
        provider: { order: ['other'], allow_fallbacks: false, require_parameters: true },
      },
      { ...body, tool_choice: { type: 'function', function: { name: 'weather' } } },
      { ...body, messages: [...body.messages, { role: 'user', content: 'x', name: 'alice' }] },
      { ...body, tools: [{ type: 'function', function: { name: 'weather', prompt: 'hidden' } }] },
    ]) {
      expect(
        directFull(meter, { body: unknownInput, serialized: writeJsonLossless(unknownInput) }),
      ).toEqual({ kind: 'unavailable' })
    }
  })

  it('refuses unbacked reasoning details while preserving independent plain reasoning', () => {
    for (const model of modelIds) {
      const textBody = {
        model,
        provider: { order: ['anthropic'], allow_fallbacks: false, require_parameters: true },
        messages: [
          { role: 'assistant', content: '', reasoning: 'Need to check the result.' },
          { role: 'user', content: 'Continue.' },
        ],
      }
      expect(measuredTokens(model, textBody)).toBeGreaterThan(0)
      const unsigned = {
        ...textBody,
        messages: [
          {
            role: 'assistant',
            content: '',
            reasoning_details: [{ type: 'reasoning.text', text: 'The result is valid.' }],
          },
        ],
      }
      expect(
        directFull(createAnthropicInputMeter(definition(model)), {
          body: unsigned,
          serialized: writeJsonLossless(unsigned),
        }),
      ).toEqual({ kind: 'unavailable' })
      const body = {
        model,
        messages: [
          {
            role: 'assistant',
            content: '',
            reasoning_details: [{ type: 'reasoning.encrypted', signature: 'opaque-ciphertext' }],
          },
          { role: 'user', content: 'Continue.' },
        ],
      }
      expect(
        directFull(createAnthropicInputMeter(definition(model)), {
          body,
          serialized: writeJsonLossless(body),
        }),
      ).toEqual({ kind: 'unavailable' })
    }
  })

  it('matches the published high-resolution visual-token example plus independent BPE frame', () => {
    const image = readFileSync(
      new URL('./fixtures/anthropic/reference-green-1920x1080.png', import.meta.url),
    )
    for (const model of modelIds) {
      const body = {
        model,
        provider: { order: ['anthropic'], allow_fallbacks: false, require_parameters: true },
        messages: [
          {
            role: 'user',
            content: [
              {
                type: 'image_url',
                image_url: { url: `data:image/png;base64,${image.toString('base64')}` },
              },
            ],
          },
        ],
      }
      // Anthropic Vision: 1920x1080 high-resolution = 2691 patches;
      // @anthropic-ai/tokenizer 0.0.4: projected frame with [image] = 27.
      expect(measuredTokens(model, body)).toBe(2718)
    }
  })

  it('uses the first GIF frame and refuses a false image MIME declaration', () => {
    const image = readFileSync(
      new URL('./fixtures/anthropic/reference-single-frame.gif', import.meta.url),
    )
    const url = `data:image/gif;base64,${image.toString('base64')}`
    for (const model of modelIds) {
      const body = {
        model,
        provider: { order: ['anthropic'], allow_fallbacks: false, require_parameters: true },
        messages: [{ role: 'user', content: [{ type: 'image_url', image_url: { url } }] }],
      }
      expect(measuredTokens(model, body)).toBe(28)
      const wrongMime = {
        ...body,
        messages: [
          {
            role: 'user',
            content: [
              { type: 'image_url', image_url: { url: url.replace('image/gif', 'image/png') } },
            ],
          },
        ],
      }
      expect(
        directFull(createAnthropicInputMeter(definition(model)), {
          body: wrongMime,
          serialized: writeJsonLossless(wrongMime),
        }),
      ).toEqual({ kind: 'unavailable' })
    }
  })

  it('refuses malformed image, unsupported media and unknown content blocks', () => {
    for (const model of modelIds) {
      const body = {
        model,
        provider: { order: ['anthropic'], allow_fallbacks: false, require_parameters: true },
        messages: [
          {
            role: 'user',
            content: [{ type: 'image_url', image_url: { url: 'data:image/png;base64,aGVsbG8=' } }],
          },
        ],
      }
      expect(
        directFull(createAnthropicInputMeter(definition(model)), {
          body,
          serialized: writeJsonLossless(body),
        }),
      ).toEqual({ kind: 'unavailable' })
      const unknown = {
        ...body,
        messages: [{ role: 'user', content: [{ type: 'audio_url', audio_url: { url: 'x' } }] }],
      }
      expect(
        directFull(createAnthropicInputMeter(definition(model)), {
          body: unknown,
          serialized: writeJsonLossless(unknown),
        }),
      ).toEqual({ kind: 'unavailable' })
    }
  })

  it('admits a real final plan with explicit caller margin and cache marker', async () => {
    const selected = definition(modelIds[0] ?? '')
    const configuration = {
      revision: '1',
      values: { cache: { mode: 'explicit', ttl: '1h', breakpoints: ['last_message'] } },
    }
    const profile = createOfficialProfileContent(selected, {
      providers: ['anthropic'],
      allowFallback: false,
      configuration,
    })
    if ('rejected' in profile) throw new Error(profile.rejected)
    const request = testInput()
    const input = {
      ...request,
      routeName: selected.modelId,
      provider: 'anthropic',
      calibration: { kind: 'none' as const, reason: 'no_observation' as const },
      tokenMargin: { multiplier: 1.2, reserveTokens: 32 },
      snapshot: {
        ...request.snapshot,
        adaptation: profile.ok.adaptation,
        providers: profile.ok.providers,
        allowFallback: profile.ok.allowFallback,
        inputModalities: profile.ok.inputModalities,
        outputModalities: profile.ok.outputModalities,
        maxInputTokens: profile.ok.maxInputTokens,
        maxOutputTokens: profile.ok.maxOutputTokens,
        inputConstraints: profile.ok.inputConstraints,
        upstreamInputLimits: profile.ok.upstreamInputLimits,
      },
    }
    const meter = createAnthropicInputMeter(selected)
    const planned = await planRequest(
      input,
      [selected],
      meter,
      {
        signal: new AbortController().signal,
      },
      testImagePreparerFor(planRequest),
    )
    if ('rejected' in planned) throw new Error(JSON.stringify(planned))
    expect(planned.planned.body.messages).toContainEqual({
      role: 'user',
      content: [
        { type: 'text', text: '[system_reminder "system_reminder"]' },
        { type: 'text', text: 'keep going' },
      ],
    })
    expect(planned.planned.serialized).toContain('cache_control')
    expect(planned.planned.inputLimitEvidence.inputTokens.kind).toBe('estimated')
    expect(planned.planned.inputLimitEvidence.tokenMargin).toEqual({
      multiplier: 1.2,
      reserveTokens: 32,
    })
    expect(planned.planned.inputLimitEvidence.requestBytes).toBe(
      Buffer.byteLength(planned.planned.serialized),
    )
    const controlled = await planRequest(
      { ...input, parameters: { reasoningEffort: 'low', maxOutputTokens: 10 } },
      [selected],
      meter,
      { signal: new AbortController().signal },
      testImagePreparerFor(planRequest),
    )
    const controlledAgain = await planRequest(
      { ...input, parameters: { reasoningEffort: 'max', maxOutputTokens: 100 } },
      [selected],
      meter,
      { signal: new AbortController().signal },
      testImagePreparerFor(planRequest),
    )
    if ('rejected' in controlled || 'rejected' in controlledAgain)
      throw new Error('valid Anthropic generation controls rejected')
    expect(controlled.planned.serialized).not.toBe(controlledAgain.planned.serialized)
    expect(measuredTokens(selected.modelId, controlled.planned.body)).toBe(
      measuredTokens(selected.modelId, controlledAgain.planned.body),
    )
    const exceeded = await planRequest(
      { ...input, tokenMargin: { multiplier: 1, reserveTokens: 872000 } },
      [selected],
      meter,
      { signal: new AbortController().signal },
      testImagePreparerFor(planRequest),
    )
    expect(exceeded).toMatchObject({
      rejected: 'invalidInput',
      reason: 'input_limit_exceeded',
      basis: 'estimated',
      metric: 'maxInputTokens',
    })
    const inline = readFileSync(new URL('./fixtures/anthropic/reference-1x1.png', import.meta.url))
    const visual = judgedMessage({
      type: 'user',
      id: 'visual',
      createdAt: at,
      blocks: [
        {
          id: 'visual-image',
          kind: 'image',
          mediaType: 'image/png',
          data: { inline: inline.toString('base64') },
          visibility: { toHuman: true, toModel: true },
        },
      ],
    })
    const imagePlan = await planRequest(
      { ...input, messages: [...input.messages, visual] },
      [selected],
      meter,
      { signal: new AbortController().signal },
      testImagePreparerFor(planRequest),
    )
    if ('rejected' in imagePlan) throw new Error(JSON.stringify(imagePlan))
    expect(imagePlan.planned.inputLimitEvidence.inputTokens.kind).toBe('estimated')
    expect(imagePlan.planned.inputLimitEvidence.images).toBe(1)
    expect(imagePlan.planned.inputLimitEvidence.imageBytes).toEqual([inline.byteLength])
    const encryptedReplay = judgedMessage({
      type: 'assistant',
      id: 'opaque-assistant',
      response: 'previous-response',
      ending: 'complete',
      createdAt: at,
      blocks: [
        {
          id: 'opaque-thinking',
          kind: 'thinking',
          text: '',
          opaque: {
            routeName: selected.modelId,
            reasoning_details: [{ type: 'reasoning.encrypted', data: 'opaque-ciphertext' }],
          },
          visibility: { toHuman: false, toModel: true },
        },
        {
          id: 'opaque-answer',
          kind: 'text',
          text: 'Previous answer',
          visibility: { toHuman: true, toModel: true },
        },
      ],
    })
    expect(
      await planRequest(
        { ...input, messages: [...input.messages, encryptedReplay, message('user', 'Continue?')] },
        [selected],
        meter,
        { signal: new AbortController().signal },
        testImagePreparerFor(planRequest),
      ),
    ).toMatchObject({
      rejected: 'invalidInput',
      reason: 'input_size_unavailable',
      metrics: ['maxInputTokens'],
    })
  })

  it.each(modelIds)(
    '%s sends the measured final text/tool request through the public factory',
    async modelId => {
      const selected = definition(modelId)
      const meter = createAnthropicInputMeter(selected)
      const configuration = {
        revision: 'factory-1',
        values: { cache: { mode: 'explicit', ttl: '1h', breakpoints: ['last_message'] } },
      }
      const profile = createOfficialProfileContent(selected, {
        providers: ['anthropic'],
        allowFallback: false,
        configuration,
      })
      if ('rejected' in profile) throw new Error(profile.rejected)
      const tool: ModelToolEntry = {
        name: 'lookup',
        description: 'Look up a forecast',
        parameters: {
          type: 'object',
          properties: { city: { type: 'string' } },
          required: ['city'],
          additionalProperties: false,
        },
      }
      const assistant = judgedMessage({
        type: 'assistant',
        id: 'previous-assistant',
        response: 'previous-response',
        ending: 'complete',
        createdAt: at,
        blocks: [
          {
            id: 'previous-call',
            kind: 'tool_call',
            callId: 'call_1',
            tool: 'lookup',
            complete: true,
            unparseable: true,
            rawArguments: '{"city":"Paris"}',
            visibility: { toHuman: true, toModel: true },
          },
        ],
      })
      const image = readFileSync(new URL('./fixtures/anthropic/reference-1x1.png', import.meta.url))
      const toolResult = judgedMessage({
        type: 'tool',
        id: 'previous-result',
        callId: 'call_1',
        createdAt: at,
        blocks: [
          {
            id: 'previous-result-block',
            kind: 'tool_result',
            callId: 'call_1',
            outcome: 'completed',
            visibility: { toHuman: true, toModel: true },
            blocks: [
              {
                id: 'previous-result-text',
                kind: 'text',
                text: 'Sunny in Paris',
                visibility: { toHuman: true, toModel: true },
              },
              {
                id: 'previous-result-image',
                kind: 'image',
                mediaType: 'image/png',
                data: { inline: image.toString('base64') },
                visibility: { toHuman: true, toModel: true },
              },
            ],
          },
        ],
      })
      const visual = judgedMessage({
        type: 'user',
        id: 'prior-visual',
        createdAt: at,
        blocks: [
          {
            id: 'prior-image',
            kind: 'image',
            mediaType: 'image/png',
            data: { inline: image.toString('base64') },
            visibility: { toHuman: true, toModel: true },
          },
        ],
      })
      const base = testInput()
      const input: PlanInput = {
        ...base,
        routeName: modelId,
        provider: 'anthropic',
        parameters: { reasoningEffort: 'high', maxOutputTokens: 64 },
        calibration: { kind: 'none' as const, reason: 'no_observation' as const },
        tokenMargin: { multiplier: 1.2, reserveTokens: 32 },
        tools: [tool],
        messages: [
          ...base.messages,
          visual,
          assistant,
          toolResult,
          message('user', 'And tomorrow?', 'tomorrow'),
        ],
        snapshot: {
          ...base.snapshot,
          adaptation: profile.ok.adaptation,
          providers: profile.ok.providers,
          allowFallback: profile.ok.allowFallback,
          inputModalities: profile.ok.inputModalities,
          outputModalities: profile.ok.outputModalities,
          maxInputTokens: profile.ok.maxInputTokens,
          maxOutputTokens: profile.ok.maxOutputTokens,
          inputConstraints: profile.ok.inputConstraints,
          upstreamInputLimits: profile.ok.upstreamInputLimits,
        },
      }
      const cert = certificate()
      const host = await httpsFixture(
        cert.tls,
        res =>
          res.end(
            content('Forecast ready') +
              sse({
                choices: [],
                usage: {
                  prompt_tokens: 100,
                  completion_tokens: 3,
                  prompt_tokens_details: { cached_tokens: 20, cache_write_tokens: 5 },
                },
              }) +
              finish(),
          ),
        {},
        undefined,
        [selected],
      )
      const transport = createPiAiTransport({
        ...host.options,
        definitions: [selected],
        inputMeters: [meter],
      })
      try {
        const planned = await transport.plan(input, { signal: new AbortController().signal })
        if ('rejected' in planned) throw new Error(JSON.stringify(planned))
        expect(planned.planned.inputLimitEvidence.inputTokens.kind).toBe('estimated')
        expect(planned.planned.inputLimitEvidence.images).toBe(2)
        const handle = invokeModel({
          ...input,
          transport,
          credential: 'synthetic-credential',
          signal: new AbortController().signal,
          policy: policy(),
          onAccepted: () => {},
        })
        const result = await handle.outcome
        if (!('outcome' in result)) throw new Error(JSON.stringify(result))
        expect(result.outcome).toBe('complete')
        if (result.usage.input_tokens === 'unknown') throw new Error('missing upstream input usage')
        expect(ExactDecimal.from(result.usage.input_tokens).compare(ExactDecimal.from(75))).toBe(0)
        expect(result.usage).toMatchObject({
          cache_read_tokens: 20,
          cache_write_tokens: 5,
          output_tokens: 3,
        })
        expect(host.requests).toHaveLength(1)
        expect(host.requests[0]?.body).toBe(planned.planned.serialized)
        const observed = readJsonStrict(host.requests[0]?.body ?? '')
        if (!('ok' in observed)) throw new Error('invalid captured request')
        expect(observed.ok).toMatchObject({
          model: modelId,
          provider: { order: ['anthropic'], allow_fallbacks: false, require_parameters: true },
          reasoning: { effort: 'high' },
          max_tokens: 64,
          tools: [{ function: { name: 'lookup', parameters: tool.parameters } }],
          messages: [
            { role: 'system' },
            { role: 'user' },
            { role: 'user' },
            {
              role: 'user',
              content: [
                {
                  type: 'image_url',
                  image_url: { url: `data:image/png;base64,${image.toString('base64')}` },
                },
              ],
            },
            { role: 'assistant', tool_calls: [{ id: 'call_1' }] },
            {
              role: 'tool',
              tool_call_id: 'call_1',
              content: [{ type: 'text', text: 'Sunny in Paris' }],
            },
            {
              role: 'user',
              content: [
                {
                  type: 'image_url',
                  image_url: { url: `data:image/png;base64,${image.toString('base64')}` },
                },
              ],
            },
            {
              role: 'user',
              content: [
                {
                  type: 'text',
                  text: 'And tomorrow?',
                  cache_control: { type: 'ephemeral', ttl: '1h' },
                },
              ],
            },
          ],
        })
      } finally {
        await transport.close()
        await host.close()
        cert.dispose()
      }
    },
  )
})

