      expect(await observed).toEqual({ rejected: { reason: 'aborted' } })
      await closing
      if (stage !== 'inspect') expect(decodedClosed).toBe(true)
      expect(closeCalls).toBe(stage === 'inspect' ? 0 : 1)
    }
  })
})

