import { describe, expect, it } from 'vitest'
import { readModelDefinition, type ModelDefinition, type ModelRoute } from '../src/definitions.ts'
import { officialModelIds } from '../src/official.ts'
import { anthropicDefinitions, anthropicModelRoutes } from '../src/official-models/anthropic.ts'
import {
  deepseekDefinitions,
  deepseekModelRoutes,
  deepseekV4Pro0813Definition,
} from '../src/official-models/deepseek.ts'
import { googleDefinitions, googleModelRoutes } from '../src/official-models/google.ts'
import { moonshotDefinitions, moonshotModelRoutes } from '../src/official-models/moonshot.ts'
import { openaiDefinitions, openaiModelRoutes } from '../src/official-models/openai.ts'
import { qwenDefinitions, qwenModelRoutes } from '../src/official-models/qwen.ts'
import { xaiDefinitions, xaiModelRoutes } from '../src/official-models/xai.ts'
import { zaiDefinitions, zaiModelRoutes } from '../src/official-models/zai.ts'

const families: Readonly<Record<string, Readonly<Record<string, ModelDefinition['routes']>>>> = {
  anthropic: anthropicModelRoutes,
  deepseek: deepseekModelRoutes,
  google: googleModelRoutes,
  moonshot: moonshotModelRoutes,
  openai: openaiModelRoutes,
  qwen: qwenModelRoutes,
  xai: xaiModelRoutes,
  zai: zaiModelRoutes,
}
const completeFamilies = [
  anthropicDefinitions,
  deepseekDefinitions,
  googleDefinitions,
  moonshotDefinitions,
  openaiDefinitions,
  qwenDefinitions,
  xaiDefinitions,
  zaiDefinitions,
]

// Exact binding inventory independently of family policy composition. These
// fixed providers must not turn into model-prefix inference or route fallback.
const providers: Readonly<Record<string, readonly string[]>> = {
  anthropic: ['anthropic'],
  deepseek: ['deepinfra/fp8'],
  google: ['google-ai-studio', 'google-vertex'],
  openai: ['openai'],
  qwen: ['alibaba'],
  xai: ['xai'],
}

function expectedProviders(family: string, modelId: string): readonly string[] {
  if (family === 'moonshot') {
    return modelId === 'moonshotai/kimi-k3' ? ['moonshotai/mxfp4'] : ['moonshotai/int4']
  }
  if (family === 'zai') return modelId === 'z-ai/glm-5.3-prime' ? ['alibaba'] : ['z-ai/fp8']
  const result = providers[family]
  if (!result) throw new Error(`missing provider expectation for ${family}`)
  return result
}

// Synthetic capacities exercise the common definition reader only; they are
// not published as real model capabilities or used for upstream requests.
function fixture(modelId: string, routes: Readonly<Record<string, ModelRoute>>): ModelDefinition {
  return {
    modelId,
    revision: '1',
    implementation: { name: 'test:family-layout', revision: '1' },
    capabilities: {
      inputModalities: ['text'],
      outputModalities: ['text'],
      maxInputTokens: 1024,
      maxOutputTokens: 128,
      inputConstraints: {},
      upstreamInputLimits: {
        maxInputTokens: { status: 'unknown' },
        maxRequestBytes: { status: 'unknown' },
      },
    },
    routes,
  }
}

describe('uniform family model/provider route maps', () => {
  it('covers every confirmed model exactly once, with explicit provider bindings', () => {
    const ids = Object.values(families).flatMap(models => Object.keys(models))
    expect(ids).toHaveLength(37)
    expect(new Set(ids).size).toBe(ids.length)
    expect(ids.toSorted()).toEqual([...officialModelIds].sort())
    let routeCount = 0
    for (const [family, models] of Object.entries(families)) {
      for (const [modelId, routes] of Object.entries(models)) {
        expect(Object.keys(routes).sort()).toEqual([...expectedProviders(family, modelId)].sort())
        routeCount += Object.keys(routes).length
        for (const route of Object.values(routes)) {
          expect(route.reminderRole).toBe(family === 'openai' ? 'developer' : 'user')
        }
      }
    }
    expect(routeCount).toBe(39)
  })

  it.each(Object.entries(families))(
    '%s composes through the same complete-definition reader',
    (_family, models) => {
      for (const [modelId, routes] of Object.entries(models)) {
        const declaration = fixture(modelId, routes)
        expect(
          readModelDefinition([declaration], {
            implementation: declaration.implementation,
            definition: { modelId, revision: declaration.revision },
          }),
        ).toEqual({ ok: declaration })
      }
    },
  )

  it('keeps the complete DeepSeek Pro definition bound to the family map', () => {
    expect(deepseekV4Pro0813Definition.routes).toEqual(
      deepseekModelRoutes['deepseek/deepseek-v4-pro-0813'],
    )
  })

  it('publishes precisely the 37 complete six-field definitions through the same reader', () => {
    const definitions = completeFamilies.flat()
    expect(definitions).toHaveLength(37)
    expect(new Set(definitions.map(value => value.modelId)).size).toBe(37)
    expect(definitions.map(value => value.modelId).toSorted()).toEqual([...officialModelIds].sort())
    for (const definition of definitions) {
      expect(Object.keys(definition.capabilities).sort()).toEqual(
        [
          'inputModalities',
          'outputModalities',
          'maxInputTokens',
          'maxOutputTokens',
          'inputConstraints',
          'upstreamInputLimits',
        ].sort(),
      )
      expect(
        readModelDefinition(definitions, {
          implementation: definition.implementation,
          definition: { modelId: definition.modelId, revision: definition.revision },
        }),
      ).toEqual({ ok: definition })
    }
  })
})

tests/official-google-definitions.spec.t.source:
import { describe, expect, it } from 'vitest'
import { judgeModelProfileDocument } from '@omne-harness-lite/model-profile'
import {
  configurationSchema,
  createOfficialProfileContent,
  interpretConfiguration,
  readModelDefinition,
} from '../src/index.ts'
import { ownDefinitions } from '../src/definitions.ts'
import { googleDefinitions, googleModelRoutes } from '../src/official-models/google.ts'

const ids = ['google/gemini-3.8-flash', 'google/gemini-3.7-flash'] as const
const configuration = { revision: '1', values: { cache: { mode: 'automatic' } } } as const

describe('complete Google Flash declarations', () => {
  it('publishes precisely two selected Google AI Studio definitions with complete MP4 facts', () => {
    expect(googleDefinitions.map(definition => definition.modelId)).toEqual(ids)
    for (const id of ids) {
      const definition = googleDefinitions.find(item => item.modelId === id)
      if (!definition) throw new Error(`Google definition missing: ${id}`)
      expect(definition.implementation).toEqual({ name: 'pi-ai:google', revision: 'mp4-17' })
      expect(definition.revision).toBe('3')
      expect(Object.keys(definition.routes)).toEqual(['google-ai-studio'])
      expect(definition.routes['google-ai-studio']).toEqual(
        googleModelRoutes[id]['google-ai-studio'],
      )
      expect(Object.keys(googleModelRoutes[id]).sort()).toEqual([
        'google-ai-studio',
        'google-vertex',
      ])
      expect(definition.capabilities).toEqual({
        inputModalities: ['audio', 'image', 'text', 'video'],
        outputModalities: ['text'],
        maxInputTokens: 983040,
        maxOutputTokens: 65536,
        inputConstraints: { maxImageBytes: 4194304 },
        upstreamInputLimits: {
          maxInputTokens: { status: 'unknown' },
          maxRequestBytes: { status: 'unknown' },
          maxImageBytes: { status: 'unknown' },
          maxImages: { status: 'unknown' },
        },
      })
    }
  })

  it.each(ids)(
    '%s reads by full identity and constructs the same complete official content',
    id => {
      const found = readModelDefinition(googleDefinitions, {
        implementation: { name: 'pi-ai:google', revision: 'mp4-17' },
        definition: { modelId: id, revision: '3' },
      })
      if ('rejected' in found) throw new Error(found.rejected)
      const profile = createOfficialProfileContent(found.ok, {
        providers: ['google-ai-studio'],
        allowFallback: false,
        configuration,
      })
      if ('rejected' in profile) throw new Error(profile.rejected)
      expect(profile.ok.routeName).toBe(id)
      expect(profile.ok.origin).toBe('official')
      expect(profile.ok.providers).toEqual(['google-ai-studio'])
      expect(profile.ok.allowFallback).toBe(false)
      expect(profile.ok.adaptation).toEqual({
        implementation: found.ok.implementation,
        definition: { modelId: id, revision: '3' },
        configuration,
      })
      for (const key of [
        'inputModalities',
        'outputModalities',
        'maxInputTokens',
        'maxOutputTokens',
        'inputConstraints',
        'upstreamInputLimits',
      ] as const)
        expect(profile.ok[key]).toEqual(found.ok.capabilities[key])
      expect(judgeModelProfileDocument('ModelProfileContent', profile.ok)).toHaveProperty('ok')
    },
  )

  it('uses caller-supplied automatic cache configuration without a TTL or fallback provider', () => {
    for (const definition of googleDefinitions) {
      expect(interpretConfiguration(definition, configuration.values, 'google-ai-studio')).toEqual({
        ok: { mode: 'automatic' },
      })
      expect(
        interpretConfiguration(
          definition,
          { cache: { mode: 'explicit', ttl: '1h' } },
          'google-ai-studio',
        ),
      ).toEqual({ rejected: 'invalidInput' })
      expect(interpretConfiguration(definition, configuration.values, 'google-vertex')).toEqual({
        rejected: 'unavailable',
      })
      const schema = configurationSchema(definition, 'google-ai-studio')
      if ('rejected' in schema) throw new Error(schema.rejected)
      expect(JSON.stringify(schema.ok)).not.toContain('default')
    }
  })

  it('does not turn an unknown upstream limit into an absent, unbounded, or invented finite fact', () => {
    const original = googleDefinitions[0]
    if (!original) throw new Error('Google definition missing')
    const missing = {
      ...original,
      capabilities: {
        ...original.capabilities,
        upstreamInputLimits: {
          maxInputTokens: { status: 'unknown' },
          maxRequestBytes: { status: 'unknown' },
          maxImageBytes: { status: 'unknown' },
        },
      },
    }
    expect(() => Reflect.apply(ownDefinitions, undefined, [[missing]])).toThrow(TypeError)
    expect(() =>
      Reflect.apply(ownDefinitions, undefined, [
        [
          {
            ...original,
            capabilities: {
              ...original.capabilities,
              upstreamInputLimits: {
                ...original.capabilities.upstreamInputLimits,
                maxInputTokens: { status: 'limited', value: 983039 },
              },
            },
          },
        ],
      ]),
    ).toThrow(TypeError)
    expect(original.capabilities.upstreamInputLimits.maxInputTokens).toEqual({ status: 'unknown' })
  })
})

