import { describe, expect, it } from 'vitest'
import { ExactDecimal } from '@omne-harness-lite/call-accounts'
import { toOpaqueJson, writeJsonLossless } from '@omne-harness-lite/content-blocks'
import type { PlanInput, PlanOutputHistoryGroup } from '@omne-harness-lite/model-request-runtime'
import { openAiFamilyRecords } from '../src/input-meters/openai-family-policy.ts'
import { createOpenAiInputMeter } from '../src/input-meters/openai.ts'
import { openaiDefinitions, openaiConfiguration } from '../src/official-models/openai.ts'
import { createOfficialProfileContent } from '../src/configuration.ts'
import { planRequest } from '../src/plan.ts'
import { outputBlockDigestAtRevision, projectionDigest } from '../src/projection.ts'
import { testImagePreparerFor } from './image-transport-support.ts'
import { at, input, judgedMessage, message } from './support.ts'

describe.each(Object.values(openAiFamilyRecords))(
  '$modelId finite original complete-output applicability',
  row => {
    it.each(row.original)(
      'maps original $definitionRevision/$implementationRevision to O once without a factory alias',
      async original => {
        const definition = openaiDefinitions.find(item => item.modelId === row.modelId)!
        const meter = createOpenAiInputMeter(definition)
        const profile = createOfficialProfileContent(definition, {
          providers: ['openai'],
          allowFallback: false,
          configuration: openaiConfiguration,
        })
        if ('rejected' in profile) throw Error(profile.rejected)
        const start = message('user', 'original prefix', 'u0')
        const next = message('user', 'next', 'u1')
        const reply = judgedMessage({
          type: 'assistant',
          id: 'a0',
          response: 'r0',
          ending: 'complete',
          createdAt: at,
          blocks: [
            {
              kind: 'thinking',
              id: 'reason',
              text: '',
              opaque: toOpaqueJson({
                routeName: row.modelId,
                reasoning_details: [
                  {
                    type: 'reasoning.encrypted',
                    data: 'ORIGINAL_OPAQUE',
                    format: 'openai-responses-v1',
                  },
                ],
              }),
              visibility: { toHuman: false, toModel: true },
            },
            {
              kind: 'text',
              id: 'text',
              text: 'visible answer',
              visibility: { toHuman: true, toModel: true },
            },
          ],
        })
        const base: PlanInput = {
          ...input(),
          routeName: row.modelId,
          provider: 'openai',
          parameters: { reasoningEffort: 'low', maxOutputTokens: 1024 },
          tools: [],
          messages: [start],
          snapshot: {
            ...input().snapshot,
            ...definition.capabilities,
            adaptation: profile.ok.adaptation,
            providers: ['openai'],
            allowFallback: false,
          },
        }
        const plan = (value: PlanInput) =>
          planRequest(
            value,
            [definition],
            meter,
            { signal: new AbortController().signal },
            testImagePreparerFor(planRequest),
          )
        const first = await plan(base)
        if ('rejected' in first || first.planned.requestInput.kind !== 'known')
          throw Error('fixture prefix')
        const { messages, ...envelope } = first.planned.body
        const binding = {
          ...base.snapshot.adaptation,
          definition: { modelId: row.modelId, revision: original.definitionRevision },
          implementation: { name: 'pi-ai:openai', revision: original.implementationRevision },
        }
        const history: PlanOutputHistoryGroup = {
          origin: {
            adaptation: binding,
            provider: 'openai',
            parameters: base.parameters,
            upstreamModel: row.modelId,
            servingProvider: 'OpenAI',
          },
          inputCalibration: {
            requestInput: {
              ...first.planned.requestInput,
              projectionRevision: original.projectionRevision,
              prefixDigest: projectionDigest('input-prefix', messages, original.projectionRevision),
              inputEnvelopeDigest: projectionDigest(
                'input-envelope',
                envelope,
                original.projectionRevision,
              ),
              countingBasis: {
                binding,
                model: row.modelId,
                provider: 'openai',
                meterRevision: original.algorithmRevision,
                replayRevision: original.replayRevision,
                tokenizerRevision: original.tokenizerRevision,
                transformRevision: original.transformRevision,
                projectionRevision: original.projectionRevision,
              },
            },
            observedInput:
              row.inputScope === 'scope_unknown'
                ? { kind: 'unavailable', reason: 'scope_unknown' }
                : {
                    kind: 'from_usage',
                    provenance: {
                      adapterRevision: 'openrouter-usage-reader/2',
                      fieldPaths: ['usage.prompt_tokens'],
                      upstreamModel: row.modelId,
                      servingProvider: 'OpenAI',
                    },
                  },
            outputGroup: {
              kind: 'known',
              projectionRevision: original.projectionRevision,
              source: 'reply',
              completeness: 'complete',
              usageRef: 'usage',
              blockDigests: reply.blocks.map(block =>
                outputBlockDigestAtRevision(block, original.projectionRevision),
              ),
            },
          },
          outputBlocks: reply.blocks,
          replaySelection: reply.blocks.map((_, index) => ({
            sourceBlockIndex: index,
            messageIndex: 1,
            blockIndex: index,
          })),
          usage: {
            input_tokens: 100,
            output_tokens: 18,
            reasoning_tokens: 7,
            cache_read_tokens: 0,
            cache_write_tokens: 0,
            source: 'upstream',
          },
        }
        const target = { ...base, messages: [start, reply, next], outputHistory: [history] }
        const result = await plan(target)
        const visible = await plan({ ...base, messages: [start, next] })
        if ('rejected' in result || 'rejected' in visible)
          throw Error(JSON.stringify({ result, visible }))
        expect(result.planned.measurement.mode).toBe('full')
        expect(ExactDecimal.from(result.planned.measurement.predictedInput).toString()).toBe(
          ExactDecimal.from(visible.planned.measurement.predictedInput)
            .add(ExactDecimal.from(18))
            .toString(),
        )
        expect(result.planned.serialized).toContain('ORIGINAL_OPAQUE')
        const { messages: finalUnits, ...finalEnvelope } = result.planned.body
        if (!Array.isArray(finalUnits) || result.planned.requestInput.kind !== 'known')
          throw Error('current projection required')
        const selectedUnit = finalUnits[1]
        if (selectedUnit === undefined) throw Error('selected unit required')
        const deltaInput = {
          units: [selectedUnit],
          envelope: finalEnvelope,
          precedingUnitCount: 1,
          unitIndices: [1],
          countingBasis: result.planned.requestInput.countingBasis,
          outputHistory: [history],
          historySpans: reply.blocks.map((_, selectionIndex) => ({
            groupIndex: 0,
            selectionIndex,
            start: 1,
            end: 2,
          })),
        }
        expect(writeJsonLossless(meter.measureNew(deltaInput))).toBe(
          '{"kind":"estimated","tokens":18}',
        )
        expect(
          writeJsonLossless(
            meter.measureNew({
              ...deltaInput,
              outputHistory: [
                { ...history, usage: { ...history.usage, output_tokens: 0, reasoning_tokens: 0 } },
              ],
            }),
          ),
        ).toBe('{"kind":"estimated","tokens":0}')

        expect(() =>
          createOpenAiInputMeter({
            ...definition,
            revision: original.definitionRevision,
            implementation: binding.implementation,
          }),
        ).toThrow('unsupported OpenAI')
        const unavailable = {
          ...history,
          inputCalibration: {
            ...history.inputCalibration,
            requestInput: { kind: 'unavailable' as const, reason: 'not_retained' as const },
          },
        }
        const withoutI = await plan({ ...target, outputHistory: [unavailable] })
        if ('rejected' in withoutI) throw Error(JSON.stringify(withoutI))
        expect(withoutI.planned.measurement.predictedInput).toEqual(
          result.planned.measurement.predictedInput,
        )
        const unknownBinding = {
          ...binding,
          definition: { ...binding.definition, revision: 'unknown' },
        }
        expect(
          await plan({
            ...target,
            outputHistory: [
              { ...unavailable, origin: { ...history.origin, adaptation: unknownBinding } },
            ],
          }),
        ).toMatchObject({ rejected: 'invalidInput', reason: 'input_size_unavailable' })
      },
    )
  },
)

tests/openai-family-policy.spec.ts.source:
import { readFileSync } from 'node:fs'
import { toOpaqueJson } from '@omne-harness-lite/content-blocks'
import { defineInputMeter } from '../src/input-meter.ts'
import type { OutputGroupSource } from '../src/input-meters/output-history.ts'
import { describe, expect, it } from 'vitest'
import {
  classifyOpenAiDetail,
  openAiOutputHistoryPolicy,
  openAiOriginalBasisApplies,
  openAiBasisRecord,
  OPENAI_FAMILY_ALGORITHM,
  OPENAI_FAMILY_REPLAY,
  openAiEnvelopeApplies,
  openAiFamilyRecord,
  openAiFamilyRecords,
  originalOpenAiRecord,
} from '../src/input-meters/openai-family-policy.ts'

const fixture = JSON.parse(
  readFileSync(
    new URL('./fixtures/openai/priority-family/original-meter-records.json', import.meta.url),
    'utf8',
  ),
)
const rows = Object.values(openAiFamilyRecords)
const route = { order: ['openai'], allow_fallbacks: false, require_parameters: true }
describe('finite OpenAI family applicability records', () => {
  it('has twelve current targets and six unknown Pro input scopes', () => {
    expect(rows).toHaveLength(12)
    expect(rows.filter(row => row.inputScope === 'scope_unknown')).toHaveLength(6)
    expect(openAiFamilyRecord('openai/gpt-6-unknown')).toBeUndefined()
    expect(openAiFamilyRecord('constructor')).toBeUndefined()
    expect(Object.isFrozen(openAiFamilyRecords)).toBe(true)
  })
  it.each(rows)('$modelId retains the independently captured original factory facts', row => {
    const captured = fixture.rows.find((item: { modelId: string }) => item.modelId === row.modelId)
    expect(captured).toBeDefined()
    const original = originalOpenAiRecord(
      row,
      captured.definitionRevision,
      captured.implementation.revision,
    )
    expect(original).toEqual({
      definitionRevision: captured.definitionRevision,
      implementationRevision: captured.implementation.revision,
      algorithmRevision: captured.algorithmRevision,
      tokenizerRevision: captured.tokenizerRevision,
      replayRevision: captured.replayRevision,
      transformRevision: captured.transformRevision,
      projectionRevision: captured.projectionRevision,
    })
    expect(Object.isFrozen(row)).toBe(true)
    expect(Object.isFrozen(row.original)).toBe(true)
    expect(originalOpenAiRecord(row, '999', 'mp4-17')).toBeUndefined()
  })
  it.each(rows)('$modelId limits whole-group proxy routing and actual effort controls', row => {
    const envelope = { model: row.modelId, provider: route }
    expect(openAiEnvelopeApplies(envelope, row)).toBe(true)
    for (const effort of row.efforts)
      expect(openAiEnvelopeApplies({ ...envelope, reasoning: { effort } }, row)).toBe(true)
    for (const bad of [
      { ...envelope, model: 'openai/other' },
      { ...envelope, provider: { ...route, allow_fallbacks: true } },
      { ...envelope, provider: { ...route, order: ['openai', 'other'] } },
      { ...envelope, provider: { ...route, data_collection: 'deny' } },
      { ...envelope, reasoning: { effort: 'unverified' } },
      { ...envelope, reasoning: { context: 'all_turns' } },
      { ...envelope, reasoning: { effort: 'low', context: 'all_turns' } },
    ])
      expect(openAiEnvelopeApplies(bad, row)).toBe(false)
  })
  it.each(rows)(
    '$modelId admits one assigned current identity without accepting arbitrary aliases',
    row => {
      expect(openAiBasisRecord(row, row.definitionRevision, 'mp4-18')).toMatchObject({
        algorithmRevision: OPENAI_FAMILY_ALGORITHM,
        replayRevision: OPENAI_FAMILY_REPLAY,
        tokenizerRevision: row.tokenizerRevision,
      })
      expect(openAiBasisRecord(row, row.definitionRevision, 'mp4-19')).toBeUndefined()
      expect(openAiBasisRecord(row, '999', 'mp4-18')).toBeUndefined()
      expect(openAiBasisRecord(row, row.definitionRevision, 'mp4-17')).toBeUndefined()
    },
  )
  it('retains only the three declared GPT56 prior full/history facts', () => {
    for (const row of rows) {
      expect(row.original.map(original => original.definitionRevision)).toEqual(
        ['openai/gpt-5.6-sol', 'openai/gpt-5.6-terra', 'openai/gpt-5.6-luna'].includes(row.modelId)
          ? ['6', '7', '8']
          : [String(Number(row.definitionRevision) - 1)],
      )
    }
  })
})
describe('OpenAI reasoning classification', () => {
  it('requires a complete group for nonempty exact-format encrypted data', () => {
    expect(
      classifyOpenAiDetail({
        type: 'reasoning.encrypted',
        data: 'opaque',
        format: 'openai-responses-v1',
      }),
    ).toBe('wholeGroup')
    for (const detail of [
      { type: 'reasoning.encrypted', data: 'opaque' },
      { type: 'reasoning.encrypted', data: '', format: 'openai-responses-v1' },
      { type: 'reasoning.encrypted', data: 'opaque', format: 'unknown' },
      { type: 'reasoning.encrypted', data: 'opaque', format: 'openai-responses-v1', index: -1 },
      { type: 'unknown', text: 'opaque' },
    ])
      expect(classifyOpenAiDetail(detail)).toBe('uninterpretable')
  })
  it('keeps visible text/summary without treating unknown metadata as visible', () => {
    expect(classifyOpenAiDetail({ type: 'reasoning.text', text: '' })).toBe('visible')
    expect(
      classifyOpenAiDetail({
        type: 'reasoning.summary',
        summary: 's',
        format: 'openai-responses-v1',
      }),
    ).toBe('visible')
    expect(
      classifyOpenAiDetail({ type: 'reasoning.text', text: '', signature: 'not-openai' }),
    ).toBe('uninterpretable')
  })
})

describe('OpenAI family source records', () => {
  it.each(rows)('$modelId accepts finite original O records and rejects unlisted sources', row => {
    const meter = defineInputMeter({
      modelId: row.modelId,
      provider: 'openai',
      definitionRevision: row.definitionRevision,
      implementation: { name: 'pi-ai:openai', revision: 'mp4-18' },
      algorithmRevision: OPENAI_FAMILY_ALGORITHM,
      replayRevision: OPENAI_FAMILY_REPLAY,
      tokenizerRevision: row.tokenizerRevision,
      transformRevision: row.transformRevision,
      evidence: 'offline guard fixture',
      measureFull: () => ({ kind: 'unavailable' }),
    })
    const envelope = { model: row.modelId, provider: route, reasoning: { effort: 'low' } }
    for (const original of row.original) {
      const binding = {
        definition: { modelId: row.modelId, revision: original.definitionRevision },
        implementation: { name: 'pi-ai:openai', revision: original.implementationRevision },
        configuration: { values: { cache: { mode: 'automatic' } } },
      }
      // These fixtures exercise the family predicate after shared schema ownership.
      // Generic completeness/account/selection guards are exercised at the full interfaces.
      const source = {
        origin: {
          adaptation: binding,
          provider: 'openai',
          parameters: { reasoningEffort: 'low' },
          servingProvider: 'OpenAI',
          upstreamModel: row.modelId,
        },
        observation: {
          kind: 'observation',
          inputCalibration: {
            requestInput: { kind: 'unavailable', reason: 'not_retained' },
            observedInput: {
              kind: 'unavailable',
              reason: row.inputScope === 'scope_unknown' ? 'scope_unknown' : 'missing_usage',
            },
          },
          outputBlocks: [
            {
              kind: 'thinking',
              text: '',
              opaque: toOpaqueJson({
                routeName: row.modelId,
                reasoning_details: [
                  { type: 'reasoning.encrypted', data: 'opaque', format: 'openai-responses-v1' },
                ],
              }),
            },
          ],
        },
      } as unknown as OutputGroupSource
      expect(openAiOutputHistoryPolicy.sourceApplies(source, meter, envelope)).toBe(true)
      expect(
        openAiOutputHistoryPolicy.sourceApplies(
          { ...source, origin: { ...source.origin!, provider: 'other' } },
          meter,
          envelope,
        ),
      ).toBe(false)
      expect(
        openAiOutputHistoryPolicy.sourceApplies(
          {
            ...source,
            origin: {
              ...source.origin!,
              adaptation: {
                ...source.origin!.adaptation,
                definition: { modelId: row.modelId, revision: 'unlisted' },
              },
            },
          },
          meter,
          envelope,
        ),
      ).toBe(false)
      expect(
        openAiOutputHistoryPolicy.sourceApplies(
          source,
          { ...meter, algorithmRevision: 'invented' },
          envelope,
        ),
      ).toBe(false)
      const basis = {
        ...original,
        binding,
        model: row.modelId,
        provider: 'openai',
        meterRevision: original.algorithmRevision,
      }
      const applies = openAiOriginalBasisApplies(row) as (basis: unknown, base: unknown) => boolean
      const base = { kind: 'known', base: original.transformRevision, preparation: null }
      expect(applies(basis, base)).toBe(true)
      expect(applies({ ...basis, meterRevision: 'invented' }, base)).toBe(false)
      expect(applies({ ...basis, projectionRevision: 'unlisted' }, base)).toBe(false)
      expect(applies({ ...basis, provider: 'other' }, base)).toBe(false)
    }
  })
})

