import { measureFull, measureNew } from '../src/input-meter.ts'
import { testImagePreparerFor } from './image-transport-support.ts'
import { ExactDecimal } from '@omne-harness-lite/call-accounts'
import { describe, expect, it } from 'vitest'
import { getEncoding } from 'js-tiktoken'
import { writeJsonLossless, toOpaqueJson } from '@omne-harness-lite/content-blocks'
import type { PlanInput, PlanOutputHistoryGroup } from '@omne-harness-lite/model-request-runtime'
import type { Message } from '@omne-harness-lite/messages'
import { projectAssistant } from '../src/assistant-projection.ts'
import { createOpenAiInputMeter } from '../src/input-meters/openai.ts'
import type { ReplayMeterInput, InputMeter } from '../src/input-meter.ts'
import { createOfficialProfileContent } from '../src/configuration.ts'
import { openaiConfiguration, openaiDefinitions } from '../src/official-models/openai.ts'
import { planRequest, type PlannedRequest } from '../src/plan.ts'
import {
  projectInput,
  projectOutput,
  projectionDigest,
  outputBlockDigestAtRevision,
} from '../src/projection.ts'
import { at, input, judgedMessage, message } from './support.ts'

// Runtime negative controls deliberately cross the typed standalone boundary.
function callReplay(input: unknown, meter: InputMeter): unknown {
  return (meter.measureReplay as (input: unknown) => unknown)(input)
}
function historicalProjection(
  group: PlanOutputHistoryGroup,
  originalPlan: PlannedRequest,
): PlanOutputHistoryGroup {
  const revision = 'openrouter-input-projection/2'
  const request = group.inputCalibration.requestInput
  const output = group.inputCalibration.outputGroup
  if (request.kind !== 'known' || output.kind !== 'known') throw Error('known fixture required')
  const { messages, ...envelope } = originalPlan.body
  return {
    ...group,
    inputCalibration: {
      ...group.inputCalibration,
      requestInput: {
        ...request,
        projectionRevision: revision,
        prefixDigest: projectionDigest('input-prefix', messages, revision),
        inputEnvelopeDigest: projectionDigest('input-envelope', envelope, revision),
        countingBasis: { ...request.countingBasis, projectionRevision: revision },
      },
      outputGroup: {
        ...output,
        projectionRevision: revision,
        blockDigests: group.outputBlocks.map(block => outputBlockDigestAtRevision(block, revision)),
      },
    },
  }
}
const ids = ['openai/gpt-5.6-sol', 'openai/gpt-5.6-terra', 'openai/gpt-5.6-luna']
const encoder = getEncoding('o200k_base')
function reply(model: string, id: string): Message {
  return judgedMessage({
    type: 'assistant',
    id,
    response: `${id}-response`,
    ending: 'complete',
    createdAt: at,
    blocks: [
      {
        kind: 'thinking',
        id: `${id}-reason`,
        text: '',
        opaque: toOpaqueJson({
          routeName: model,
          reasoning_details: [
            {
              type: 'reasoning.encrypted',
              data: `CIPHER_${id}`,
              format: 'openai-responses-v1',
              index: 0,
            },
          ],
        }),
        visibility: { toHuman: false, toModel: true },
      },
      {
        kind: 'text',
        id: `${id}-text`,
        text: `Visible ${id}`,
        visibility: { toHuman: true, toModel: true },
      },
    ],
  })
}
function group(
  plan: PlannedRequest,
  reply: Message,
  index: number,
  output: number,
  observed?: number,
): PlanOutputHistoryGroup {
  const projected = projectOutput({
    blocks: reply.blocks,
    source: 'reply',
    completeness: 'complete',
  })
  if (!('projected' in projected)) throw Error('fixture projection')
  return {
    inputCalibration: {
      requestInput: plan.requestInput,
      observedInput:
        observed === undefined
          ? { kind: 'unavailable', reason: 'missing_usage' }
          : {
              kind: 'from_usage',
              provenance: {
                adapterRevision: 'openrouter-usage-reader/2',
                fieldPaths: ['usage.prompt_tokens'],
              },
            },
      outputGroup: projected.projected,
    },
    usage: {
      input_tokens: observed ?? 'unknown',
      output_tokens: output,
      cache_read_tokens: observed === undefined ? 'unknown' : 0,
      cache_write_tokens: observed === undefined ? 'unknown' : 0,
      reasoning_tokens: 7,
      source: 'upstream',
    },
    outputBlocks: reply.blocks,
    replaySelection: reply.blocks.map((_, i) => ({
      sourceBlockIndex: i,
      messageIndex: index,
      blockIndex: i,
    })),
    origin: {
      adaptation: plan.input.snapshot.adaptation,
      provider: 'openai',
      parameters: plan.parameters,
      servingProvider: 'OpenAI',
      upstreamModel: plan.input.routeName,
    },
  }
}
const observation = (g: PlanOutputHistoryGroup) => ({
  kind: 'observation' as const,
  inputCalibration: g.inputCalibration,
  usage: g.usage,
  outputBlocks: g.outputBlocks,
  replaySelection: g.replaySelection,
})
describe.each(ids)('%s explicit complete output history', model => {
  const definition = openaiDefinitions.find(d => d.modelId === model)!
  const meter = createOpenAiInputMeter(definition)
  const profile = createOfficialProfileContent(definition, {
    providers: ['openai'],
    allowFallback: false,
    configuration: openaiConfiguration,
  })
  if ('rejected' in profile) throw Error(profile.rejected)
  const resolvedProfile = profile.ok
  function request(): PlanInput {
    const base = input()
    return {
      ...base,
      routeName: model,
      provider: 'openai',
      snapshot: {
        ...base.snapshot,
        ...definition.capabilities,
        adaptation: resolvedProfile.adaptation,
        providers: resolvedProfile.providers,
        allowFallback: false,
      },
      messages: [message('user', 'start', 'u1')],
      tools: [],
      parameters: { reasoningEffort: 'low', maxOutputTokens: 1024 },
      tokenMargin: { multiplier: 1.1, reserveTokens: 7 },
    }
  }
  async function planned(value: PlanInput): Promise<PlannedRequest> {
    const result = await planRequest(
      value,
      [definition],
      meter,
      {
        signal: new AbortController().signal,
      },
      testImagePreparerFor(planRequest),
    )
    if (!('planned' in result)) throw Error(JSON.stringify(result))
    return result.planned
  }
  async function history() {
    const first = await planned(await request()),
      a = reply(model, 'a'),
      ga = group(first, a, 1, 18, 100)
    const second = await planned({
      ...(await request()),
      messages: [...(await request()).messages, a, message('user', 'next', 'u2')],
      outputHistory: [ga],
    })
    const b = reply(model, 'b'),
      gb = group(second, b, 3, 23)
    const value = {
      ...(await request()),
      messages: [
        ...(await request()).messages,
        a,
        message('user', 'next', 'u2'),
        b,
        message('user', 'last', 'u3'),
      ],
      outputHistory: [ga, gb],
    }
    return { value, ga, gb, first }
  }
  it('owns replay input before inspecting fields and rejects multiple or inconsistent original groups', async () => {
    let getterReads = 0
    const accessor = Object.defineProperty({}, 'outputHistory', {
      enumerable: true,
      get() {
        getterReads++
        return []
      },
    })
    for (const bad of [null, {}, { units: [] }, accessor]) {
      expect(callReplay(bad, meter)).toEqual({ kind: 'invalidInput' })
      expect(Reflect.apply(meter.measureReplay, undefined, [bad])).toEqual({ kind: 'invalidInput' })
    }
    expect(getterReads).toBe(0)
    const { value, ga } = await history()
    let actual: ReplayMeterInput | undefined
    const result = await planRequest(
      { ...value, calibration: observation(ga) },
      [definition],
      {
        ...meter,
        measureReplay(input) {
          actual = input
          return meter.measureReplay(input)
        },
      },
      { signal: new AbortController().signal },
      testImagePreparerFor(planRequest),
    )
    expect(result).toHaveProperty('planned')
    if (!actual) throw Error('missing actual replay')
    expect(callReplay(actual, meter)).toEqual({ kind: 'estimated', tokens: 18 })
    const original = actual.outputHistory[0]
    if (!original) throw Error('missing original group')
    for (const bad of [
      { ...actual, outputHistory: [original, original] },
      {
        ...actual,
        outputHistory: [{ ...original, usage: { ...original.usage, output_tokens: 999 } }],
      },
    ]) {
      expect(callReplay(bad, meter)).toEqual({ kind: 'invalidInput' })
      expect(meter.measureReplay(bad)).toEqual({ kind: 'invalidInput' })
    }
  })
  it('covers two O groups in full and only N O in marginal with independent numeric oracles', async () => {
    const { value, ga } = await history()
    const full = await planned(value)
    const body = {
      ...full.body,
      messages: (full.body.messages as unknown[]).filter((_, i) => i !== 1 && i !== 3),
    }
    const expected = encoder.encode(writeJsonLossless(body)).length + 18 + 23
    expect(full.measurement).toMatchObject({
      mode: 'full',
      admissionTokens: Math.ceil(expected * 1.1) + 7,
    })
    expect(ExactDecimal.from(full.measurement.predictedInput).toString()).toBe(String(expected))
    expect(writeJsonLossless(full.body)).toContain('CIPHER_a')
    expect(writeJsonLossless(full.body)).toContain('CIPHER_b')
    const marginal = await planned({ ...value, calibration: observation(ga) })
    const { messages: _, tools: __, ...envelope } = marginal.body
    const remaining = (marginal.body.messages as unknown[]).filter((_, i) => i === 2 || i === 4)
    const net =
      encoder.encode(writeJsonLossless({ ...envelope, messages: remaining })).length -
      encoder.encode(writeJsonLossless({ ...envelope, messages: [] })).length +
      23
    expect(marginal.measurement.mode).toBe('marginal')
    if (marginal.measurement.mode !== 'marginal') throw Error('marginal required')
    expect(ExactDecimal.from(marginal.measurement.replayContribution.tokens).toString()).toBe('18')
    expect(ExactDecimal.from(marginal.measurement.newContribution.tokens).toString()).toBe(
      String(net),
    )
    expect(ExactDecimal.from(marginal.measurement.predictedInput).toString()).toBe(
      String(100 + 18 + net),
    )
  })
  it.each([
    {
      definition: '6',
      implementation: 'mp4-12',
      algorithm: 'openai-gpt-5.6-o200k-base-complete-output-6/response-calibration-1',
      replay: 'openai-gpt-5.6-complete-encrypted-group-output-zero-framing-estimated/1',
    },
    {
      definition: '7',
      implementation: 'mp4-16',
      algorithm: 'openai-gpt-5.6-o200k-base-complete-output-history-7/response-calibration-1',
      replay: 'openai-gpt-5.6-complete-encrypted-group-output-zero-framing-estimated/2',
    },
    {
      definition: '8',
      implementation: 'mp4-17',
      algorithm: 'openai-gpt-5.6-o200k-base-complete-output-history-7/response-calibration-1',
      replay: 'openai-gpt-5.6-complete-encrypted-group-output-zero-framing-estimated/2',
    },
  ])('BR finite original $definition retains O under current preparation semantics', async row => {
    const { value, ga, gb, first } = await history()
    const source = ga.inputCalibration.requestInput
    if (source.kind !== 'known') throw Error('known source required')
    const binding = {
      ...ga.origin.adaptation,
      definition: { modelId: model, revision: row.definition },
      implementation: { name: 'pi-ai:openai', revision: row.implementation },
    }
    const old: PlanOutputHistoryGroup = historicalProjection(
      {
        ...ga,
        origin: { ...ga.origin, adaptation: binding },
        inputCalibration: {
          ...ga.inputCalibration,
          requestInput: {
            ...source,
            countingBasis: {
              ...source.countingBasis,
              binding,
              meterRevision: row.algorithm,
              replayRevision: row.replay,
            },
          },
        },
      },
      first,
    )
    const current = await planned({ ...value, outputHistory: [old, gb] })
    const preparer = testImagePreparerFor(planRequest)
    const descriptor = {
      algorithmRevision: preparer.algorithmRevision,
      codecRevision: preparer.codecRevision,
      policyDigest: preparer.policyDigest,
    }
    const projection = projectInput(current.body, current.input, meter, descriptor)
    const historySpans = [old, gb].flatMap((group, groupIndex) =>
      group.replaySelection.map((item, selectionIndex) => ({
        groupIndex,
        selectionIndex,
        start: item.messageIndex,
        end: item.messageIndex + 1,
      })),
    )
    const full = {
      body: current.body,
      serialized: current.serialized,
      projection,
      outputHistory: [old, gb],
      historySpans,
    }
    expect(measureFull(meter, full)).toEqual({
      kind: current.measurement.precision,
      tokens: current.measurement.predictedInput,
    })
    expect(
      measureNew(meter, {
        units: projection.units,
        envelope: projection.envelope,
        precedingUnitCount: 0,
        unitIndices: projection.units.map((_, i) => i),
        countingBasis: projection.requestInput.countingBasis,
        outputHistory: [old, gb],
        historySpans,
      }).kind,
    ).toBe('estimated')
    const selected = projection.units[1]
    if (selected === undefined) throw Error('selected unit required')
    const replay: ReplayMeterInput = {
      units: [selected],
      envelope: projection.envelope,
      precedingUnitCount: 1,
      unitIndices: [1],
      countingBasis: projection.requestInput.countingBasis,
      observation: observation(old),
      outputHistory: [old],
      selectionSpans: old.replaySelection.map((_, selectionIndex) => ({
        selectionIndex,
        start: 1,
        end: 2,
      })),
    }
    expect(callReplay(replay, meter)).toEqual({ kind: 'unavailable' })
    if (row.definition === '8') {
      const same: PlanOutputHistoryGroup = {
        ...ga,
        inputCalibration: {
          ...ga.inputCalibration,
          requestInput: { ...source, countingBasis: projection.requestInput.countingBasis },
        },
      }
      expect(
        callReplay({ ...replay, observation: observation(same), outputHistory: [same] }, meter),
      ).toEqual({ kind: 'estimated', tokens: 18 })
    }
    const unknown: PlanOutputHistoryGroup = {
      ...old,
      origin: {
        ...old.origin,
        adaptation: { ...binding, definition: { ...binding.definition, revision: 'unlisted' } },
      },
      inputCalibration: {
        ...old.inputCalibration,
        requestInput: {
          ...source,
          countingBasis: {
            ...source.countingBasis,
            binding: { ...binding, definition: { ...binding.definition, revision: 'unlisted' } },
          },
        },
      },
    }
    expect(measureFull(meter, { ...full, outputHistory: [unknown, gb] })).toEqual({
      kind: 'unavailable',
    })
    const originOnly: PlanOutputHistoryGroup = {
      ...old,
      inputCalibration: {
        ...old.inputCalibration,
        requestInput: { kind: 'unavailable', reason: 'not_retained' },
      },
    }
    expect(measureFull(meter, { ...full, outputHistory: [originOnly, gb] }).kind).toBe('estimated')
    expect(writeJsonLossless(full.body)).toContain('CIPHER_a')
  })
  it('uses original origin with unavailable requestInput but never invents missing origin', async () => {
    const { value, gb } = await history()
    const noI: PlanOutputHistoryGroup = {
      ...gb,
      inputCalibration: {
        ...gb.inputCalibration,
        requestInput: { kind: 'unavailable', reason: 'not_retained' },
      },
    }
    expect(
      (await planned({ ...value, outputHistory: [value.outputHistory[0]!, noI] })).measurement.mode,
    ).toBe('full')
    const { origin: _, ...missing } = noI
    expect(
      await planRequest(
        { ...value, outputHistory: [value.outputHistory[0]!, missing as PlanOutputHistoryGroup] },
        [definition],
        meter,
        { signal: new AbortController().signal },
        testImagePreparerFor(planRequest),
      ),
    ).toMatchObject({ rejected: 'invalidInput', reason: 'malformed' })
  })
  it.each([
    {
      definition: '6',
      implementation: 'mp4-12',
      algorithm: 'openai-gpt-5.6-o200k-base-complete-output-6/response-calibration-1',
      replay: 'openai-gpt-5.6-complete-encrypted-group-output-zero-framing-estimated/1',
    },
    {
      definition: '7',
      implementation: 'mp4-16',
      algorithm: 'openai-gpt-5.6-o200k-base-complete-output-history-7/response-calibration-1',
      replay: 'openai-gpt-5.6-complete-encrypted-group-output-zero-framing-estimated/2',
    },
  ])(
    'maps finite original definition $definition without making its factory callable',
    async source => {
      const { value, ga, first } = await history()
      const original = ga.inputCalibration.requestInput
      if (original.kind !== 'known') throw Error('fixture source')
      const binding = {
        ...ga.origin.adaptation,
        definition: { modelId: model, revision: source.definition },
        implementation: { name: 'pi-ai:openai', revision: source.implementation },
      }
      const old: PlanOutputHistoryGroup = historicalProjection(
        {
          ...ga,
          origin: { ...ga.origin, adaptation: binding },
          inputCalibration: {
            ...ga.inputCalibration,
            requestInput: {
              ...original,
              countingBasis: {
                ...original.countingBasis,
                binding,
                meterRevision: source.algorithm,
                replayRevision: source.replay,
              },
            },
          },
        },
        first,
      )
      expect(
        (await planned({ ...value, outputHistory: [old, value.outputHistory[1]!] })).measurement
          .mode,
      ).toBe('full')
      expect(() =>
        createOpenAiInputMeter({
          ...definition,
          revision: source.definition,
          implementation: binding.implementation,
        }),
      ).toThrow()
      const oldRequest = old.inputCalibration.requestInput
      if (oldRequest.kind !== 'known') throw Error('known historical request')
      const bad = {
        ...old,
        inputCalibration: {
          ...old.inputCalibration,
          requestInput: {
            ...oldRequest,
            countingBasis: {
              ...oldRequest.countingBasis,
              binding,
              meterRevision: 'invented',
              replayRevision: source.replay,
            },
          },
        },
      }
      expect(
        await planRequest(
          { ...value, outputHistory: [bad, value.outputHistory[1]!] },
          [definition],
          meter,
          { signal: new AbortController().signal },
          testImagePreparerFor(planRequest),
        ),
      ).toMatchObject({ rejected: 'invalidInput', reason: 'input_size_unavailable' })
    },
  )
  it('does not turn partial selections, missing O or absent facts into ciphertext estimates', async () => {
    const { value, ga } = await history()
    const partial = { ...ga, replaySelection: ga.replaySelection.slice(0, 1) }
    expect(
      await planRequest(
        { ...value, outputHistory: [partial, value.outputHistory[1]!] },
        [definition],
        meter,
        { signal: new AbortController().signal },
        testImagePreparerFor(planRequest),
      ),
    ).toMatchObject({ rejected: 'invalidInput' })
    expect(
      await planRequest(
        { ...value, outputHistory: [] },
        [definition],
        meter,
        {
          signal: new AbortController().signal,
        },
        testImagePreparerFor(planRequest),
      ),
    ).toMatchObject({
      rejected: 'invalidInput',
      reason: 'input_size_unavailable',
    })
    expect(
      await planRequest(
        {
          ...value,
          outputHistory: [
            { ...ga, usage: { ...ga.usage, output_tokens: 'unknown' } },
            value.outputHistory[1]!,
          ],
        },
        [definition],
        meter,
        { signal: new AbortController().signal },
        testImagePreparerFor(planRequest),
      ),
    ).toMatchObject({ rejected: 'invalidInput', reason: 'input_size_unavailable' })
    expect(
      await planRequest(
        { ...value, outputHistory: [ga, ga] },
        [definition],
        meter,
        {
          signal: new AbortController().signal,
        },
        testImagePreparerFor(planRequest),
      ),
    ).toMatchObject({
      rejected: 'invalidInput',
      reason: 'malformed',
    })
    expect(
      await planRequest(
        {
          ...value,
          outputHistory: [
            { ...ga, origin: { ...ga.origin, upstreamModel: 'openai/gpt-6-sol' } },
            value.outputHistory[1]!,
          ],
        },
        [definition],
        meter,
        { signal: new AbortController().signal },
        testImagePreparerFor(planRequest),
      ),
    ).toMatchObject({ rejected: 'invalidInput', reason: 'input_size_unavailable' })
  })
  it('never borrows O after a model switch, including Pro and GPT-6 targets', async () => {
    const { value } = await history()
    for (const target of [ids.find(id => id !== model)!, `${model}-pro`, 'openai/gpt-6-sol']) {
      const selected = openaiDefinitions.find(d => d.modelId === target)!
      const supplied = createOfficialProfileContent(selected, {
        providers: ['openai'],
        allowFallback: false,
        configuration: openaiConfiguration,
      })
      if ('rejected' in supplied) throw Error(supplied.rejected)
      const changed: PlanInput = {
        ...value,
        routeName: target,
        snapshot: { ...value.snapshot, adaptation: supplied.ok.adaptation },
      }
      const beforeProjection = writeJsonLossless(changed.messages)
      expect(projectAssistant(changed.messages[1]!.blocks, target, false)).toEqual({
        rejected: 'unavailable',
      })
      const result = await planRequest(
        changed,
        [selected],
        createOpenAiInputMeter(selected),
        {
          signal: new AbortController().signal,
        },
        testImagePreparerFor(planRequest),
      )
      // Opaque source route mismatch is rejected by the shared assistant projector.
      expect(result).toEqual({ rejected: 'unavailable' })
      expect(writeJsonLossless(changed.messages)).toBe(beforeProjection)
      expect(beforeProjection).toContain('CIPHER_a')
    }
  })
  it('covers text, reasoning and tool calls by O once while counting the paired result normally', async () => {
    const firstInput = {
      ...(await request()),
      tools: [
        {
          name: 'lookup',
          description: 'Lookup',
          parameters: { type: 'object', properties: { key: { type: 'string' } } },
        },
      ],
    }
    const first = await planned(firstInput)
    const output = judgedMessage({
      ...reply(model, 'with-tool'),
      blocks: [
        ...reply(model, 'with-tool').blocks,
        {
          id: 'call-block',
          kind: 'tool_call',
          callId: 'lookup_1',
          tool: 'lookup',
          arguments: { key: 'already-covered-by-O'.repeat(30) },
          complete: true,
          visibility: { toHuman: true, toModel: true },
        },
      ],
    })
    const result = judgedMessage({
      type: 'tool',
      id: 'result-message',
      callId: 'lookup_1',
      createdAt: at,
      blocks: [
        {
          id: 'result-block',
          kind: 'tool_result',
          callId: 'lookup_1',
          outcome: 'completed',
          visibility: { toHuman: true, toModel: true },
          blocks: [
            {
              id: 'result-text',
              kind: 'text',
              text: 'a new result',
              visibility: { toHuman: true, toModel: true },
            },
          ],
        },
      ],
    })
    const current = await planned({
      ...firstInput,
      messages: [...firstInput.messages, output, result],
      outputHistory: [group(first, output, 1, 40)],
    })
    const remaining = {
      ...current.body,
      messages: (current.body.messages as unknown[]).filter((_, index) => index !== 1),
    }
    expect(
      ExactDecimal.from(current.measurement.predictedInput).compare(
        ExactDecimal.from(encoder.encode(writeJsonLossless(remaining)).length + 40),
      ),
    ).toBe(0)
    expect(writeJsonLossless(current.body)).toContain('already-covered-by-O')
    expect(writeJsonLossless(current.body)).toContain('a new result')
  })
})

tests/openai-pro-images.spec.ts.source:
import { imagePreparation, testImagePreparerFor } from './image-transport-support.ts'
import { readFileSync } from 'node:fs'
import { afterAll, beforeAll, describe, expect, it } from 'vitest'
import { writeJsonLossless } from '@omne-harness-lite/content-blocks'
import { invokeModel, type PlanInput } from '@omne-harness-lite/model-request-runtime'
import { createOpenAiInputMeter } from '../src/input-meters/openai.ts'
import { createOfficialProfileContent } from '../src/configuration.ts'
import { openaiConfiguration, openaiDefinitions } from '../src/official-models/openai.ts'
import { createPiAiTransport } from '../src/transport.ts'
import { planRequest } from '../src/plan.ts'
import { directFull } from './direct-full-input.ts'
import {
  at,
  certificate,
  finish,
  fixture,
  input,
  judgedMessage,
  message,
  policy,
  sse,
} from './support.ts'

const models = [
  'openai/gpt-6-astra-pro',
  'openai/gpt-5.6-sol-pro',
  'openai/gpt-5.6-terra-pro',
  'openai/gpt-5.6-luna-pro',
]
const bytes = (name: string) =>
  readFileSync(new URL(`./fixtures/openai-meter/${name}`, import.meta.url))
const imageUrl = (name: string) =>
  `data:image/${name.endsWith('.gif') ? 'gif' : 'png'};base64,${bytes(name).toString('base64')}`

// These assert the frozen surrogate, not the private Pro preprocessor's accuracy.
describe.each(models)('%s base-image estimated proxy', modelId => {
  const astra = modelId === 'openai/gpt-6-astra-pro'
  const definition = openaiDefinitions.find(item => item.modelId === modelId)!
  const meter = createOpenAiInputMeter(definition)
  function measured(name: string, detail: string | undefined = undefined) {
    const body = {
      model: modelId,
      provider: { order: ['openai'], allow_fallbacks: false, require_parameters: true },
      stream: true,
      store: false,
      messages: [
        {
          role: 'user',
          content: [
            {
              type: 'image_url',
              image_url: { url: imageUrl(name), ...(detail === undefined ? {} : { detail }) },
            },
          ],
        },
      ],
    }
    return directFull(meter, { body, serialized: writeJsonLossless(body) })
  }
  it('requires the new binding and records the inference as estimated', () => {
    expect(definition).toMatchObject({
      revision: astra ? '6' : '8',
      implementation: { revision: 'mp4-18' },
    })
    expect(meter.algorithmRevision).toBe('openai-visible-json-complete-output-group-estimated/1')
    expect(meter.evidence).toContain('not verified Pro preprocessing')
    expect(() =>
      createOpenAiInputMeter({
        ...definition,
        revision: astra ? '3' : '5',
        implementation: { name: 'pi-ai:openai', revision: astra ? 'mp4-8' : 'mp4-7' },
      }),
    ).toThrow('unsupported OpenAI')
  })
  it.each([
    ['low', 229],
    ['high', 2940],
    ['original', 3685],
    ['auto', 3685],
    [undefined, 3685],
  ] as const)('keeps detail %s numeric patch goldens (%s net)', (detail, expected) => {
    const large = measured('2048x1536.png', detail)
    const small = measured('1x1.png', detail)
    expect(large.kind).toBe('estimated')
    expect(small.kind).toBe('estimated')
    if (large.kind !== 'estimated' || small.kind !== 'estimated') throw Error('missing estimate')
    expect(Number(large.tokens) - Number(small.tokens)).toBe(expected)
  })
  it('keeps Astra and GPT-5.6 high-detail fit limits separate', () => {
    const wide = measured('65536x32.png', 'high')
    const small = measured('1x1.png', 'high')
    if (wide.kind !== 'estimated' || small.kind !== 'estimated') throw Error('missing estimate')
    // Astra fits to 65535 x 31 (2048 patches); GPT-5.6 to 2048 x 1 (64 patches).
    expect(Number(wide.tokens) - Number(small.tokens)).toBe(astra ? 2456 : 75)
  })
  it('accepts a complete single-frame GIF and refuses animated, truncated and unknown detail input', () => {
    expect(measured('single-frame.gif', 'low')).toEqual(measured('1x1.png', 'low'))
    expect(measured('two-frame.gif')).toEqual({ kind: 'unavailable' })
    expect(measured('truncated.gif')).toEqual({ kind: 'unavailable' })
    expect(measured('1x1.png', 'ultra')).toEqual({ kind: 'unavailable' })
  })
  let cert: ReturnType<typeof certificate>
  beforeAll(() => {
    cert = certificate()
  })
  afterAll(() => cert.dispose())
  it('uses the public invocation unchanged wire and actual accounts, without creating an input anchor', async () => {
    const profile = createOfficialProfileContent(definition, {
      providers: ['openai'],
      allowFallback: false,
      configuration: openaiConfiguration,
    })
    if ('rejected' in profile) throw Error(profile.rejected)
    const visual = judgedMessage({
      type: 'user',
      id: 'image-user',
      createdAt: at,
      blocks: [
        {
          id: 'image',
          kind: 'image',
          mediaType: 'image/png',
          data: { inline: bytes('1024x1024.png').toString('base64') },
          visibility: { toHuman: true, toModel: true },
        },
      ],
    })
    const request: PlanInput = {
      ...input(),
      routeName: modelId,
      provider: 'openai',
      messages: [message('system_reminder', 'Keep the image in history.', 'reminder'), visual],
      parameters: { reasoningEffort: 'low', maxOutputTokens: 1024 },
      snapshot: {
        ...input().snapshot,
        ...definition.capabilities,
        adaptation: profile.ok.adaptation,
        providers: profile.ok.providers,
        allowFallback: false,
      },
      tokenMargin: { multiplier: 1.1, reserveTokens: 64 },
    }
    const host = await fixture(
      cert.tls,
      res =>
        res.end(
          sse({
            model: modelId,
            provider: 'OpenAI',
            choices: [{ delta: { content: 'image answer' } }],
          }) +
            sse({
              choices: [],
              usage: {
                prompt_tokens: 9000,
                completion_tokens: 2,
                prompt_tokens_details: { cached_tokens: 0, cache_write_tokens: 0 },
                cost: 0.000123,
              },
            }) +
            finish(),
        ),
      {},
      undefined,
      [definition],
    )
    const transport = createPiAiTransport({
      ...host.options,
      definitions: [definition],
      inputMeters: [meter],
    })
    try {
      const rejected = await planRequest(
        { ...request, tokenMargin: { multiplier: 1, reserveTokens: 10000000 } },
        [definition],
        meter,
        { signal: new AbortController().signal },
        testImagePreparerFor(planRequest),
      )
      expect(rejected).toMatchObject({ rejected: 'invalidInput', reason: 'input_limit_exceeded' })
      expect(host.requests).toHaveLength(0)
      const planned = await planRequest(
        request,
        [definition],
        meter,
        {
          signal: new AbortController().signal,
        },
        testImagePreparerFor(planRequest),
      )
      if ('rejected' in planned) throw Error(JSON.stringify(planned))
      expect(planned.planned.measurement.mode).toBe('full')
      expect(planned.planned.inputLimitEvidence.inputTokens.kind).toBe('estimated')
      expect(planned.planned.inputLimitEvidence.images).toBe(1)
      const response = await invokeModel({
        ...request,
        transport,
        credential: 'local-only',
        signal: new AbortController().signal,
        policy: policy(),
      }).outcome
      if (!('outcome' in response)) throw Error(JSON.stringify(response))
      expect(response.outcome).toBe('complete')
      expect(response.inputCalibration.observedInput).toEqual({
        kind: 'unavailable',
        reason: 'scope_unknown',
      })
      expect(writeJsonLossless(response.usage.input_tokens)).toBe('9000')
      expect(writeJsonLossless(response.cost.cost_usd)).toBe('0.000123')
      expect(host.requests).toHaveLength(1)
      expect(host.requests[0]?.body).toBe(planned.planned.serialized)
      expect(host.requests[0]?.body).toContain(imageUrl('1024x1024.png'))
      expect(host.requests[0]?.body).toContain('"role":"developer"')
    } finally {
      await transport.close()
      await host.close()
    }
  })
})

tests/openai-remaining-meters-astra.spec.source:
import { testImagePreparerFor, imagePreparation } from './image-transport-support.ts'
import { afterAll, beforeAll, describe, expect, it, vi } from 'vitest'
import { ExactDecimal } from '@omne-harness-lite/call-accounts'
import { LosslessNumber, writeJsonLossless } from '@omne-harness-lite/content-blocks'
import { invokeModel, type PlanInput } from '@omne-harness-lite/model-request-runtime'
import { createOpenAiInputMeter } from '../src/input-meters/openai.ts'
import { createOfficialProfileContent } from '../src/configuration.ts'
import { openaiConfiguration, openaiDefinitions } from '../src/official-models/openai.ts'
import { createPiAiTransport } from '../src/transport.ts'
import { planRequest } from '../src/plan.ts'
import {
  at,
  certificate,
  finish,
  fixture,
  input,
  judgedMessage,
  message,
  policy,
  sse,
} from './support.ts'
import { recordTiktokenInput } from './tokenizer-input.ts'

const tokenized = recordTiktokenInput()
const definition = openaiDefinitions.find(value => value.modelId === 'openai/gpt-6-astra')!
function request(): PlanInput {
  const profile = createOfficialProfileContent(definition, {
    providers: ['openai'],
    allowFallback: false,
    configuration: openaiConfiguration,
  })
  if ('rejected' in profile) throw Error(profile.rejected)
  return {
    ...input(),
    routeName: definition.modelId,
    provider: 'openai',
    parameters: { reasoningEffort: 'low', maxOutputTokens: 1024 },
    messages: [
      message('system', 'Preserve the conversation.', 'sys'),
      message('system_reminder', 'Use the completed tool result.', 'reminder'),
      message('user', 'STABLE_PREFIX_MARKER ' + 'long history '.repeat(100), 'u1'),
      judgedMessage({
        type: 'assistant',
        id: 'tool-call-message',
        response: 'prior-tool-response',
        ending: 'complete',
        createdAt: at,
        blocks: [
          {
            id: 'tool-call',
            kind: 'tool_call',
            callId: 'call-lookup',
            tool: 'lookup',
            arguments: { query: 'saved' },
            complete: true,
            visibility: { toHuman: true, toModel: true },
