            id: 'tool-result',
            kind: 'tool_result',
            callId: 'call-lookup',
            outcome: 'completed',
            visibility: { toHuman: true, toModel: true },
            blocks: [
              {
                id: 'tool-result-text',
                kind: 'text',
                text: 'saved value',
                visibility: { toHuman: true, toModel: true },
              },
            ],
          },
        ],
      }),
      message('user', 'Answer with the saved value.', 'after-tool'),
