import { imagePreparation } from './image-transport-support.ts'
import { testDefinitions } from './definitions.ts'
import { afterAll, beforeAll, describe, expect, it } from 'vitest'
import { Context, type Plugin } from '@deepseek-ai/cordis'
import {
  invokeModel,
  type PlanInput,
  type StreamEnd,
} from '@omne-harness-lite/model-request-runtime'
import type { ArrivalEvent } from '@omne-harness-lite/arrival-events'
import {
  createModelTransportService,
  type AdaptationLease,
  type AdaptationRegistration,
  type ModelDefinition,
  type ModelTransportService,
  type RetirementPolicy,
} from '@omne-harness-lite/pi-ai-transport'
import {
  createModelPlugin as createModelPluginWithMeter,
  MODEL_TRANSPORT_SERVICE,
  piAiTransportPlugin,
} from '@omne-harness-lite/pi-ai-transport/plugin'
import {
  certificate,
  content,
  fixture,
  input,
  invocation,
  networkPolicy,
  policy,
} from './support.ts'
import { syntheticInputMeter } from './synthetic-input-meter.ts'

function createModelPlugin(definition: ModelDefinition, policy: RetirementPolicy) {
  return createModelPluginWithMeter(definition, syntheticInputMeter(definition, 'openai'), policy)
}

// Cordis 4.0.4 publishes these numeric FiberState values in its public declaration.
// The const enum has no JavaScript export for Vitest's isolated transpilation.
const fiberState = { pending: 0, active: 2, failed: 3, disposed: 4, unloading: 5 }

function deferred() {
  let resolve = () => {}
  const promise = new Promise<void>(complete => {
    resolve = complete
  })
  return { promise, resolve }
}

function retirement(force = false, onDeadline = () => {}): RetirementPolicy {
  return {
    waitMilliseconds: 30,
    force,
    schedule(milliseconds, callback) {
      const timer = setTimeout(() => {
        onDeadline()
        callback()
      }, milliseconds)
      return () => clearTimeout(timer)
    },
  }
}

function firstDefinition(): ModelDefinition {
  const definition = testDefinitions[0]
  if (!definition) throw new Error('pilot definition missing')
  return definition
}

function nextDefinition(): ModelDefinition {
  const definition = firstDefinition()
  return { ...definition, revision: `${definition.revision}-next` }
}

function requestFor(definition: ModelDefinition): PlanInput {
  const request = input()
  return {
    ...request,
    routeName: definition.modelId,
    snapshot: {
      ...request.snapshot,
      adaptation: {
        ...request.snapshot.adaptation,
        implementation: definition.implementation,
        definition: { modelId: definition.modelId, revision: definition.revision },
      },
    },
  }
}

// Lookup is an unknown boundary. Check the public service shape without asserting a type.
function isModelTransportService(value: unknown): value is ModelTransportService {
  return (
    !!value &&
    typeof value === 'object' &&
    'registerAdaptation' in value &&
    typeof value.registerAdaptation === 'function' &&
    'acquire' in value &&
    typeof value.acquire === 'function' &&
    'retire' in value &&
    typeof value.retire === 'function' &&
    'close' in value &&
    typeof value.close === 'function' &&
    'closed' in value &&
    value.closed instanceof Promise &&
    'inspect' in value &&
    typeof value.inspect === 'function'
  )
}

function serviceOf(ctx: Context): ModelTransportService {
  const value: unknown = ctx.get(MODEL_TRANSPORT_SERVICE)
  if (!isModelTransportService(value)) throw new Error('model transport service unavailable')
  return value
}

function acquire(service: ModelTransportService, request: PlanInput): AdaptationLease {
  const result = service.acquire(request.snapshot.adaptation, request.routeName)
  if ('rejected' in result) throw new Error(`acquire rejected: ${result.rejected}`)
  return result.lease
}

function register(
  service: ModelTransportService,
  definition: ModelDefinition,
  owner: object,
  cleanup: () => void | Promise<void>,
): AdaptationRegistration {
  const result = service.registerAdaptation(
    definition,
    syntheticInputMeter(definition, 'openai'),
    owner,
    cleanup,
  )
  if ('rejected' in result) throw new Error(`registration rejected: ${result.rejected}`)
  return result.registered
}

async function consume(reader: AsyncGenerator<ArrivalEvent, StreamEnd>): Promise<StreamEnd> {
  while (true) {
    const next = await reader.next()
    if (next.done) return next.value
  }
}

let cert: ReturnType<typeof certificate>
beforeAll(() => {
  cert = certificate()
})
afterAll(() => cert.dispose())

describe('actual Cordis 4.0.4 model contribution lifecycle', () => {
  it('missing stable service keeps a contribution pending; later provision activates it without false registration', async () => {
    const ctx = new Context()
    const contribution = ctx.plugin(createModelPlugin(firstDefinition(), retirement()), {})
    try {
      await new Promise<void>(resolve => setImmediate(resolve))
      expect(contribution.state).toBe(fiberState.pending)
      expect(ctx.get(MODEL_TRANSPORT_SERVICE)).toBeUndefined()
      const provider = ctx.plugin(piAiTransportPlugin, {
        imagePreparation,
        policy: networkPolicy,
        retirement: retirement(),
      })
      await provider
      await contribution
      expect(provider.state).toBe(fiberState.active)
      expect(contribution.state).toBe(fiberState.active)
      expect(serviceOf(ctx).inspect().registrations).toBe(1)
    } finally {
      await ctx.fiber.dispose()
    }
  })

  it('invalid base configuration fails its fiber and never provides the stable service', async () => {
    // Preserve the real plugin and its Config schema, while allowing malformed
    // external configuration to reach the runtime validation boundary.
    const pluginAtUnknownConfigBoundary: Plugin.Object<unknown> = piAiTransportPlugin
    const invalidConfigurations: readonly unknown[] = [
      { policy: { ...networkPolicy, maxConnections: 0 }, retirement: retirement() },
      { policy: networkPolicy },
      { policy: networkPolicy, retirement: { ...retirement(), waitMilliseconds: 0 } },
      { policy: networkPolicy, retirement: { waitMilliseconds: 30, force: false } },
    ]
    for (const config of invalidConfigurations) {
      const ctx = new Context()
      try {
        const provider = ctx.plugin(pluginAtUnknownConfigBoundary, config)
        await expect(Promise.resolve(provider)).rejects.toThrow(/invalid config/)
        expect(provider.state).toBe(fiberState.failed)
        expect(ctx.get(MODEL_TRANSPORT_SERVICE)).toBeUndefined()
      } finally {
        await ctx.fiber.dispose()
      }
    }
  })

  it('registering V2 preserves the stable service and does not rerun unrelated consumers or rebind old leases', async () => {
    const ctx = new Context()
    const leases: AdaptationLease[] = []
    let starts = 0,
      stops = 0
    const consumer: Plugin.Object = {
      name: 'model-transport-stability-consumer',
      inject: [MODEL_TRANSPORT_SERVICE],
      apply(consumerContext) {
        serviceOf(consumerContext)
        starts++
        consumerContext.effect(() => () => {
          stops++
        })
      },
    }
    try {
      const provider = ctx.plugin(piAiTransportPlugin, {
        imagePreparation,
        policy: networkPolicy,
        retirement: retirement(),
      })
      await provider
      const stable = serviceOf(ctx)
      const unrelated = ctx.plugin(consumer)
      await unrelated
      const v1 = ctx.plugin(createModelPlugin(firstDefinition(), retirement()), {})
      await v1
      const oldRequest = requestFor(firstDefinition())
      const oldLease = acquire(stable, oldRequest)
      leases.push(oldLease)
      const v2 = ctx.plugin(createModelPlugin(nextDefinition(), retirement()), {})
      await v2
      const newRequest = requestFor(nextDefinition())
      const newLease = acquire(stable, newRequest)
      leases.push(newLease)
      expect(serviceOf(ctx)).toBe(stable)
      expect(provider.state).toBe(fiberState.active)
      expect(unrelated.state).toBe(fiberState.active)
      expect(starts).toBe(1)
      expect(stops).toBe(0)
      expect(stable.inspect().registrations).toBe(2)
      expect(oldLease.binding).toEqual(oldRequest.snapshot.adaptation)
      expect(newLease.binding).toEqual(newRequest.snapshot.adaptation)
      expect(
        await oldLease.transport.plan(newRequest, { signal: new AbortController().signal }),
      ).toEqual({
        rejected: 'invalidInput',
        reason: 'malformed',
      })
      expect(
        await oldLease.transport.plan(oldRequest, { signal: new AbortController().signal }),
      ).toHaveProperty('planned')
    } finally {
      for (const lease of leases) lease.release()
      await ctx.fiber.dispose()
    }
    expect(stops).toBe(1)
  })

  it('after acquire A and an idle interval, lease B keeps retiring V1 alive while V2 remains available', async () => {
    const ctx = new Context()
    const leases: AdaptationLease[] = []
    let deadlines = 0,
      disposed = false
    let disposal: Promise<void> | undefined
    try {
      await ctx.plugin(piAiTransportPlugin, {
        imagePreparation,
        policy: networkPolicy,
        retirement: retirement(),
      })
      const service = serviceOf(ctx)
      const v1 = ctx.plugin(
        createModelPlugin(
          firstDefinition(),
          retirement(false, () => {
            deadlines++
          }),
        ),
        {},
      )
      await v1
      const oldRequest = requestFor(firstDefinition())
      const a = acquire(service, oldRequest)
      a.release()
      a.release()
      expect(service.inspect().references).toBe(0)
      await new Promise<void>(resolve => setImmediate(resolve))
      const b = acquire(service, oldRequest)
      leases.push(b)
      expect(service.inspect().references).toBe(1)
      const v2 = ctx.plugin(createModelPlugin(nextDefinition(), retirement()), {})
      await v2
      disposal = v1.dispose().then(() => {
        disposed = true
      })
      await expect.poll(() => service.inspect().retiring).toBe(1)
      expect(service.acquire(oldRequest.snapshot.adaptation, oldRequest.routeName)).toEqual({
        rejected: 'unavailable',
      })
      expect(
        await b.transport.plan(oldRequest, { signal: new AbortController().signal }),
      ).toHaveProperty('planned')
      await expect.poll(() => deadlines).toBeGreaterThan(0)
      expect(disposed).toBe(false)
      expect(v1.state).toBe(fiberState.unloading)
      expect(service.inspect()).toMatchObject({ registrations: 2, retiring: 1, references: 1 })
      const current = acquire(service, requestFor(nextDefinition()))
      leases.push(current)
      b.release()
      b.release()
      await disposal
      expect(v1.state).toBe(fiberState.disposed)
      expect(service.inspect()).toMatchObject({ registrations: 1, references: 1 })
      expect(
        await current.transport.plan(requestFor(nextDefinition()), {
          signal: new AbortController().signal,
        }),
      ).toHaveProperty('planned')
    } finally {
      for (const lease of leases) lease.release()
      if (disposal) await disposal
      await ctx.fiber.dispose()
    }
  })
})

describe('public registry actual HTTPS execution ownership', () => {
  it('retirement timeout reports remaining work; completed historical retirement cannot remove a replacement contribution', async () => {
    const service = createModelTransportService({ imagePreparation, policy: networkPolicy })
    const cleanup = deferred()
    const leases: AdaptationLease[] = []
    let cleanups = 0
    try {
      const old = register(service, firstDefinition(), {}, () => {
        cleanups++
        return cleanup.promise
      })
      const lease = acquire(service, requestFor(firstDefinition()))
      leases.push(lease)
      expect(await service.retire(old, retirement())).toEqual({
        remaining_active: true,
        references: 1,
        executions: 0,
      })
      expect(cleanups).toBe(0)
      expect(
        await lease.transport.plan(requestFor(firstDefinition()), {
          signal: new AbortController().signal,
        }),
      ).toHaveProperty('planned')
      lease.release()
      await expect.poll(() => cleanups).toBe(1)
      expect(service.inspect().registrations).toBe(1)
      cleanup.resolve()
      expect(await service.retire(old, retirement())).toEqual({ retired: true })
      const replacement = register(service, firstDefinition(), {}, () => {
        cleanups++
      })
      const replacementLease = acquire(service, requestFor(firstDefinition()))
      leases.push(replacementLease)
      expect(await service.retire(old, retirement())).toEqual({ retired: true })
      expect(service.inspect()).toMatchObject({ registrations: 1, retiring: 0, references: 1 })
      expect(
        await replacementLease.transport.plan(requestFor(firstDefinition()), {
          signal: new AbortController().signal,
        }),
      ).toHaveProperty('planned')
      replacementLease.release()
      expect(await service.retire(replacement, retirement())).toEqual({ retired: true })
      expect(cleanups).toBe(2)
    } finally {
      cleanup.resolve()
      for (const lease of leases) lease.release()
      await service.close(retirement(true))
      await service.closed
    }
  })

  it('real Cordis forced contribution disposal stops both HTTPS consumers and waits for tracked callbacks', async () => {
    const host = await fixture(cert.tls, res => {
      res.writeHead(200, { 'content-type': 'text/event-stream' })
      res.write(content('unapproved-content'))
    })
    const service = createModelTransportService(host.options)
    const ctx = new Context()
    const request = requestFor(firstDefinition())
    const direct = deferred(),
      gate = deferred()
    const leases: AdaptationLease[] = []
    let deadlines = 0,
      contributionDisposed = false,
      providerDisposed = false,
      gateEntered = false
    let disposal: Promise<void> | undefined
    try {
      // A trusted local assembly supplies the same public production registry
      // with explicit HTTPS fixture options. The production plugin endpoint
      // configuration remains unchanged; no replacement Cordis is involved.
      const localProvider: Plugin.Object = {
        name: 'local-https-model-transport-assembly',
        apply(providerContext) {
          providerContext.provide(MODEL_TRANSPORT_SERVICE, service)
          providerContext.effect(() => async () => {
            await service.close(retirement(true))
            await service.closed
            providerDisposed = true
          })
        },
      }
      await ctx.plugin(localProvider)
      const contribution = ctx.plugin(
        createModelPlugin(
          firstDefinition(),
          retirement(true, () => {
            deadlines++
          }),
        ),
        {},
      )
      await contribution
      expect(serviceOf(ctx)).toBe(service)
      const directLease = acquire(service, request)
      leases.push(directLease)
      directLease.track(direct.promise)
      const planned = await directLease.transport.plan(request, {
        signal: new AbortController().signal,
      })
      if ('rejected' in planned) throw new Error('direct plan rejected')
      const cancellation = new AbortController()
      const sent = await directLease.transport.send(
        planned.planned,
        'fixture-test-secret',
        cancellation.signal,
      )
      if (!('response' in sent)) throw new Error('direct response unavailable')
      const directReading = consume(
        directLease.transport.read(sent.response, planned.planned, cancellation.signal),
      )
      const runtimeLease = acquire(service, request)
      leases.push(runtimeLease)
      runtimeLease.track(gate.promise)
      const handle = invokeModel({
        ...request,
        transport: runtimeLease.transport,
        credential: 'fixture-test-secret',
        signal: runtimeLease.signal,
        policy: policy(),
        beforeFirstContent: () => {
          gateEntered = true
          return gate.promise
        },
      })
      runtimeLease.track(handle.outcome)
      await expect.poll(() => gateEntered).toBe(true)
      expect(host.requests).toHaveLength(2)
      expect(host.closedSockets()).toBe(0)
      disposal = contribution.dispose().then(() => {
        contributionDisposed = true
      })
      await expect.poll(() => deadlines).toBeGreaterThan(0)
      expect(directLease.signal.aborted).toBe(true)
      expect(runtimeLease.signal.aborted).toBe(true)
      expect(await directReading).toHaveProperty('aborted', true)
      const result = invocation(await handle.outcome)
      expect(result.outcome).toBe('interrupted')
      expect(result.blocks).toEqual([])
      await expect.poll(host.closedSockets).toBe(2)
      directLease.release()
      runtimeLease.release()
      expect(service.inspect()).toMatchObject({
        registrations: 1,
        retiring: 1,
        references: 2,
        executions: 2,
      })
      expect(contributionDisposed).toBe(false)
      expect(providerDisposed).toBe(false)
      expect(contribution.state).toBe(fiberState.unloading)
      direct.resolve()
      gate.resolve()
      await disposal
      expect(contributionDisposed).toBe(true)
      expect(contribution.state).toBe(fiberState.disposed)
      expect(service.inspect()).toMatchObject({ registrations: 0, references: 0, executions: 0 })
      expect(host.requests).toHaveLength(2)
    } finally {
      direct.resolve()
      gate.resolve()
      for (const lease of leases) lease.release()
      if (disposal) await disposal
      await ctx.fiber.dispose()
      // Also releases the factory on any pre-provider initialization failure.
      await service.close(retirement(true))
      await service.closed
      await host.close()
    }
    expect(providerDisposed).toBe(true)
  })
})

tests/qwen-commercial-template.spec.ts.source:
// QC-V2 and QC-V3 of the adopted Qwen commercial public-template estimate (candidate
// revision 1): the template oracle against independent Jinja goldens, the batch8
// reproduction (counterexample 17), the equivalence oracle and the open-leaf regression
// oracle (counterexample 14). Goldens come from real Jinja2 + HF tokenizers
// (fixtures/qwen/commercial-reference-render.py; batch8 from the QC-V0 recompute), never
// from the package renderer.
import { createHash } from 'node:crypto'
import { readFileSync } from 'node:fs'
import { beforeAll, describe, expect, it } from 'vitest'
import { Tokenizer } from '@huggingface/tokenizers'
import {
  readJsonStrict,
  writeJsonLossless,
  type JsonObject,
  type JsonValue,
} from '@omne-harness-lite/content-blocks'
import {
  createQwenInputMeter,
  projectQwenMeterBody,
  qwenOpenTemplateSettings,
  renderQwenPrompt,
  type QwenTemplateSettings,
} from '../src/input-meters/qwen.ts'
import { object } from '../src/json.ts'
import { qwenDefinitions } from '../src/official-models/qwen.ts'
import { directFull } from './direct-full-input.ts'
import { asReasoningString, serialized } from './moonshot-visible-support.ts'
import {
  qwenBatch8,
  qwenCommercialMeter,
  qwenCommercialModels,
  qwenFamilySettings,
} from './qwen-commercial-support.ts'

function readFixture(name: string): JsonObject {
  const parsed = readJsonStrict(
    readFileSync(new URL(`./fixtures/qwen/${name}`, import.meta.url), 'utf8'),
  )
  if (!('ok' in parsed) || !object(parsed.ok)) throw new Error(`invalid ${name}`)
  return parsed.ok
}

const source = readFixture('commercial-template-cases.json')
const golden = readFixture('commercial-template-golden.json')
const capture = readFixture('open-regression-capture.json')
if (!Array.isArray(source.cases) || !object(golden.cases) || !object(capture.rows))
  throw new Error('invalid template fixtures')
const cases = source.cases.filter(object)
const goldenCases = golden.cases
const captureRows = capture.rows

function caseBody(value: JsonObject, modelId: string): JsonObject {
  const tools = typeof value.tools === 'string' ? source[value.tools] : undefined
  if (!Array.isArray(value.messages)) throw new Error('case messages')
  return {
    model: modelId,
    provider: { order: ['alibaba'], allow_fallbacks: false, require_parameters: true },
    stream: true,
    messages: value.messages,
    ...(tools === undefined ? {} : { tools: [tools] }),
  }
}

function goldenRow(name: string, key: string): { promptSha256: string; tokens: number } {
  const rows = goldenCases[name]
  const row = object(rows) ? rows[key] : undefined
  if (!object(row) || typeof row.promptSha256 !== 'string' || typeof row.tokens !== 'number')
    throw new Error(`golden ${name} ${key}`)
  return { promptSha256: row.promptSha256, tokens: row.tokens }
}

function settingsKey(settings: QwenTemplateSettings): string {
  return `thinking=${settings.preserveThinking ? 'all' : 'last-turn'},instruction=${settings.effortInstruction},tojson=${settings.toolJson}`
}

const sha = (text: string | undefined) =>
  text === undefined ? undefined : createHash('sha256').update(text).digest('hex')

function render(body: JsonObject, settings?: QwenTemplateSettings): string | undefined {
  const projected = projectQwenMeterBody(body)
  return projected && renderQwenPrompt(projected, settings)
}

// An independent handle on the pinned tokenizer, for counts under settings no leaf binds.
let tokenizer: Tokenizer
beforeAll(() => {
  const directory = new URL('../tokenizers/qwen-38-24t/', import.meta.url)
  tokenizer = new Tokenizer(
    JSON.parse(readFileSync(new URL('tokenizer.json', directory), 'utf8')),
    JSON.parse(readFileSync(new URL('tokenizer_config.json', directory), 'utf8')),
  )
  for (const model of qwenCommercialModels) qwenCommercialMeter(model)
}, 120_000)
const count = (text: string) => tokenizer.encode(text, { add_special_tokens: false }).ids.length

const matrix: QwenTemplateSettings[] = [true, false].flatMap(preserveThinking =>
  (['xhigh', 'none'] as const).map(effortInstruction => ({
    preserveThinking,
    effortInstruction,
    toolJson: 'wire-order' as const,
  })),
)

describe('QC-V2 template oracle: parameterized renderer equals independent Jinja', () => {
  it('fixtures pin the same template and tokenizer bytes', () => {
    expect(golden.chatTemplateSha256).toBe(
      createHash('sha256')
        .update(
          readFileSync(new URL('../tokenizers/qwen-38-24t/chat_template.jinja', import.meta.url)),
        )
        .digest('hex'),
    )
    expect(golden.tokenizerSha256).toBe(
      '0997f410c57a1f4e53b09e4be8f4a172d90edd9564368fb0847030937229b9f3',
    )
    expect(cases.map(value => value.name)).toEqual(Object.keys(goldenCases))
  })

  it.each(cases.map(value => ({ name: String(value.name), value })))(
    '$name: preserve_thinking {default,false} × instruction {xhigh,none}',
    ({ name, value }) => {
      const body = caseBody(value, 'qwen/qwen3.8-flash')
      const prompts = new Set<string>()
      for (const settings of matrix) {
        const expected = goldenRow(name, settingsKey(settings))
        const prompt = render(body, settings)
        if (prompt === undefined) throw new Error(`${name} ${settingsKey(settings)} unrendered`)
        expect(sha(prompt), settingsKey(settings)).toBe(expected.promptSha256)
        expect(count(prompt), settingsKey(settings)).toBe(expected.tokens)
        prompts.add(prompt)
      }
      // The two instruction values always differ; thinking differs unless no assistant
      // precedes the last user query.
      expect(prompts.size).toBeGreaterThanOrEqual(2)
    },
  )

  it.each(qwenCommercialModels)(
    '$modelId factory counts every case with its bound settings',
    model => {
      const settings = qwenFamilySettings[model.family]
      for (const value of cases) {
        const name = String(value.name)
        const body = caseBody(value, model.modelId)
        const expected = goldenRow(name, settingsKey(settings))
        expect(directFull(qwenCommercialMeter(model), serialized(body)), name).toEqual({
          kind: 'estimated',
          tokens: expected.tokens,
        })
      }
    },
  )

  it('geometry: last-turn thinking drops only assistants before the last user query', () => {
    const last = qwenFamilySettings['3.7']
    const think = (name: string) => {
      const value = cases.find(item => item.name === name)
      if (!value) throw new Error(name)
      return render(caseBody(value, 'qwen/qwen3.7-flash'), last)?.split('<think>\n').length
    }
    // Generation prompt always opens one think block; count the rest.
    expect(think('assistant-before-last-query')).toBe(2) // dropped
    expect(think('assistant-after-last-query')).toBe(3) // kept: in-turn tool loop
    expect(think('consecutive-tool-results')).toBe(2) // both before the new query
    expect(think('wrapped-tool-response-user')).toBe(3) // wrapped user is not a query
    expect(think('reminder-after-tool-result')).toBe(2) // a reminder user is a query
  })
})

describe('QC-V2 and counterexample 17: batch8 18 rebuilt bodies reproduce upstream', () => {
  it('residual 0 on every request; sorted-key tojson would give +1', () => {
    expect(qwenBatch8).toHaveLength(18)
    const table: string[] = []
    for (const row of qwenBatch8) {
      const model = qwenCommercialModels.find(item => item.modelId === `qwen/${row.leaf}`)
      if (!model) throw new Error(row.leaf)
      const settings = qwenFamilySettings[model.family]
      expect(writeJsonLossless(row.body)).toBe(row.wire)
      const measured = directFull(qwenCommercialMeter(model), {
        body: row.body,
        serialized: row.wire,
      })
      if (measured.kind !== 'estimated') throw new Error(`${row.leaf} ${row.round} unavailable`)
      const tokens = Number(measured.tokens)
      table.push(`${row.leaf} r${row.round} ${tokens - row.upstreamPromptTokens}`)
      expect(tokens, `${row.leaf} round ${row.round}`).toBe(row.upstreamPromptTokens)
      expect(tokens).toBe(row.predictedWireOrder)
      // The rendered prompt is byte-identical to the independent Jinja rendering (the meter
      // strips 0902's high effort before rendering; so does this direct call).
      const effortless = noEffort(row.body)
      expect(sha(render(effortless, settings))).toBe(row.promptSha256WireOrder)
      // Negative control: Jinja's built-in sorted-key tojson reproduces the QC-V0 +1.
      const sorted = render(effortless, { ...settings, toolJson: 'sorted-keys' })
      if (sorted === undefined) throw new Error('sorted-key render')
      expect(count(sorted)).toBe(row.predictedSortedKeys)
      expect(count(sorted) - row.upstreamPromptTokens).toBe(1)
      // Negative control: the other family's thinking/instruction settings do not fit.
      const swapped = render(effortless, qwenFamilySettings[model.family === '3.8' ? '3.7' : '3.8'])
      if (swapped === undefined) throw new Error('swapped render')
      expect(count(swapped)).not.toBe(row.upstreamPromptTokens)
    }
    expect(table.every(line => line.endsWith(' 0'))).toBe(true)
  })
})

describe('QC-V3 equivalence oracle: details and the `reasoning` string count the same', () => {
  it.each(qwenCommercialModels)('$modelId on batch8 bodies and every template case', model => {
    const meter = qwenCommercialMeter(model)
    const bodies: JsonObject[] = [
      ...qwenBatch8.map(row => forLeaf(row.body, model.modelId)),
      ...cases.map(value => caseBody(value, model.modelId)),
    ]
    let compared = 0
    for (const body of bodies) {
      const details = directFull(meter, serialized(body))
      if (details.kind !== 'estimated') throw new Error('details form unavailable')
      expect(directFull(meter, serialized(asReasoningString(body)))).toEqual(details)
      compared++
    }
    expect(compared).toBe(18 + cases.length)
  })
})

function noEffort(body: JsonObject): JsonObject {
  return Object.fromEntries(Object.entries(body).filter(([key]) => key !== 'reasoning'))
}

/** A batch8 body moved to another leaf's route: its effort and cache domain, same history. */
function forLeaf(body: JsonObject, modelId: string): JsonObject {
  const definition = qwenDefinitions.find(item => item.modelId === modelId)
  const automatic = definition?.routes.alibaba?.cache.mode === 'automatic'
  const moved = modelId === 'qwen/qwen3.8-max-0902' ? body : noEffort(body)
  return {
    ...moved,
    model: modelId,
    messages: (Array.isArray(body.messages) ? body.messages : []).map(message =>
      automatic && object(message) && Array.isArray(message.content)
        ? {
            ...message,
            content: message.content.map(part =>
              object(part)
                ? Object.fromEntries(
                    Object.entries(part).filter(([key]) => key !== 'cache_control'),
                  )
                : part,
            ),
          }
        : message,
    ),
  }
}

describe('QC-V3 and counterexample 14: open leaves are byte-for-byte unchanged', () => {
  it.each(['qwen/qwen3.8-2.4t-a95b', 'qwen/qwen3.8-27b'])(
    '%s renders and counts every case as captured before the change',
    modelId => {
      const definition = qwenDefinitions.find(item => item.modelId === modelId)
      if (!definition) throw new Error(modelId)
      expect(definition).toMatchObject({
        revision: '4',
        implementation: { name: 'pi-ai:qwen', revision: 'mp4-19' },
      })
      const meter = createQwenInputMeter(definition)
      expect(meter.algorithmRevision).toBe(
        modelId === 'qwen/qwen3.8-27b'
          ? 'qwen-38-public-template-image-effort-5'
          : 'qwen-38-public-template-effort-4',
      )
      expect(meter.tokenizerRevision).toBe(
        modelId === 'qwen/qwen3.8-27b'
          ? 'tokenizer-basis/qwen-38-public-template-image-effort-4'
          : 'tokenizer-basis/qwen-38-public-template-effort-3',
      )
      const rows = captureRows[modelId]
      if (!object(rows)) throw new Error('capture rows')
      for (const value of cases) {
        const name = String(value.name)
        const row = rows[name]
        if (!object(row)) throw new Error(`capture ${name}`)
        const body = caseBody(value, modelId)
        const prompt = render(body)
        expect(sha(prompt), name).toBe(row.promptSha256)
        expect(render(body, qwenOpenTemplateSettings)).toBe(prompt)
        // The unchanged open path is also the independent Jinja sorted-key rendering.
        expect(sha(prompt)).toBe(
          goldenRow(name, 'thinking=all,instruction=xhigh,tojson=sorted-keys').promptSha256,
        )
        expect(directFull(meter, serialized(body)), name).toEqual({
          kind: 'estimated',
          tokens: row.tokens as JsonValue,
        })
      }
    },
  )
})

