import { afterAll, beforeAll, describe, expect, it } from 'vitest'
import {
  LosslessNumber,
  writeJsonLossless,
  type JsonNumber,
} from '@omne-harness-lite/content-blocks'
import { getEventListeners } from 'node:events'
import { ExactDecimal } from '@omne-harness-lite/call-accounts'
import { readStream } from '@omne-harness-lite/pi-ai-transport'
import { invokeModel } from '@omne-harness-lite/model-request-runtime'
import type { ArrivalEvent } from '@omne-harness-lite/arrival-events'
import { certificate, fixture, finish, input, invocation, planned, policy, sse } from './support.ts'

let cert: ReturnType<typeof certificate>
beforeAll(() => {
  cert = certificate()
})
afterAll(() => cert.dispose())
function expectTokens(value: JsonNumber | 'unknown', expected: number) {
  if (value === 'unknown') throw Error('expected known tokens')
  expect(ExactDecimal.from(value).compare(ExactDecimal.from(expected))).toBe(0)
}
const refusal = (text: unknown) => sse({ choices: [{ delta: { refusal: text } }] })
const usage = {
  prompt_tokens: 123,
  completion_tokens: 7,
  prompt_tokens_details: { cached_tokens: 20, cache_write_tokens: 3 },
  cost: new LosslessNumber('0.000123456789123456789'),
}
async function run(body: string, credential = 'synthetic-refusal-credential') {
  const events: ArrivalEvent[] = [],
    diagnostics: unknown[] = []
  const host = await fixture(
    cert.tls,
    res => res.end(body),
    {},
    event => {
      diagnostics.push(event)
    },
  )
  try {
    const result = invocation(
      await invokeModel({
        ...input(),
        transport: host.transport,
        credential,
        signal: new AbortController().signal,
        policy: policy(),
        onAccepted: event => {
          events.push(event)
        },
      }).outcome,
    )
    expect(host.requests).toHaveLength(1)
    return { result, events, diagnostics }
  } finally {
    await host.close()
  }
}

describe('D108 refusal mapping through shared production reader over TLS', () => {
  it('RF-V1 pure whitespace is actual content', async () => {
    const { result } = await run(refusal(' \t\n') + finish())
    expect(result.outcome).toBe('complete')
    expect(result.timing.firstTokenAt).toBeDefined()
    expect(result.blocks).toMatchObject([{ text: ' \t\n' }])
  })
  it('RF-V5 late in-band error preserves refusal and earlier facts without reading future usage', async () => {
    const { result, events } = await run(
      sse({ choices: [{ delta: { refusal: 'already delivered' } }], usage }) +
        sse({ error: { code: 503, message: 'unavailable' } }) +
        sse({ choices: [], usage: { prompt_tokens: 999 } }) +
        finish(),
    )
    expect(result.outcome).toBe('failed')
    expect(result.failure).toMatchObject({
      cause: 'interrupted_mid_reply',
      statusCode: 503,
      inBand: true,
    })
    expect(result.blocks).toMatchObject([{ text: 'already delivered' }])
    expectTokens(result.usage.input_tokens, 100)
    expect(events.filter(event => event.t === 'account')).toHaveLength(1)
  })
  for (const mode of ['cancel', 'idle-timeout'] as const) {
    it(`RF-V7 ${mode} after refusal stops a hanging socket and retains already-read facts`, async () => {
      const events: ArrivalEvent[] = []
      const host = await fixture(cert.tls, res => {
        res.writeHead(200, { 'content-type': 'text/event-stream' })
        res.write(sse({ choices: [{ delta: { refusal: 'partial' } }], usage }))
      })
      try {
        const handle = invokeModel({
          ...input(),
          transport: host.transport,
          credential: 'synthetic-credential',
          signal: new AbortController().signal,
          policy: { ...policy(), idleContentTimeoutMs: mode === 'idle-timeout' ? 80 : 3000 },
          onAccepted: event => {
            events.push(event)
          },
        })
        if (mode === 'cancel') {
          await expect.poll(() => events.some(event => event.t === 'fill')).toBe(true)
          handle.abort()
        }
        const result = invocation(await handle.outcome)
        expect(result.outcome).toBe(mode === 'cancel' ? 'interrupted' : 'failed')
        expect(result.ending).toBe(mode === 'cancel' ? 'interrupted_by_user' : undefined)
        if (mode === 'cancel') expect(result.failure).toBeUndefined()
        else expect(result.failure?.cause).toBe('interrupted_mid_reply')
        expect(result.blocks).toMatchObject([{ text: 'partial' }])
        expectTokens(result.usage.input_tokens, 100)
        expect(writeJsonLossless(result.cost)).toContain('0.000123456789123456789')
        // Cancellation closes the event sequence; already-read facts travel in the final outcome.
        expect(events.filter(event => event.t === 'account')).toHaveLength(0)
        await expect.poll(host.closedSockets).toBe(1)
        expect(host.requests).toHaveLength(1)
      } finally {
        await host.close()
      }
    })
  }
  for (const [label, delta] of [
    ['missing', {}],
    ['null', { refusal: null }],
    ['empty', { refusal: '' }],
  ] as const) {
    it(`RF-V1 ${label} neither opens a block nor passes the first-content gate`, async () => {
      const { result, events } = await run(sse({ choices: [{ delta }] }) + finish())
      expect(result.blocks).toEqual([])
      expect(result.timing.firstTokenAt).toBeUndefined()
      expect(events.some(event => ['open', 'fill', 'close'].includes(event.t))).toBe(false)
    })
  }
  for (const value of [false, true, 0, 42, [], ['private-invalid'], { text: 'private-invalid' }]) {
    it(`RF-V1 invalid ${JSON.stringify(value)} rejects before same-frame content and preserves facts`, async () => {
      const { result, events, diagnostics } = await run(
        sse({
          choices: [{ delta: { content: 'must-not-leak', refusal: value } }],
          usage,
        }) +
          sse({ choices: [], usage: { prompt_tokens: 999 } }) +
          finish(),
      )
      expect(result.outcome).toBe('failed')
      expect(result.failure?.localError).toBe('invalid refusal')
      expect(result.blocks).toEqual([])
      expectTokens(result.usage.input_tokens, 100)
      expect(result.usage).toMatchObject({
        output_tokens: 7,
        cache_read_tokens: 20,
        cache_write_tokens: 3,
      })
      expect(writeJsonLossless(result.cost)).toContain('0.000123456789123456789')
      expect(events.filter(event => event.t === 'account')).toHaveLength(1)
      expect(writeJsonLossless([result, diagnostics])).not.toContain('private-invalid')
      expect(writeJsonLossless([result, diagnostics])).not.toContain('must-not-leak')
    })
  }
  it('RF-V1/V2 actual whitespace/unicode, frame order and deterministic same-frame order share one text block', async () => {
    // JSON key insertion order deliberately places refusal before content.
    const body =
      refusal('拒答🙂') +
      sse({ choices: [{ delta: { refusal: ' R ', content: 'C' } }] }) +
      sse({ choices: [{ delta: { content: 'later', refusal: '\n', reasoning: 'thinking' } }] }) +
      finish()
    const { result, events } = await run(body)
    expect(result.outcome).toBe('complete')
    expect(result.blocks).toMatchObject([
      { kind: 'text', text: '拒答🙂C R later\n' },
      { kind: 'thinking', text: 'thinking' },
    ])
    expect(
      events
        .filter(event => event.t === 'open')
        .map(event => ({ kind: event.kind, index: writeJsonLossless(event.index) })),
    ).toEqual([
      { kind: 'text', index: '0' },
      { kind: 'thinking', index: '1' },
    ])
    expect(events.filter(event => event.t === 'fill').map(event => event.payload)).toEqual([
      '拒答🙂',
      'C',
      ' R ',
      'later',
      '\n',
      'thinking',
    ])
    const text = result.blocks[0]
    expect(text).not.toHaveProperty('origin')
    expect(text).not.toHaveProperty('opaque')
  })
  it('RF-V2 shared text channel keeps existing thinking and tool opening order', async () => {
    const { result, events } = await run(
      sse({ choices: [{ delta: { reasoning: 'think' } }] }) +
        sse({
          choices: [
            {
              delta: {
                refusal: 'refuse',
                tool_calls: [
                  {
                    index: 0,
                    type: 'function',
                    function: { name: 'lookup', arguments: '{"x":1}' },
                  },
                ],
              },
            },
          ],
        }) +
        sse({ choices: [{ delta: { content: 'after' } }] }) +
        finish('tool_calls'),
    )
    expect(result.outcome).toBe('complete')
    expect(
      events
        .filter(event => event.t === 'open')
        .map(event => ({ kind: event.kind, index: writeJsonLossless(event.index) })),
    ).toEqual([
      { kind: 'thinking', index: '0' },
      { kind: 'text', index: '1' },
      { kind: 'tool_call', index: '2' },
    ])
    expect(result.blocks).toMatchObject([
      { kind: 'thinking', text: 'think' },
      { kind: 'text', text: 'refuseafter' },
      { kind: 'tool_call', tool: 'lookup' },
    ])
  })
  for (const reason of ['stop', 'tool_calls', 'length']) {
    it(`RF-V4 ${reason} uses actual finish and reads normal trailing usage before DONE`, async () => {
      const { result, events } = await run(
        refusal('actual refusal') +
          sse({ choices: [{ delta: {}, finish_reason: reason }] }) +
          sse({ choices: [{ delta: { refusal: '' }, finish_reason: reason }], usage }) +
          sse('[DONE]'),
      )
      expect(result.outcome).toBe(reason === 'length' ? 'truncated' : 'complete')
      expect(result.ending).toBe(reason === 'length' ? 'truncated_at_limit' : 'complete')
      expect(result.blocks).toMatchObject([{ kind: 'text', text: 'actual refusal' }])
      expect(result.failure).toBeUndefined()
      expectTokens(result.usage.input_tokens, 100)
      expect(result.usage).toMatchObject({
        output_tokens: 7,
        source: 'upstream',
      })
      expect(events.filter(event => event.t === 'account')).toHaveLength(1)
      expect(events.filter(event => event.t === 'close')).toHaveLength(reason === 'length' ? 0 : 1)
    })
  }
  for (const [label, tail, expected] of [
    [
      'content_filter',
      sse({ choices: [{ delta: {}, finish_reason: 'content_filter' }] }),
      undefined,
    ],
    ['error finish', sse({ choices: [{ delta: {}, finish_reason: 'error' }] }), undefined],
    ['EOF', '', 'stream ended before terminal facts'],
    ['bad JSON', 'data: {bad}\n\n', 'invalid SSE JSON'],
    ['duplicate key', 'data: {"choices":[],"choices":[]}\n\n', 'invalid SSE JSON'],
    [
      'changed finish',
      sse({ choices: [{ delta: {}, finish_reason: 'stop' }] }) +
        sse({ choices: [{ delta: {}, finish_reason: 'length' }] }),
      'finish_reason changed',
    ],
    [
      'late refusal',
      sse({ choices: [{ delta: {}, finish_reason: 'stop' }] }) + refusal('late'),
      'content after finish_reason',
    ],
    ['DONE without finish', sse('[DONE]'), 'stream ended before terminal facts'],
  ] as const) {
    it(`RF-V5 ${label} keeps delivered text without a successful reply or invented later usage`, async () => {
      const { result, events } = await run(refusal('delivered refusal') + tail)
      expect(result.outcome).toBe('failed')
      expect(result.failure?.cause).toBe('interrupted_mid_reply')
      if (expected) expect(result.failure?.localError).toBe(expected)
      expect(result.ending).toBeUndefined()
      expect(result.blocks).toMatchObject([{ kind: 'text', text: 'delivered refusal' }])
      expect(result.usage.input_tokens).toBe('unknown')
      expect(events.filter(event => event.t === 'close')).toHaveLength(0)
    })
  }
  it('RF-V5/V8 same-frame error wins over refusal/content, preserves independent 503 and same-frame exact usage', async () => {
    const { result, events } = await run(
      sse({
        error: { code: 503, message: '503' },
        usage,
        choices: [{ delta: { content: 'must-not-leak', refusal: 'must-not-leak' } }],
      }) + sse({ choices: [], usage: { prompt_tokens: 999 } }),
      '503',
    )
    expect(result.outcome).toBe('failed')
    expect(result.failure).toMatchObject({ statusCode: 503, inBand: true })
    expect(writeJsonLossless(result.failure?.upstreamError)).not.toContain('"message":"503"')
    expect(result.blocks).toEqual([])
    expectTokens(result.usage.input_tokens, 100)
    expect(events.filter(event => event.t === 'account')).toHaveLength(1)
  })
  it('RF-V6 accounting before/same/after refusal is one account and conflicts remain unavailable', async () => {
    const { result, events } = await run(
      sse({ choices: [], usage }) +
        sse({ choices: [{ delta: { refusal: 'text' } }], usage }) +
        sse({
          choices: [{ delta: {}, finish_reason: 'stop' }],
          usage: { ...usage, prompt_tokens: 124 },
        }) +
        sse('[DONE]'),
    )
    expect(result.outcome).toBe('complete')
    expect(result.inputCalibration.observedInput).toMatchObject({
      kind: 'unavailable',
      reason: 'inconsistent_usage',
    })
    expect(events.filter(event => event.t === 'account')).toHaveLength(1)
    expectTokens(result.usage.input_tokens, 100)
  })
  it('RF-V8 legal reply text is unchanged by credential policy and diagnostics do not copy it', async () => {
    const { result, diagnostics } = await run(refusal('503') + finish(), '503')
    expect(result.blocks).toMatchObject([{ text: '503' }])
    expect(JSON.stringify(diagnostics)).not.toContain('503')
  })
  it('RF-V9 exported readStream path yields the same refusal text and settles stopped', async () => {
    const host = await fixture(cert.tls, res => res.end(refusal('public reader') + finish()))
    try {
      const request = await planned(host.transport)
      const sent = await host.transport.send(
        request,
        'synthetic-credential',
        new AbortController().signal,
      )
      if (!('response' in sent)) throw Error('expected actual response')
      const signal = new AbortController().signal
      const listenersBefore = getEventListeners(signal, 'abort').length
      const iterator = readStream(sent.response, request, signal, {
        maxSseEventBytes: 16384,
        diagnostic: () => {},
      })
      const events: ArrivalEvent[] = []
      let end = await iterator.next()
      while (!end.done) {
        events.push(end.value)
        end = await iterator.next()
      }
      expect(end.value).toMatchObject({ ended: 'end' })
      expect(events.filter(event => event.t === 'fill')).toMatchObject([
        { payload: 'public reader' },
      ])
      await sent.response.stopped
      expect(getEventListeners(signal, 'abort')).toHaveLength(listenersBefore)
      expect(host.requests).toHaveLength(1)
    } finally {
      await host.close()
    }
  })
  it('RF-V7 direct reader cancellation removes its listener and actually stops without later facts', async () => {
    const host = await fixture(cert.tls, res => {
      res.writeHead(200, { 'content-type': 'text/event-stream' })
      res.write(refusal('read before abort'))
    })
    try {
      const request = await planned(host.transport)
      const controller = new AbortController()
      const initialListeners = getEventListeners(controller.signal, 'abort').length
      const sent = await host.transport.send(request, 'synthetic-credential', controller.signal)
      if (!('response' in sent)) throw Error('expected actual response')
      const iterator = readStream(sent.response, request, controller.signal, {
        maxSseEventBytes: 16384,
        diagnostic: () => {},
      })
      expect((await iterator.next()).value).toMatchObject({ t: 'open', kind: 'text' })
      expect((await iterator.next()).value).toMatchObject({
        t: 'fill',
        payload: 'read before abort',
      })
      controller.abort()
      const ended = await iterator.next()
      expect(ended.done).toBe(true)
      expect(ended.value).toMatchObject({
        aborted: true,
        readFacts: { usage: { input_tokens: 'unknown' }, cost: { cost_usd: 'unknown' } },
      })
      await sent.response.stopped
      await expect.poll(host.closedSockets).toBe(1)
      expect(getEventListeners(controller.signal, 'abort')).toHaveLength(initialListeners)
      expect(host.requests).toHaveLength(1)
    } finally {
      await host.close()
    }
  })
  it('RF-V5 oversized later event fails without discarding refusal already delivered', async () => {
    const { result } = await run(refusal('retained') + refusal('x'.repeat(20000)) + finish())
    expect(result.outcome).toBe('failed')
    expect(result.failure?.cause).toBe('interrupted_mid_reply')
    expect(result.blocks).toMatchObject([{ text: 'retained' }])
    expect(result.usage.input_tokens).toBe('unknown')
  })
})

tests/registry-diagnostics.spec.ts.source:
import { imagePreparation } from './image-transport-support.ts'
import { Context } from '@deepseek-ai/cordis'
import {
  createDiagnosticCollector,
  type DiagnosticCollectorConfig,
  type DiagnosticEvent,
  type DiagnosticJournalStore,
  type DiagnosticRecord,
} from '@omne-harness-lite/model-request-runtime'
import {
  createModelTransportService,
  type ModelDefinition,
  type ModelTransportService,
  type RetirementPolicy,
} from '@omne-harness-lite/pi-ai-transport'
import {
  createModelPlugin,
  MODEL_TRANSPORT_SERVICE,
  piAiTransportPlugin,
} from '@omne-harness-lite/pi-ai-transport/plugin'
import { describe, expect, it } from 'vitest'
import { testDefinitions } from './definitions.ts'
import { syntheticInputMeter } from './synthetic-input-meter.ts'
import { input, networkPolicy } from './support.ts'

const definition: ModelDefinition = (() => {
  const found = testDefinitions[0]
  if (!found) throw new Error('missing controlled definition')
  return found
})()

function policy(force = false): RetirementPolicy {
  return {
    force,
    waitMilliseconds: 15,
    schedule(milliseconds, callback) {
      const timer = setTimeout(callback, milliseconds)
      return () => clearTimeout(timer)
    },
  }
}

function deferred() {
  let resolve = () => {}
  const promise = new Promise<void>(done => {
    resolve = done
  })
  return { promise, resolve }
}

function register(
  service: ModelTransportService,
  value: ModelDefinition = definition,
  owner: object = {},
  cleanup: () => void | Promise<void> = () => {},
) {
  const result = service.registerAdaptation(
    value,
    syntheticInputMeter(value, 'openai'),
    owner,
    cleanup,
  )
  if ('rejected' in result) throw new Error('controlled contribution rejected')
  return result.registered
}

function collectorFixture(collectorId: string) {
  const records: DiagnosticRecord[] = []
  const store: DiagnosticJournalStore = {
    async append(record) {
      records.push(record)
      return 'written'
    },
    async flush() {},
    async query() {
      return { rejected: 'unavailable' }
    },
    async exportPage() {
      return { rejected: 'unavailable' }
    },
    async close() {
      return { complete: true, coverage: 'complete' }
    },
    health() {
      return {
        pendingQueries: 0,
        pendingQueryIo: 0,
        openQueryHandles: 0,
        pendingQueryCloses: 0,
        timedOutQueries: 0,
        queryCloseFailures: 0,
        expired: 0,
        expiredBytes: 0,
        evicted: 0,
        evictedBytes: 0,
        retainedBytes: 0,
        retainedRecords: 0,
        retainedSegments: 0,
        coverage: 'complete',
      }
    },
  }
  const config: DiagnosticCollectorConfig = {
    collectorId,
    scope: { kind: 'local' },
    maxRecordBytes: 4096,
    maxFieldBytes: 512,
    queueMaxRecords: 64,
    queueMaxBytes: 65536,
    segmentMaxBytes: 65536,
    retainedMaxBytes: 131072,
    retainedMaxSegments: 3,
    retentionMs: 60000,
    queryMaxRecords: 8,
    queryMaxBytes: 8192,
    queryScanMaxBytes: 8192,
    queryConcurrency: 1,
    queryMaxDurationMs: 500,
    exportMaxRecords: 8,
    exportMaxBytes: 8192,
    closeWaitMs: 500,
    stderrMaxReports: 1,
    monotonicClock: () => 1,
    wallClock: () => new Date('2026-09-29T00:00:00Z'),
    schedule(milliseconds, callback) {
      const timer = setTimeout(callback, milliseconds)
      return { cancel: () => clearTimeout(timer) }
    },
    store,
  }
  return { collector: createDiagnosticCollector(config), records }
}

describe('actual registry engineering diagnostics', () => {
  it('reports only real publication, acquisition and final retirement, preserving exact owned revisions', async () => {
    const events: DiagnosticEvent[] = []
    const service = createModelTransportService({
      imagePreparation,
      policy: networkPolicy,
      registryDiagnostics: {
        record(event) {
          events.push(event)
          return { recorded: { collectorId: 'local', sequence: String(events.length) } }
        },
      },
    })
    const owner = {}
    const cleanup = () => {}
    const meter = syntheticInputMeter(definition, 'openai')
    const registration = register(service, definition, owner, cleanup)
    expect(service.registerAdaptation(definition, meter, owner, cleanup)).toEqual({
      registered: registration,
    })
    expect(
      events.filter(
        event => event.facts.kind === 'registration' && event.facts.phase === 'published',
      ),
    ).toHaveLength(1)
    expect(service.registerAdaptation(definition, meter, {}, cleanup)).toEqual({
      rejected: 'invalidInput',
    })
    const requested = input()
    const acquired = service.acquire(requested.snapshot.adaptation, requested.routeName)
    if ('rejected' in acquired) throw new Error('controlled acquire rejected')
    expect(events).toContainEqual(
      expect.objectContaining({
        stage: 'registration',
        outcome: 'accepted',
        binding: expect.objectContaining({
          implementationRevision: definition.implementation.revision,
          definitionRevision: definition.revision,
          configurationRevision: requested.snapshot.adaptation.configuration.revision,
        }),
        facts: expect.objectContaining({ phase: 'admitted', references: 1, executions: 0 }),
      }),
    )
    const retiring = service.retire(registration, policy())
    expect(service.acquire(requested.snapshot.adaptation, requested.routeName)).toEqual({
      rejected: 'unavailable',
    })
    expect(await retiring).toMatchObject({ remaining_active: true, references: 1 })
    expect(events.some(event => event.stage === 'retirement' && event.outcome === 'stopped')).toBe(
      false,
    )
    acquired.lease.release()
    expect(await service.retire(registration, policy())).toEqual({ retired: true })
    expect(
      events.filter(event => event.stage === 'retirement' && event.outcome === 'stopped'),
    ).toHaveLength(1)
    expect(await service.close(policy())).toEqual({ retired: true })
    expect(events.some(event => JSON.stringify(event).includes('configuration.values'))).toBe(false)
  })

  it('keeps forced cancellation, remaining active, late stop and cleanup failure separate', async () => {
    const events: DiagnosticEvent[] = []
    const service = createModelTransportService({
      imagePreparation,
      policy: networkPolicy,
      registryDiagnostics: {
        record(event) {
          events.push(event)
          return { recorded: { collectorId: 'local', sequence: String(events.length) } }
        },
      },
    })
    const work = deferred()
    const registration = register(service)
    const request = input()
    const acquired = service.acquire(request.snapshot.adaptation, request.routeName)
    if ('rejected' in acquired) throw new Error('controlled acquire rejected')
    acquired.lease.track(work.promise)
    acquired.lease.release()
    expect(await service.retire(registration, policy(true))).toEqual({
      remaining_active: true,
      references: 1,
      executions: 1,
    })
    expect(acquired.lease.signal.aborted).toBe(true)
    expect(events).toContainEqual(
      expect.objectContaining({
        stage: 'retirement',
        outcome: 'cancel_requested',
        facts: expect.objectContaining({ cancellation: 'requested' }),
      }),
    )
    expect(events).toContainEqual(
      expect.objectContaining({
        stage: 'retirement',
        outcome: 'waiting',
        facts: expect.objectContaining({
          cancellation: 'remaining_active',
          references: 1,
          executions: 1,
        }),
      }),
    )
    expect(events.some(event => event.stage === 'retirement' && event.outcome === 'stopped')).toBe(
      false,
    )
    work.resolve()
    expect(await service.retire(registration, policy())).toEqual({ retired: true })
    expect(events.some(event => event.stage === 'retirement' && event.outcome === 'stopped')).toBe(
      true,
    )
    await service.close(policy())

    const failed = createModelTransportService({
      imagePreparation,
      policy: networkPolicy,
      registryDiagnostics: {
        record(event) {
          events.push(event)
          return { recorded: { collectorId: 'local', sequence: String(events.length) } }
        },
      },
    })
    const broken = register(failed, definition, {}, () => {
      throw new Error('private cleanup secret')
    })
    expect(await failed.retire(broken, policy())).toEqual({ cleanup_failed: true })
    expect(events).toContainEqual(
      expect.objectContaining({
        stage: 'retirement',
        outcome: 'failed',
        facts: expect.objectContaining({ cancellation: 'cleanup_failed' }),
      }),
    )
    expect(JSON.stringify(events)).not.toContain('private cleanup secret')
  })

  it('reports the actual timeout result counts even when a reference drains before the caller resumes', async () => {
    const events: DiagnosticEvent[] = []
    const service = createModelTransportService({
      imagePreparation,
      policy: networkPolicy,
      registryDiagnostics: {
        record(event) {
          events.push(event)
          return { recorded: { collectorId: 'local', sequence: String(events.length) } }
        },
      },
    })
    const registration = register(service)
    const requested = input()
    const acquired = service.acquire(requested.snapshot.adaptation, requested.routeName)
    if ('rejected' in acquired) throw new Error('controlled acquire rejected')
    const timeout: RetirementPolicy = {
      force: false,
      waitMilliseconds: 1,
      schedule(_milliseconds, callback) {
        callback()
        return () => {}
      },
    }
    const result = service.retire(registration, timeout)
    acquired.lease.release()
    expect(await result).toEqual({ remaining_active: true, references: 1, executions: 0 })
    expect(events).toContainEqual(
      expect.objectContaining({
        stage: 'retirement',
        outcome: 'waiting',
        facts: expect.objectContaining({ references: 1, executions: 0 }),
      }),
    )
    expect(await service.retire(registration, policy())).toEqual({ retired: true })
    await service.close(policy())
  })

  it('is accepted by the real local collector and distinguishes service generations', async () => {
    const first = collectorFixture('registry-generation-a')
    const second = collectorFixture('registry-generation-b')
    const one = createModelTransportService({
      imagePreparation,
      policy: networkPolicy,
      registryDiagnostics: first.collector.emitter({ kind: 'local' }, { executionId: 'service-a' }),
    })
    const two = createModelTransportService({
      imagePreparation,
      policy: networkPolicy,
      registryDiagnostics: second.collector.emitter(
        { kind: 'local' },
        { executionId: 'service-b' },
      ),
    })
    const a = register(one)
    const b = register(two)
    expect(await one.retire(a, policy())).toEqual({ retired: true })
    expect(await two.retire(b, policy())).toEqual({ retired: true })
    await one.close(policy())
    await two.close(policy())
    expect(await first.collector.close()).toMatchObject({ complete: true })
    expect(await second.collector.close()).toMatchObject({ complete: true })
    expect(first.records.length).toBeGreaterThan(0)
    expect(second.records.length).toBeGreaterThan(0)
    expect(
      first.records.every(
        record =>
          record.collectorId === 'registry-generation-a' &&
          record.association?.executionId === 'service-a',
      ),
    ).toBe(true)
    expect(
      second.records.every(
        record =>
          record.collectorId === 'registry-generation-b' &&
          record.association?.executionId === 'service-b',
      ),
    ).toBe(true)
    expect(first.collector.health().invalidRecords).toBe(0)
    expect(second.collector.health().invalidRecords).toBe(0)
    expect(one.inspect()).toMatchObject({
      registryDiagnosticFailures: 0,
      registryDiagnosticDropped: 0,
    })
    expect(two.inspect()).toMatchObject({
      registryDiagnosticFailures: 0,
      registryDiagnosticDropped: 0,
    })
  })

  it('keeps absent, throwing, rejected and malformed borrowed record results separate from network health', async () => {
    const absent = createModelTransportService({ imagePreparation, policy: networkPolicy })
    const noDiagnostic = register(absent)
    expect(await absent.retire(noDiagnostic, policy())).toEqual({ retired: true })
    expect(await absent.close(policy())).toEqual({ retired: true })
    expect(absent.inspect()).toMatchObject({
      registryDiagnosticFailures: 0,
      registryDiagnosticDropped: 0,
    })

    const throws = createModelTransportService({
      imagePreparation,
      policy: networkPolicy,
      registryDiagnostics: {
        record() {
          throw new Error('private thrown secret')
        },
      },
    })
    const thrown = register(throws)
    expect(await throws.retire(thrown, policy())).toEqual({ retired: true })
    expect(await throws.close(policy())).toEqual({ retired: true })
    expect(throws.inspect().registryDiagnosticFailures).toBeGreaterThan(1)
    expect(throws.inspect().registryDiagnosticDropped).toBe(0)
    expect(throws.diagnostics()).toEqual({ failed: 0, pending: 0, dropped: 0 })

    const dropped = createModelTransportService({
      imagePreparation,
      policy: networkPolicy,
      registryDiagnostics: { record: () => ({ dropped: 'queue_full' }) },
    })
    const declined = register(dropped)
    expect(await dropped.retire(declined, policy())).toEqual({ retired: true })
    expect(await dropped.close(policy())).toEqual({ retired: true })
    expect(dropped.inspect().registryDiagnosticDropped).toBeGreaterThan(0)
    expect(dropped.inspect().registryDiagnosticFailures).toBe(0)
    expect(dropped.diagnostics()).toEqual({ failed: 0, pending: 0, dropped: 0 })

    const malformed = createModelTransportService({
      imagePreparation,
      policy: networkPolicy,
      registryDiagnostics: {
        // @ts-expect-error exercise a runtime callback violating its declared result
        record: () => ({ dropped: 'private unsupported result' }),
      },
    })
    const invalid = register(malformed)
    expect(await malformed.retire(invalid, policy())).toEqual({ retired: true })
    expect(await malformed.close(policy())).toEqual({ retired: true })
    expect(malformed.inspect().registryDiagnosticFailures).toBeGreaterThan(0)
    expect(malformed.inspect().registryDiagnosticDropped).toBe(0)
  })

  it('stops a thenable-violating emitter after one call without awaiting its rejection or holding a lease', async () => {
    let calls = 0
    const service = createModelTransportService({
      imagePreparation,
      policy: networkPolicy,
      registryDiagnostics: {
        // @ts-expect-error exercise a runtime callback returning a Promise from a synchronous port
        record() {
          calls++
          return Promise.reject(new Error('private rejected secret'))
        },
      },
    })
    const registration = register(service)
    const requested = input()
    const acquired = service.acquire(requested.snapshot.adaptation, requested.routeName)
    if ('rejected' in acquired) throw new Error('controlled acquire rejected')
    acquired.lease.release()
    expect(await service.retire(registration, policy())).toEqual({ retired: true })
    expect(await service.close(policy())).toEqual({ retired: true })
    expect(calls).toBe(1)
    expect(service.inspect()).toMatchObject({
      registryDiagnosticFailures: 1,
      registryDiagnosticDropped: 0,
      references: 0,
      executions: 0,
    })
  })

  it('does not retain a lease or start repeated reactions for a permanently pending diagnostic Promise', async () => {
    const never = new Promise<void>(() => {})
    let calls = 0
    const service = createModelTransportService({
      imagePreparation,
      policy: networkPolicy,
      registryDiagnostics: {
        // @ts-expect-error deliberately return a never-settling Promise from a sync port
        record() {
          calls++
          return never
        },
      },
    })
    const registration = register(service)
    const requested = input()
    const acquired = service.acquire(requested.snapshot.adaptation, requested.routeName)
    if ('rejected' in acquired) throw new Error('controlled acquire rejected')
    acquired.lease.release()
    expect(await service.retire(registration, policy())).toEqual({ retired: true })
    expect(await service.close(policy())).toEqual({ retired: true })
    expect(calls).toBe(1)
    expect(service.inspect()).toMatchObject({ registryDiagnosticFailures: 1, references: 0 })
  })

  it('observes actual Cordis contribution replacement without retiring the new revision', async () => {
    const fixture = collectorFixture('cordis-registry')
    const ctx = new Context()
    const next = { ...definition, revision: `${definition.revision}-next` }
    try {
      await ctx.plugin(piAiTransportPlugin, {
        imagePreparation,
        policy: networkPolicy,
        retirement: policy(),
        registryDiagnostics: fixture.collector.emitter(
          { kind: 'local' },
          { executionId: 'cordis-service' },
        ),
      })
      const old = ctx.plugin(
        createModelPlugin(definition, syntheticInputMeter(definition, 'openai'), policy()),
        {},
      )
      await old
      const newer = ctx.plugin(
        createModelPlugin(next, syntheticInputMeter(next, 'openai'), policy()),
        {},
      )
      await newer
      const service: unknown = ctx.get(MODEL_TRANSPORT_SERVICE)
      if (
        !service ||
        typeof service !== 'object' ||
        !('inspect' in service) ||
        typeof service.inspect !== 'function'
      )
        throw new Error('service missing')
      expect(service.inspect()).toMatchObject({ registrations: 2 })
      await old.dispose()
      expect(service.inspect()).toMatchObject({ registrations: 1 })
    } finally {
      await ctx.fiber.dispose()
      await fixture.collector.close()
    }
    const published = fixture.records.filter(
      record =>
        record.stage === 'registration' &&
        record.facts.kind === 'registration' &&
        record.facts.phase === 'published',
    )
    const stopped = fixture.records.filter(
      record => record.stage === 'retirement' && record.outcome === 'stopped' && record.binding,
    )
    expect(published.map(record => record.binding?.definitionRevision)).toEqual([
      definition.revision,
      next.revision,
    ])
    expect(stopped.map(record => record.binding?.definitionRevision)).toContain(definition.revision)
  })
})

