import { describe, it, expect, vi } from 'vitest'
import {
  writeJsonLossless,
  LosslessNumber,
  judgeContentBlock,
  toOpaqueJson,
  type JsonObject,
} from '@omne-harness-lite/content-blocks'
import type { PlanOutputHistoryGroup } from '@omne-harness-lite/model-request-runtime'
import {
  defineInputMeter,
  type FullMeterInput,
  type NewMeterInput,
  type ReplayMeterInput,
} from '../src/input-meter.ts'
import { projectInput, projectOutput, canonicalProjection } from '../src/projection.ts'
import {
  fullOutputHistory,
  newOutputHistory,
  replayOutputHistory,
  type OutputHistoryPolicy,
} from '../src/input-meters/output-history.ts'
import { withOutputPrefix } from '../src/input-meters/output-prefix.ts'
import { projectAssistant } from '../src/assistant-projection.ts'
import { object } from '../src/json.ts'
import { input, judgedMessage, at } from './support.ts'
import { ExactDecimal } from '@omne-harness-lite/call-accounts'

function fixture() {
  const request = input()
  const meter = defineInputMeter({
    modelId: request.routeName,
    definitionRevision: request.snapshot.adaptation.definition.revision,
    implementation: request.snapshot.adaptation.implementation,
    provider: request.provider,
    algorithmRevision: 'shared-fixture/1',
    tokenizerRevision: 'shared-fixture-tokenizer/1',
    replayRevision: 'shared-fixture-replay/1',
    evidence: 'named local finite fixture, not vendor certification',
    measureFull: () => ({ kind: 'unavailable' }),
  })
  const envelope: JsonObject = {
    model: request.routeName,
    provider: { order: [request.provider], allow_fallbacks: false, require_parameters: true },
    max_tokens: 128,
  }
  const prefix = { role: 'user', content: 'stable-prefix-never-tokenize' }
  const origin = projectInput({ ...envelope, messages: [prefix] }, request, meter)
  const reply = judgedMessage({
    type: 'assistant',
    id: 'a',
    response: 'r',
    ending: 'complete',
    createdAt: at,
    blocks: [
      {
        kind: 'thinking',
        id: 'reason',
        text: '',
        opaque: toOpaqueJson({
          routeName: request.routeName,
          reasoning_details: [
            { type: 'reasoning.encrypted', data: 'never-tokenize-opaque', format: 'fixture-v1' },
          ],
        }),
        visibility: { toHuman: false, toModel: true },
      },
      { kind: 'text', id: 'text', text: 'answer', visibility: { toHuman: true, toModel: true } },
    ],
  })
  const projected = projectAssistant(reply.blocks, request.routeName, false)
  if ('rejected' in projected) throw Error('assistant')
  const output = projectOutput({ blocks: reply.blocks, source: 'reply', completeness: 'complete' })
  if (!('projected' in output)) throw Error('output')
  const group: PlanOutputHistoryGroup = {
    inputCalibration: {
      requestInput: origin.requestInput,
      observedInput: {
        kind: 'from_usage',
        provenance: { adapterRevision: 'fixture-reader/1', fieldPaths: ['usage.prompt_tokens'] },
      },
      outputGroup: output.projected,
    },
    usage: {
      input_tokens: 100,
      output_tokens: 18,
      cache_read_tokens: 0,
      cache_write_tokens: 0,
      reasoning_tokens: 7,
      source: 'upstream',
    },
    outputBlocks: reply.blocks,
    replaySelection: reply.blocks.map((_, i) => ({
      sourceBlockIndex: i,
      messageIndex: 1,
      blockIndex: i,
    })),
    origin: {
      adaptation: request.snapshot.adaptation,
      provider: request.provider,
      parameters: { maxOutputTokens: 128 },
    },
  }
  const body = {
    ...envelope,
    messages: [prefix, projected.message, { role: 'user', content: 'new' }],
  }
  const projection = projectInput(body, request, meter)
  const historySpans = group.replaySelection.map((_, selectionIndex) => ({
    groupIndex: 0,
    selectionIndex,
    start: 1,
    end: 2,
  }))
  const full: FullMeterInput = {
    body,
    serialized: writeJsonLossless(body),
    projection,
    outputHistory: [group],
    historySpans,
  }
  const fresh: NewMeterInput = Object.freeze({
    units: projection.units.slice(1),
    envelope: projection.envelope,
    precedingUnitCount: 1,
    unitIndices: [1, 2],
    countingBasis: projection.requestInput.countingBasis,
    outputHistory: [group],
    historySpans,
  })
  const replay: ReplayMeterInput = Object.freeze({
    units: [projected.message],
    envelope: projection.envelope,
    precedingUnitCount: 1,
    unitIndices: [1],
    countingBasis: projection.requestInput.countingBasis,
    observation: {
      kind: 'observation' as const,
      inputCalibration: group.inputCalibration,
      usage: group.usage,
      outputBlocks: group.outputBlocks,
      replaySelection: group.replaySelection,
    },
    outputHistory: [group],
    selectionSpans: historySpans.map(({ groupIndex: _g, ...span }) => span),
  })
  const policy: OutputHistoryPolicy = {
    classifyUnit: unit =>
      object(unit) && Object.hasOwn(unit, 'reasoning_details') ? 'wholeGroup' : 'visible',
    sourceApplies: source =>
      source.origin === undefined || source.origin.provider === request.provider,
    originalBasisApplies: () => () => true,
    requiresSignedPrefix: () => false,
    projectionRevisionApplies: revision => revision === origin.requestInput.projectionRevision,
  }
  const counter = vi.fn(({ body }: { body: JsonObject }) => ({
    kind: 'estimated' as const,
    tokens: 5 + (Array.isArray(body.messages) ? body.messages.length * 10 : 0),
  }))
  return { meter, policy, counter, full, fresh, replay, group, projection, envelope, request }
}
function amount(result: ReturnType<typeof newOutputHistory>): string {
  return 'tokens' in result ? ExactDecimal.from(result.tokens).toString() : result.kind
}
describe('shared complete output group composition', () => {
  it('full/new/phi share O once and exclude ciphertext from every raw counter', () => {
    const f = fixture()
    expect(amount(fullOutputHistory(f.full, f.meter, f.counter, f.policy))).toBe('43')
    expect(amount(newOutputHistory(f.fresh, f.meter, f.counter, f.policy))).toBe('28')
    expect(amount(replayOutputHistory(f.replay, f.meter, f.counter, f.policy))).toBe('18')
    for (const [arg] of f.counter.mock.calls)
      expect(writeJsonLossless(arg.body)).not.toContain('never-tokenize-opaque')
  })
  it('preserves actual JSON member order while removing only validated cache metadata', () => {
    const f = fixture()
    const body: JsonObject = {
      model: f.request.routeName,
      messages: [{ role: 'user', content: 'plain' }],
      provider: { order: [f.request.provider], allow_fallbacks: false, require_parameters: true },
      max_tokens: 128,
    }
    const projection = projectInput(body, f.request, f.meter)
    const counter = vi.fn(({ serialized }: { body: JsonObject; serialized: string }) => {
      expect(serialized).toBe(writeJsonLossless(body))
      return { kind: 'estimated' as const, tokens: 12 }
    })
    expect(
      fullOutputHistory(
        {
          body,
          serialized: writeJsonLossless(body),
          projection,
          outputHistory: [],
          historySpans: [],
        },
        f.meter,
        counter,
        f.policy,
      ),
    ).toEqual({ kind: 'estimated', tokens: 12 })
    expect(counter).toHaveBeenCalledOnce()
  })
  it('known zero O remains estimated in full/new/phi while missing O is never zero', () => {
    const f = fixture()
    const group = { ...f.group, usage: { ...f.group.usage, output_tokens: 0, reasoning_tokens: 0 } }
    expect(
      amount(
        fullOutputHistory({ ...f.full, outputHistory: [group] }, f.meter, f.counter, f.policy),
      ),
    ).toBe('25')
    const fresh = {
      ...f.fresh,
      units: f.fresh.units.slice(0, 1),
      unitIndices: [1],
      outputHistory: [group],
    }
    const delta = newOutputHistory(fresh, f.meter, f.counter, f.policy)
    expect(delta.kind).toBe('estimated')
    expect(amount(delta)).toBe('0')
    const replay = {
      ...f.replay,
      observation: { ...f.replay.observation, usage: group.usage },
      outputHistory: [group],
    }
    expect(replayOutputHistory(replay, f.meter, f.counter, f.policy)).toEqual({
      kind: 'estimated',
      tokens: 0,
    })
    const missing = { ...group, usage: { ...group.usage, output_tokens: 'unknown' as const } }
    expect(
      newOutputHistory({ ...fresh, outputHistory: [missing] }, f.meter, f.counter, f.policy),
    ).toEqual({ kind: 'unavailable' })
  })
  it('multiple complete groups use exact decimal addition without binary rounding or extra reasoning', () => {
    const f = fixture()
    const blocks = f.group.outputBlocks.map(block => {
      const judged = judgeContentBlock({ ...block, id: `${block.id}-second` })
      if ('rejected' in judged) throw Error('block fixture')
      return judged.ok
    })
    const output = projectOutput({ blocks, source: 'reply', completeness: 'complete' })
    if (!('projected' in output)) throw Error('second output')
    const first = {
      ...f.group,
      usage: { ...f.group.usage, output_tokens: new LosslessNumber('9007199254740993') },
    }
    const second: PlanOutputHistoryGroup = {
      ...f.group,
      outputBlocks: blocks,
      inputCalibration: { ...f.group.inputCalibration, outputGroup: output.projected },
      replaySelection: f.group.replaySelection.map(s => ({ ...s, messageIndex: 3 })),
    }
    const body = {
      ...f.full.body,
      messages: [...f.projection.units, f.projection.units[1]!, { role: 'user', content: 'last' }],
    }
    const projection = projectInput(body, f.request, f.meter)
    const historySpans = [
      ...f.full.historySpans,
      ...f.full.historySpans.map(s => ({ ...s, groupIndex: 1, start: 3, end: 4 })),
    ]
    const full = {
      body,
      serialized: writeJsonLossless(body),
      projection,
      outputHistory: [first, second],
      historySpans,
    }
    expect(amount(fullOutputHistory(full, f.meter, f.counter, f.policy))).toBe('9007199254741046')
    const fresh = {
      ...f.fresh,
      units: projection.units.slice(1),
      unitIndices: [1, 2, 3, 4],
      outputHistory: [first, second],
      historySpans,
    }
    expect(amount(newOutputHistory(fresh, f.meter, f.counter, f.policy))).toBe('9007199254741031')
  })
  it('phi requires known original input usage even when its basis is identical', () => {
    const f = fixture()
    const input: ReplayMeterInput = {
      ...f.replay,
      observation: {
        ...f.replay.observation,
        inputCalibration: {
          ...f.replay.observation.inputCalibration,
          observedInput: { kind: 'unavailable', reason: 'scope_unknown' },
        },
      },
      outputHistory: [
        {
          ...f.group,
          inputCalibration: {
            ...f.group.inputCalibration,
            observedInput: { kind: 'unavailable', reason: 'scope_unknown' },
          },
        },
      ],
    }
    expect(replayOutputHistory(input, f.meter, f.counter, f.policy)).toEqual({
      kind: 'unavailable',
    })
    expect(f.counter).not.toHaveBeenCalled()
    expect(
      amount(
        newOutputHistory(
          { ...f.fresh, outputHistory: input.outputHistory },
          f.meter,
          f.counter,
          f.policy,
        ),
      ),
    ).toBe('28')
  })
  it('stable P never reaches the marginal counter and valid broad-envelope change loses signed proof', () => {
    const f = fixture(),
      policy = { ...f.policy, requiresSignedPrefix: () => true }
    expect(
      amount(
        withOutputPrefix(f.fresh, f.projection, () =>
          newOutputHistory(f.fresh, f.meter, f.counter, policy),
        ),
      ),
    ).toBe('28')
    for (const [arg] of f.counter.mock.calls)
      expect(writeJsonLossless(arg.body)).not.toContain('stable-prefix-never-tokenize')
    f.counter.mockClear()
    const changed = projectInput({ ...f.full.body, max_tokens: 256 }, f.request, f.meter)
    const fresh = Object.freeze({ ...f.fresh, envelope: changed.envelope })
    expect(
      withOutputPrefix(fresh, changed, () => newOutputHistory(fresh, f.meter, f.counter, policy)),
    ).toEqual({ kind: 'unavailable' })
    expect(f.counter).not.toHaveBeenCalled()
  })
  it('rejects duplicate targets and changed summaries before counting', () => {
    const f = fixture()
    expect(
      fullOutputHistory(
        {
          ...f.full,
          outputHistory: [f.group, f.group],
          historySpans: [
            ...f.full.historySpans,
            ...f.full.historySpans.map(s => ({ ...s, groupIndex: 1 })),
          ],
        },
        f.meter,
        f.counter,
        f.policy,
      ),
    ).toEqual({ kind: 'unavailable' })
    const bad = {
      ...f.group,
      inputCalibration: {
        ...f.group.inputCalibration,
        outputGroup: {
          ...f.group.inputCalibration.outputGroup,
          usageRef: 'usage' as const,
          kind: 'known' as const,
          source: 'reply' as const,
          completeness: 'complete' as const,
          projectionRevision: f.projection.requestInput.projectionRevision,
          blockDigests: ['0'.repeat(64), '0'.repeat(64)],
        },
      },
    }
    expect(
      newOutputHistory({ ...f.fresh, outputHistory: [bad] }, f.meter, f.counter, f.policy),
    ).toEqual({ kind: 'invalidInput' })
    expect(f.counter).not.toHaveBeenCalled()
  })
  it('unknown opaque mappings, partial original group and a counter exception cannot fall through', () => {
    const f = fixture()
    expect(
      newOutputHistory(f.fresh, f.meter, f.counter, {
        ...f.policy,
        classifyUnit: () => 'uninterpretable',
      }),
    ).toEqual({ kind: 'unavailable' })
    const group = { ...f.group, replaySelection: f.group.replaySelection.slice(0, 1) }
    expect(
      newOutputHistory(
        { ...f.fresh, outputHistory: [group], historySpans: f.fresh.historySpans.slice(0, 1) },
        f.meter,
        f.counter,
        f.policy,
      ),
    ).toEqual({ kind: 'unavailable' })
    expect(f.counter).not.toHaveBeenCalled()
    expect(
      newOutputHistory(
        f.fresh,
        f.meter,
        () => {
          throw Error('counter')
        },
        f.policy,
      ),
    ).toEqual({ kind: 'unavailable' })
  })
  it('an original opaque group cannot become ordinary visible counting through partial selection', () => {
    const f = fixture()
    const body = {
      ...f.full.body,
      messages: [
        f.projection.units[0]!,
        { role: 'assistant', content: 'answer' },
        f.projection.units[2]!,
      ],
    }
    const projection = projectInput(body, f.request, f.meter)
    const group = {
      ...f.group,
      replaySelection: [{ sourceBlockIndex: 1, messageIndex: 1, blockIndex: 0 }],
    }
    const full = {
      ...f.full,
      body,
      serialized: writeJsonLossless(body),
      projection,
      outputHistory: [group],
      historySpans: [{ groupIndex: 0, selectionIndex: 0, start: 1, end: 2 }],
    }
    expect(fullOutputHistory(full, f.meter, f.counter, f.policy)).toEqual({ kind: 'unavailable' })
    expect(f.counter).not.toHaveBeenCalled()
    expect(projectAssistant(f.group.outputBlocks, 'different-model', false)).toEqual({
      rejected: 'unavailable',
    })
  })
  it('owns inputs before trusted rules run and verifies independent full projection facts', () => {
    const f = fixture()
    const policy = {
      ...f.policy,
      sourceApplies: () => {
        Object.assign(f.group.usage, { output_tokens: 999 })
        return true
      },
    }
    expect(amount(fullOutputHistory(f.full, f.meter, f.counter, policy))).toBe('43')
    expect(
      fullOutputHistory(
        {
          ...f.full,
          projection: {
            ...f.projection,
            requestInput: { ...f.projection.requestInput, prefixDigest: '0'.repeat(64) },
          },
        },
        f.meter,
        f.counter,
        f.policy,
      ),
    ).toEqual({ kind: 'unavailable' })
    let reads = 0
    const malformed = Object.defineProperty({}, 'body', {
      enumerable: true,
      get() {
        reads++
        return f.full.body
      },
    })
    expect(
      Reflect.apply(fullOutputHistory, undefined, [malformed, f.meter, f.counter, f.policy]),
    ).toEqual({ kind: 'unavailable' })
    expect(reads).toBe(0)
  })
  it('signed prefix capability is exact identity, is cleaned on throw, and isolates reentry', () => {
    const f = fixture(),
      policy = { ...f.policy, requiresSignedPrefix: () => true }
    expect(newOutputHistory(f.fresh, f.meter, f.counter, policy)).toEqual({ kind: 'unavailable' })
    expect(
      amount(
        withOutputPrefix(f.fresh, f.projection, () =>
          newOutputHistory(f.fresh, f.meter, f.counter, policy),
        ),
      ),
    ).toBe('28')
    withOutputPrefix(f.fresh, f.projection, () => {
      expect(newOutputHistory({ ...f.fresh }, f.meter, f.counter, policy)).toEqual({
        kind: 'unavailable',
      })
      expect(() => withOutputPrefix(f.fresh, f.projection, () => null)).toThrow(
        'active meter input',
      )
    })
    expect(() =>
      withOutputPrefix(f.fresh, f.projection, () => {
        throw Error('after install')
      }),
    ).toThrow('after install')
    expect(newOutputHistory(f.fresh, f.meter, f.counter, policy)).toEqual({ kind: 'unavailable' })
    const other = Object.freeze({ ...f.fresh })
    withOutputPrefix(f.fresh, f.projection, () =>
      withOutputPrefix(other, f.projection, () => {
        expect(amount(newOutputHistory(f.fresh, f.meter, f.counter, policy))).toBe('28')
        expect(amount(newOutputHistory(other, f.meter, f.counter, policy))).toBe('28')
      }),
    )
  })
  it('same N under different P or an inserted message never receives signed prefix proof', () => {
    const f = fixture(),
      policy = { ...f.policy, requiresSignedPrefix: () => true }
    const changed = projectInput(
      {
        ...f.full.body,
        messages: [{ role: 'user', content: 'changed' }, ...f.projection.units.slice(1)],
      },
      f.request,
      f.meter,
    )
    expect(canonicalProjection(changed.units.slice(1))).toBe(canonicalProjection(f.fresh.units))
    expect(
      withOutputPrefix(f.fresh, changed, () =>
        newOutputHistory(f.fresh, f.meter, f.counter, policy),
      ),
    ).toEqual({ kind: 'unavailable' })
    const moved = Object.freeze({
      ...f.fresh,
      unitIndices: [2, 3],
      historySpans: f.fresh.historySpans.map(s => ({ ...s, start: 2, end: 3 })),
    })
    const inserted = projectInput(
      {
        ...f.full.body,
        messages: [
          f.projection.units[0]!,
          { role: 'user', content: 'inserted' },
          ...f.projection.units.slice(1),
        ],
      },
      f.request,
      f.meter,
    )
    expect(
      withOutputPrefix(moved, inserted, () => newOutputHistory(moved, f.meter, f.counter, policy)),
    ).toEqual({ kind: 'unavailable' })
    expect(f.counter).not.toHaveBeenCalled()
  })
})

tests/transport-diagnostics.spec.ts.source:
import { afterAll, beforeAll, describe, expect, it } from 'vitest'
import type {
  TransportDiagnosticFact,
  TransportExecutionDiagnostics,
} from '@omne-harness-lite/model-request-runtime'
import type { ArrivalEvent } from '@omne-harness-lite/arrival-events'
import { certificate, content, finish, fixture, input } from './support.ts'

let cert: ReturnType<typeof certificate>
beforeAll(() => {
  cert = certificate()
})
afterAll(() => cert.dispose())

function collector(): {
  readonly facts: TransportDiagnosticFact[]
  readonly sink: TransportExecutionDiagnostics
} {
  const facts: TransportDiagnosticFact[] = []
  return { facts, sink: { record: fact => facts.push(fact) } }
}

async function drain(reader: AsyncGenerator<ArrivalEvent, unknown>) {
  while (true) {
    const next = await reader.next()
    if (next.done) return next.value
  }
}

describe('request-local transport diagnostics', () => {
  it('keeps two concurrent TLS requests on their own emitters and rejects a read rebinding', async () => {
    let arrived = 0
    let release: () => void = () => {}
    const bothArrived = new Promise<void>(resolve => {
      release = resolve
    })
    const instanceEvents: string[] = []
    const host = await fixture(
      cert.tls,
      async (res, request) => {
        arrived++
        if (arrived === 2) release()
        await bothArrived
        res.writeHead(request.headers.authorization === 'Bearer secret-one' ? 201 : 202)
        res.end(content('safe') + finish())
      },
      {},
      event => instanceEvents.push(event.kind),
    )
    const first = collector()
    const second = collector()
    const firstPlan = await host.transport.plan(input(), { signal: new AbortController().signal })
    const secondPlan = await host.transport.plan(input(), { signal: new AbortController().signal })
    if (!('planned' in firstPlan) || !('planned' in secondPlan))
      throw new Error('fixture plan rejected')
    try {
      const [a, b] = await Promise.all([
        host.transport.send(
          firstPlan.planned,
          'secret-one',
          new AbortController().signal,
          first.sink,
        ),
        host.transport.send(
          secondPlan.planned,
          'secret-two',
          new AbortController().signal,
          second.sink,
        ),
      ])
      if (!('response' in a) || !('response' in b)) throw new Error('fixture send failed')
      expect(
        await drain(
          host.transport.read(
            a.response,
            firstPlan.planned,
            new AbortController().signal,
            second.sink,
          ),
        ),
      ).toMatchObject({
        rejected: 'invalidInput',
        readFacts: { observedInput: { kind: 'unavailable' } },
      })
      const [aEnd, bEnd] = await Promise.all([
        drain(
          host.transport.read(
            a.response,
            firstPlan.planned,
            new AbortController().signal,
            first.sink,
          ),
        ),
        drain(
          host.transport.read(
            b.response,
            secondPlan.planned,
            new AbortController().signal,
            second.sink,
          ),
        ),
      ])
      expect(aEnd).toMatchObject({ ended: 'end' })
      expect(bEnd).toMatchObject({ ended: 'end' })
      expect(first.facts).toContainEqual({
        stage: 'stream_end',
        outcome: 'completed',
        facts: { kind: 'transport', stream: 'ended' },
      })
      expect(second.facts).toContainEqual({
        stage: 'stream_end',
        outcome: 'completed',
        facts: { kind: 'transport', stream: 'ended' },
      })
      for (const [run, status] of [
        [first, 201],
        [second, 202],
      ] as const) {
        expect(run.facts).toContainEqual({
          stage: 'send',
          outcome: 'completed',
          facts: { kind: 'transport', httpStatus: status },
        })
        expect(run.facts).toContainEqual({
          stage: 'send',
          outcome: 'accepted',
          facts: { kind: 'transport', touch: 'touched' },
        })
      }
      expect(instanceEvents).toEqual([])
      expect(host.requests).toHaveLength(2)
      for (const request of host.requests) {
        expect(request.body).not.toContain('executionId')
        expect(request.headers).not.toHaveProperty('x-session-id')
        expect(JSON.stringify(request)).not.toContain('stream_end')
      }
      expect(JSON.stringify(first.facts)).not.toContain('secret-')
      expect(JSON.stringify(second.facts)).not.toContain('secret-')
    } finally {
      release()
      await host.close()
    }
  })

  it('keeps an independently observed HTTP 503 while omitting credential and upstream echo', async () => {
    const host = await fixture(cert.tls, res => {
      res.writeHead(503, { 'content-type': 'application/json' })
      res.end(JSON.stringify({ error: { message: '503' } }))
    })
    const tracked = collector()
    const plan = await host.transport.plan(input(), { signal: new AbortController().signal })
    if (!('planned' in plan)) throw new Error('fixture plan rejected')
    try {
      const result = await host.transport.send(
        plan.planned,
        '503',
        new AbortController().signal,
        tracked.sink,
      )
      expect(result).toHaveProperty('failed')
      expect(tracked.facts).toContainEqual({
        stage: 'send',
        outcome: 'completed',
        facts: { kind: 'transport', httpStatus: 503 },
      })
      expect(JSON.stringify(tracked.facts)).not.toContain('message')
      expect(JSON.stringify(tracked.facts)).not.toContain('credential')
      expect(host.requests).toHaveLength(1)
    } finally {
      await host.close()
    }
  })

  it('separates cancellation request from observed stream stop and isolates a throwing sink', async () => {
    const host = await fixture(cert.tls, res => {
      res.writeHead(200)
      res.write(content('partial'))
    })
    const facts: TransportDiagnosticFact[] = []
    const sink: TransportExecutionDiagnostics = {
      record: fact => {
        facts.push(fact)
        if (fact.stage === 'send' && fact.outcome === 'started')
          throw new Error('diagnostic sink failure')
      },
    }
    const plan = await host.transport.plan(input(), { signal: new AbortController().signal })
    if (!('planned' in plan)) throw new Error('fixture plan rejected')
    const cancellation = new AbortController()
    try {
      const sent = await host.transport.send(plan.planned, 'test-secret', cancellation.signal, sink)
      if (!('response' in sent)) throw new Error('fixture send failed')
      const reader = host.transport.read(sent.response, plan.planned, cancellation.signal, sink)
      expect((await reader.next()).done).toBe(false)
      cancellation.abort()
      expect(await drain(reader)).toMatchObject({ aborted: true })
      expect(facts.filter(fact => fact.outcome === 'cancel_requested')).toHaveLength(1)
      expect(facts).toContainEqual({
        stage: 'stream_end',
        outcome: 'stopped',
        facts: { kind: 'transport', stream: 'lost' },
      })
      expect(host.requests).toHaveLength(1)
    } finally {
      cancellation.abort()
      await host.close()
    }
  })
})

tests/unsupported-content-usage.spec.ts.source:
import { afterAll, beforeAll, describe, expect, it } from 'vitest'
import { LosslessNumber, writeJsonLossless } from '@omne-harness-lite/content-blocks'
import { ExactDecimal } from '@omne-harness-lite/call-accounts'
import { invokeModel } from '@omne-harness-lite/model-request-runtime'
import type { ArrivalEvent } from '@omne-harness-lite/arrival-events'
import { certificate, fixture, finish, input, invocation, policy, sse } from './support.ts'

let cert: ReturnType<typeof certificate>
beforeAll(() => {
  cert = certificate()
})
afterAll(() => cert.dispose())

const fields = ['images', 'audio'] as const
const marker = 'PRIVATE-UNSUPPORTED-CONTENT-MUST-NOT-BE-LOGGED'
const values = {
  images: [{ url: marker }],
  audio: { data: marker },
  refusal: marker,
}
const usage = {
  prompt_tokens: 123,
  completion_tokens: 7,
  prompt_tokens_details: { cached_tokens: 20, cache_write_tokens: 3 },
  cost: new LosslessNumber('0.000123456789123456789'),
}

describe('unsupported content field diagnostics through actual TLS and public invocation', () => {
  for (const field of fields) {
    it(`${field}: names only the fixed field, preserves same-frame usage/cost and stops a hanging upstream`, async () => {
      const closed = Promise.withResolvers<void>()
      const events: ArrivalEvent[] = []
      const diagnostics: unknown[] = []
      const host = await fixture(
        cert.tls,
        res => {
          res.once('close', () => closed.resolve())
          res.writeHead(200, { 'content-type': 'text/event-stream' })
          res.write(sse({ choices: [{ delta: { [field]: values[field] } }], usage }))
          // No finish, DONE or EOF: the client must stop without awaiting future facts.
        },
        {},
        diagnostic => {
          diagnostics.push(diagnostic)
        },
      )
      try {
        const signal = new AbortController().signal
        const result = invocation(
          await invokeModel({
            ...input(),
            transport: host.transport,
            credential: 'synthetic-test-credential',
            signal,
            policy: policy(),
            onAccepted: event => {
              events.push(event)
            },
          }).outcome,
        )
        expect(result.outcome).toBe('failed')
        expect(result.failure).toMatchObject({
          cause: 'unrecognized',
          localError: `unsupported content member: ${field}`,
        })
        expect(result.blocks).toEqual([])
        expect(result.usage.input_tokens).not.toBe('unknown')
        if (result.usage.input_tokens === 'unknown') throw Error('missing input usage')
        expect(ExactDecimal.from(result.usage.input_tokens).compare(ExactDecimal.from(100))).toBe(0)
        expect(result.usage).toMatchObject({
          output_tokens: 7,
          cache_read_tokens: 20,
          cache_write_tokens: 3,
          source: 'upstream',
        })
        expect(writeJsonLossless(result.cost)).toContain('"cost_usd":0.000123456789123456789')
        expect(result.inputCalibration.observedInput).toMatchObject({
          kind: 'from_usage',
          provenance: {
            fieldPaths: [
              'usage.prompt_tokens',
              'usage.prompt_tokens_details.cached_tokens',
              'usage.prompt_tokens_details.cache_write_tokens',
            ],
          },
        })
        const accounts = events.filter(event => event.t === 'account')
        expect(accounts).toHaveLength(1)
        expect(accounts[0]).toMatchObject({ usage: result.usage, cost: result.cost })
        expect(events.filter(event => event.t === 'finish')).toHaveLength(1)
        expect(writeJsonLossless(result)).not.toContain(marker)
        expect(JSON.stringify(diagnostics)).not.toContain(marker)
        expect(signal.aborted).toBe(false)
        await closed.promise
        expect(host.requests).toHaveLength(1)
      } finally {
        await host.close()
      }
    })

    it(`${field}: does not turn a subsequent unread usage frame into known accounting`, async () => {
      const events: ArrivalEvent[] = []
      const host = await fixture(cert.tls, res => {
        res.writeHead(200, { 'content-type': 'text/event-stream' })
        res.end(
          sse({ choices: [{ delta: { [field]: values[field] } }] }) +
            sse({ choices: [], usage }) +
            finish(),
        )
      })
      try {
        const result = invocation(
          await invokeModel({
            ...input(),
            transport: host.transport,
            credential: 'synthetic-test-credential',
            signal: new AbortController().signal,
            policy: policy(),
            onAccepted: event => {
              events.push(event)
            },
          }).outcome,
        )
        expect(result.failure?.localError).toBe(`unsupported content member: ${field}`)
        expect(result.usage).toEqual({
          input_tokens: 'unknown',
          output_tokens: 'unknown',
          cache_read_tokens: 'unknown',
          cache_write_tokens: 'unknown',
          source: 'none',
        })
        expect(result.cost).toEqual({ cost_usd: 'unknown', source: 'none' })
        expect(result.inputCalibration.observedInput).toEqual({
          kind: 'unavailable',
          reason: 'missing_usage',
        })
        expect(events.filter(event => event.t === 'account')).toHaveLength(0)
        expect(writeJsonLossless(result)).not.toContain(marker)
        expect(host.requests).toHaveLength(1)
      } finally {
        await host.close()
      }
    })

    for (const [label, empty] of [
      ['null', null],
      ['empty string', ''],
      ['empty array', []],
    ] as const) {
      it(`${field}: ignores ${label} and completes normally`, async () => {
        const host = await fixture(cert.tls, res => {
          res.writeHead(200, { 'content-type': 'text/event-stream' })
          res.end(sse({ choices: [{ delta: { [field]: empty, content: 'accepted' } }] }) + finish())
        })
        try {
          const result = invocation(
            await invokeModel({
              ...input(),
              transport: host.transport,
              credential: 'synthetic-test-credential',
              signal: new AbortController().signal,
              policy: policy(),
            }).outcome,
          )
          expect(result.outcome).toBe('complete')
          expect(result.failure).toBeUndefined()
          expect(result.blocks).toMatchObject([{ kind: 'text', text: 'accepted' }])
          expect(host.requests).toHaveLength(1)
        } finally {
          await host.close()
        }
      })
    }
  }

  it('retains existing source redaction even when a credential equals the fixed field name', async () => {
    const host = await fixture(cert.tls, res =>
      res.end(sse({ choices: [{ delta: { images: values.images } }] })),
    )
    try {
      const result = invocation(
        await invokeModel({
          ...input(),
          transport: host.transport,
          credential: 'images',
          signal: new AbortController().signal,
          policy: policy(),
        }).outcome,
      )
      expect(result.outcome).toBe('failed')
      expect(result.failure?.cause).toBe('unrecognized')
      expect(result.failure?.localError).toContain('unsupported content member:')
      expect(result.failure?.localError).not.toContain('images')
      expect(writeJsonLossless(result)).not.toContain(marker)
      expect(host.requests).toHaveLength(1)
    } finally {
      await host.close()
    }
  })
})

