import { imagePreparation } from './image-transport-support.ts'
import { afterAll, beforeAll, describe, expect, it, vi } from 'vitest'
import { invokeModel, type PlanInput } from '@omne-harness-lite/model-request-runtime'
import {
  anthropicDefinitions,
  createAnthropicInputMeter,
  createOfficialProfileContent,
  createPiAiTransport,
} from '../src/index.ts'
import {
  certificate,
  fixture,
  input,
  message,
  judgedMessage,
  content,
  sse,
  finish,
  policy,
  at,
} from './support.ts'
let cert: ReturnType<typeof certificate>
beforeAll(() => {
  cert = certificate()
})
afterAll(() => cert.dispose())
describe('official Anthropic public invocation response re-anchoring over actual TLS', () => {
  for (const definition of anthropicDefinitions)
    it(definition.modelId, async () => {
      const profile = createOfficialProfileContent(definition, {
        providers: ['anthropic'],
        allowFallback: false,
        configuration: {
          revision: 'cache',
          values: { cache: { mode: 'explicit', ttl: '1h', breakpoints: ['last_message'] } },
        },
      })
      if ('rejected' in profile) throw Error(profile.rejected)
      const meter = createAnthropicInputMeter(definition),
        full = vi.fn(meter.measureFull)
      let calls = 0
      const host = await fixture(
        cert.tls,
        res => {
          calls++
          res.end(
            content(`answer ${calls}`) +
              sse({
                choices: [],
                model: definition.modelId,
                provider: 'Anthropic',
                usage: {
                  prompt_tokens: 100 * calls,
                  completion_tokens: 4,
                  prompt_tokens_details: { cached_tokens: 20, cache_write_tokens: 5 },
                },
              }) +
              finish(),
          )
        },
        {},
        undefined,
        [definition],
      )
      const transport = createPiAiTransport({
        ...host.options,
        definitions: [definition],
        inputMeters: [{ ...meter, measureFull: full }],
      })
      let request: PlanInput = {
        ...input(),
        routeName: definition.modelId,
        provider: 'anthropic',
        parameters: { maxOutputTokens: 64 },
        messages: [message('user', 'first', 'u0')],
        snapshot: {
          ...input().snapshot,
          ...definition.capabilities,
          adaptation: profile.ok.adaptation,
          providers: profile.ok.providers,
          allowFallback: profile.ok.allowFallback,
        },
      }
      try {
        for (let round = 0; round < 3; round++) {
          const planned = await transport.plan(request, { signal: new AbortController().signal })
          if ('rejected' in planned) throw Error(JSON.stringify(planned))
          expect(planned.planned.measurement.mode).toBe(round === 0 ? 'full' : 'marginal')
          const result = await invokeModel({
            ...request,
            transport,
            credential: 'local-synthetic',
            signal: new AbortController().signal,
            policy: policy(),
            onAccepted: () => {},
          }).outcome
          if (!('outcome' in result) || result.outcome !== 'complete')
            throw Error(JSON.stringify(result))
          expect(result.inputCalibration.observedInput.kind).toBe('from_usage')
          expect(result.inputCalibration.requestInput).toEqual(planned.planned.requestInput)
          const reply = judgedMessage({
            type: 'assistant',
            id: `a${round}`,
            response: `r${round}`,
            ending: 'complete',
            createdAt: at,
            blocks: result.blocks,
          })
          request = {
            ...request,
            calibration: {
              kind: 'observation',
              inputCalibration: result.inputCalibration,
              usage: result.usage,
              outputBlocks: result.blocks,
              replaySelection: result.blocks.map((_block, sourceBlockIndex) => ({
                sourceBlockIndex,
                messageIndex: request.messages.length,
                blockIndex: sourceBlockIndex,
              })),
            },
            messages: [
              ...request.messages,
              reply,
              message('user', `next ${round}`, `u${round + 1}`),
            ],
          }
        }
        // One explicit plan and invokeModel's own plan on the first request only.
        expect(full).toHaveBeenCalledTimes(2)
        expect(host.requests).toHaveLength(3)
        for (const recorded of host.requests)
          expect(recorded.body).toContain('"cache_control":{"type":"ephemeral","ttl":"1h"}')
      } finally {
        await host.close()
      }
    })
})

tests/usage-reader-tls.spec.ts.source:
import { beforeAll, afterAll, describe, it, expect } from 'vitest'
import type { ArrivalEvent } from '@omne-harness-lite/arrival-events'
import type { StreamEnd } from '@omne-harness-lite/model-request-runtime'
import { certificate, fixture, planned, content, sse, finish } from './support.ts'
let cert: ReturnType<typeof certificate>
beforeAll(() => {
  cert = certificate()
})
afterAll(() => cert.dispose())
async function drain(reader: AsyncGenerator<ArrivalEvent, StreamEnd>) {
  while (true) {
    const next = await reader.next()
    if (next.done) return next.value
  }
}
const usage = {
  prompt_tokens: 123,
  completion_tokens: 4,
  prompt_tokens_details: { cached_tokens: 100 },
}
describe('real TLS reader terminal handoff', () => {
  for (const hasUsage of [false, true])
    it(`cancel hanging upstream after content; parsed usage ${hasUsage}`, async () => {
      const host = await fixture(cert.tls, res => {
        res.writeHead(200, { 'content-type': 'text/event-stream' })
        res.write(
          (hasUsage ? sse({ choices: [], usage }) : '') + content('one'),
        ) /* deliberately never end */
      })
      try {
        const request = await planned(host.transport),
          controller = new AbortController()
        const sent = await host.transport.send(request, 'test-only-credential', controller.signal)
        if (!('response' in sent)) throw Error('not sent')
        const reader = host.transport.read(sent.response, request, controller.signal)
        expect((await reader.next()).done).toBe(false)
        controller.abort()
        const ended = await drain(reader)
        expect(ended).toMatchObject({ aborted: true })
        expect(ended.readFacts.observedInput).toMatchObject(
          hasUsage
            ? { kind: 'upstream_total', tokens: 123 }
            : { kind: 'unavailable', reason: 'missing_usage' },
        )
        await sent.response.stopped
        expect(host.requests).toHaveLength(1)
      } finally {
        await host.close()
      }
    }, 3000)
  for (const ending of ['invalid-json', 'in-band', 'normal', 'cache-hit'])
    it(`usage preserved on ${ending}`, async () => {
      const host = await fixture(cert.tls, res => {
        res.writeHead(200, {
          'content-type': 'text/event-stream',
          ...(ending === 'cache-hit' ? { 'X-OpenRouter-Cache-Status': 'HIT' } : {}),
        })
        if (ending === 'in-band')
          res.end(sse({ usage, error: { code: 429, message: 'throttled' } }))
        else
          res.end(
            sse({ usage, choices: [] }) +
              (ending === 'invalid-json' ? 'data: {invalid}\n\n' : content('ok') + finish()),
          )
      })
      try {
        const request = await planned(host.transport),
          signal = new AbortController().signal
        const sent = await host.transport.send(request, 'test-only-credential', signal)
        if (!('response' in sent)) throw Error('not sent')
        const ended = await drain(host.transport.read(sent.response, request, signal))
        expect(ended.readFacts.usage.output_tokens).toBe(4)
        expect(ended.readFacts.observedInput).toMatchObject(
          ending === 'cache-hit'
            ? { kind: 'unavailable', reason: 'response_cache' }
            : { kind: 'upstream_total', tokens: 123 },
        )
        await sent.response.stopped
      } finally {
        await host.close()
      }
    })
})

