import { testImagePreparerFor } from './image-transport-support.ts'
import { directFull } from './direct-full-input.ts'
import { createHash } from 'node:crypto'
import { describe, expect, it } from 'vitest'
import { writeJsonLossless, type JsonObject } from '@omne-harness-lite/content-blocks'
import { parseOpaqueIdentifier, unwrap } from '@omne-harness-lite/identity-values'
import { judgeMessage } from '@omne-harness-lite/messages'
import type { PlanInput } from '@omne-harness-lite/model-request-runtime'
import { createOfficialProfileContent } from '../src/configuration.ts'
import { createGlm53InputMeter, renderGlm53Prompt } from '../src/input-meters/zai-glm53.ts'
import { zaiDefinitions } from '../src/official-models/zai.ts'
import { planRequest } from '../src/plan.ts'

const definitions = zaiDefinitions.filter(item =>
  ['z-ai/glm-5.3', 'z-ai/glm-5.3-flash'].includes(item.modelId),
)
const at = '2026-09-28T00:00:00Z'

function definition(modelId: string) {
  const found = definitions.find(item => item.modelId === modelId)
  if (!found) throw new Error(`missing GLM-5.3 definition: ${modelId}`)
  return found
}

async function actualPlan(modelId: string, effort?: 'low' | 'high' | 'max') {
  const selected = definition(modelId)
  const configuration = { revision: '1', values: { cache: { mode: 'automatic' } } }
  const profile = createOfficialProfileContent(selected, {
    providers: ['z-ai/fp8'],
    allowFallback: false,
    configuration,
  })
  if ('rejected' in profile) throw new Error(profile.rejected)
  const raw = {
    type: 'system_reminder',
    id: 'reminder',
    createdAt: at,
    nature: 'event',
    source: { kind: 'attempt_started', attempt: 1, reason: 'first', at },
    blocks: [
      {
        id: 'reminder-text',
        kind: 'text',
        text: 'Continue',
        visibility: { toHuman: true, toModel: true },
      },
    ],
  }
  const reminder = judgeMessage(raw)
  if ('rejected' in reminder) throw new Error(reminder.rejected)
  const user = judgeMessage({
    type: 'user',
    id: 'user',
    createdAt: at,
    blocks: [
      {
        id: 'user-text',
        kind: 'text',
        text: 'Hello 世界',
        visibility: { toHuman: true, toModel: true },
      },
    ],
  })
  if ('rejected' in user) throw new Error(user.rejected)
  const input: PlanInput = {
    calibration: { kind: 'none' as const, reason: 'no_observation' as const },
    outputHistory: [],
    tokenMargin: { multiplier: 1.2, reserveTokens: 32 },
    target: {
      kind: 'model_call',
      callId: unwrap(parseOpaqueIdentifier('glm53-meter-test', 'ModelCallId')),
      dispatch: 1,
    },
    routeName: selected.modelId,
    provider: 'z-ai/fp8',
    snapshot: {
      adaptation: profile.ok.adaptation,
      providers: profile.ok.providers,
      allowFallback: profile.ok.allowFallback,
      inputModalities: profile.ok.inputModalities,
      outputModalities: profile.ok.outputModalities,
      maxInputTokens: profile.ok.maxInputTokens,
      maxOutputTokens: profile.ok.maxOutputTokens,
      inputConstraints: profile.ok.inputConstraints,
      upstreamInputLimits: profile.ok.upstreamInputLimits,
      updatedAt: at,
    },
    parameters: { maxOutputTokens: 64, ...(effort ? { reasoningEffort: effort } : {}) },
    messages: [reminder.ok, user.ok],
    tools: [],
  }
  return await planRequest(
    input,
    [selected],
    createGlm53InputMeter(selected),
    {
      signal: new AbortController().signal,
    },
    testImagePreparerFor(planRequest),
  )
}

function measured(modelId: string, body: JsonObject) {
  return directFull(createGlm53InputMeter(definition(modelId)), {
    body,
    serialized: writeJsonLossless(body),
  })
}

describe('Z.AI GLM-5.3 and Flash pinned public-template estimates', () => {
  it('matches independent pinned Jinja goldens, including reverse tool results and low effort', () => {
    const messages = [
      { role: 'system', content: [{ type: 'text', text: 'Be helpful' }] },
      { role: 'user', content: [{ type: 'text', text: 'Use tools' }] },
      {
        role: 'assistant',
        content: '',
        tool_calls: [
          { id: 'a', type: 'function', function: { name: 'lookup', arguments: '{"q":"a"}' } },
          { id: 'b', type: 'function', function: { name: 'lookup', arguments: '{"q":"b"}' } },
        ],
      },
      { role: 'tool', tool_call_id: 'b', content: 'B' },
      { role: 'tool', tool_call_id: 'a', content: 'A' },
      { role: 'user', content: [{ type: 'text', text: 'Done' }] },
    ]
    const tools = [
      {
        type: 'function',
        function: {
          name: 'lookup',
          description: 'Find',
          parameters: { type: 'object', properties: { q: { type: 'string' } } },
        },
      },
    ]
    const standard = { model: 'z-ai/glm-5.3', messages, tools }
    const prompt = renderGlm53Prompt(standard, false, 'refuse')
    expect(
      createHash('sha256')
        .update(prompt ?? '')
        .digest('hex'),
    ).toBe('5345eddccee6e2f361762a929cbecc979330f55795f74488b86cecf93ac1dcdc')
    expect(prompt).toContain(
      '<|observation|><tool_response>A</tool_response><tool_response>B</tool_response>',
    )
    expect(
      createHash('sha256')
        .update(
          renderGlm53Prompt({ ...standard, reasoning: { effort: 'low' } }, false, 'refuse') ?? '',
        )
        .digest('hex'),
    ).toBe('de28a1454d5dcfe5aac18a373df6be002463373da8195739029b80c9b68edb88')
    expect(measured(standard.model, standard).kind).toBe('estimated')
    const flash = { ...standard, model: 'z-ai/glm-5.3-flash' }
    expect(
      createHash('sha256')
        .update(renderGlm53Prompt(flash, true, 'refuse') ?? '')
        .digest('hex'),
    ).toBe('5345eddccee6e2f361762a929cbecc979330f55795f74488b86cecf93ac1dcdc')
    expect(measured(flash.model, flash).kind).toBe('estimated')
  })

  it.each(['z-ai/glm-5.3', 'z-ai/glm-5.3-flash'])(
    '%s plans final text/reminder wire with real meter',
    async modelId => {
      const plan = await actualPlan(modelId, modelId.endsWith('flash') ? undefined : 'high')
      if ('rejected' in plan) throw new Error(JSON.stringify(plan))
      expect(plan.planned.body.messages).toMatchObject([
        { role: 'user', content: [{ text: '[system_reminder "reminder"]' }, { text: 'Continue' }] },
        { role: 'user' },
      ])
      expect(plan.planned.inputLimitEvidence).toMatchObject({ inputTokens: { kind: 'estimated' } })
      expect(plan.planned.serialized).toBe(writeJsonLossless(plan.planned.body))
    },
  )

  it('returns unavailable for unsupported multimodal, opaque reasoning and extra fields', () => {
    for (const modelId of ['z-ai/glm-5.3', 'z-ai/glm-5.3-flash']) {
      const body = { model: modelId, messages: [{ role: 'user', content: 'Hello' }] }
      expect(
        measured(modelId, {
          ...body,
          messages: [
            {
              role: 'user',
              content: [{ type: 'image_url', image_url: { url: 'data:image/png;base64,AAAA' } }],
            },
          ],
        }),
      ).toEqual({ kind: 'unavailable' })
      // Released at mp4-18 after ZV0: a plain reasoning string is visible history; opaque
      // details and `reasoning_content` stay unavailable.
      expect(
        measured(modelId, {
          ...body,
          messages: [{ role: 'assistant', content: 'Hello', reasoning: 'secret' }],
        }),
      ).toMatchObject({ kind: 'estimated' })
      for (const extra of [
        {
          reasoning_details: [
            { type: 'reasoning.encrypted', data: 'OPAQUE', format: 'unknown', index: 0 },
          ],
        },
        { reasoning_content: 'secret' },
      ])
        expect(
          measured(modelId, {
            ...body,
            messages: [{ role: 'assistant', content: 'Hello', ...extra }],
          }),
        ).toEqual({ kind: 'unavailable' })
      expect(measured(modelId, { ...body, unknown_prompt_field: 'test' })).toEqual({
        kind: 'unavailable',
      })
    }
    expect(() =>
      createGlm53InputMeter({ ...definition('z-ai/glm-5.3'), modelId: 'z-ai/glm-5.3-prime' }),
    ).toThrow(TypeError)
    expect(() =>
      createGlm53InputMeter({
        ...definition('z-ai/glm-5.3-flash'),
        modelId: 'z-ai/glm-5.3-flashx',
      }),
    ).toThrow(TypeError)
    // Only the current exported release (3 / mp4-18) binds; the retired refusing release,
    // any mixed or unpublished coordinate throws at construction.
    for (const modelId of ['z-ai/glm-5.3', 'z-ai/glm-5.3-flash'])
      for (const coordinates of [
        { revision: '2', implementation: { name: 'pi-ai:zai', revision: 'mp4-17' } },
        { revision: '3', implementation: { name: 'pi-ai:zai', revision: 'mp4-17' } },
        { revision: '2', implementation: { name: 'pi-ai:zai', revision: 'mp4-18' } },
        { revision: '4', implementation: { name: 'pi-ai:zai', revision: 'mp4-18' } },
        { revision: '1', implementation: { name: 'pi-ai:zai', revision: 'mp4-1' } },
      ])
        expect(() => createGlm53InputMeter({ ...definition(modelId), ...coordinates })).toThrow(
          TypeError,
        )
  })
})

tests/zai-history-replay.spec.ts.source:
import { testImagePreparerFor } from './image-transport-support.ts'
import { createHash } from 'node:crypto'
import { afterAll, beforeAll, describe, expect, it } from 'vitest'
import { readOpaqueJson, toOpaqueJson, type JsonObject } from '@omne-harness-lite/content-blocks'
import { start, accept, closeOut } from '@omne-harness-lite/stream-assembly'
import { invokeModel } from '@omne-harness-lite/model-request-runtime'
import { createZaiCommercialInputMeter } from '../src/input-meters/zai-commercial.ts'
import { planRequest } from '../src/plan.ts'
import { object } from '../src/json.ts'
import { definition, histories, historyInput, jsonBody } from './fixtures/zai/history-cases.ts'
import { at, certificate, fixture, judgedMessage, message, policy } from './support.ts'

let cert: ReturnType<typeof certificate>
beforeAll(() => {
  cert = certificate()
})
afterAll(() => cert.dispose())

describe('authentic complete ZAI reasoning through production stream and assembly', () => {
  it.each(histories)(
    '$id retains same-head fragments, full opaque and cross-route plaintext',
    async row => {
      expect(createHash('sha256').update(row.sse).digest('hex')).toBe(row.sseSha256)
      const model = definition(row.model)
      const host = await fixture(cert.tls, response => response.end(row.sse), {}, undefined, [
        model,
      ])
      try {
        const request = historyInput(row.model)
        const planned = await host.transport.plan(request, { signal: new AbortController().signal })
        if ('rejected' in planned) throw new Error(planned.rejected)
        const signal = new AbortController().signal
        const sent = await host.transport.send(planned.planned, 'local-zai-replay-secret', signal)
        if (!('response' in sent)) throw new Error('no local response')
        const initial = start(request.target)
        if ('rejected' in initial) throw new Error(initial.rejected)
        let state = initial.ok
        const reading = host.transport.read(sent.response, planned.planned, signal)
        for (;;) {
          const step = await reading.next()
          if (step.done) {
            expect(step.value).toMatchObject({ ended: 'end' })
            break
          }
          const next = accept(state, step.value)
          if ('rejected' in next) throw new Error(next.rejected)
          state = next.ok
        }
        await sent.response.stopped
        const finished = accept(state, { t: 'finish', reason: 'end' })
        if ('rejected' in finished) throw new Error(finished.rejected)
        const settled = closeOut(finished.ok)
        if ('rejected' in settled) throw new Error(settled.rejected)
        const thinking = settled.ok.blocks.find(block => block.kind === 'thinking')
        if (!thinking || thinking.kind !== 'thinking' || !thinking.opaque)
          throw new Error('missing opaque')
        expect(thinking.text).toBe(row.thought)
        expect(readOpaqueJson(thinking.opaque)).toEqual(
          jsonBody({ routeName: row.model, reasoning_details: [row.detail] }),
        )
        const assistant = judgedMessage({
          type: 'assistant',
          id: 'replayed',
          response: 'original-response',
          ending: 'complete',
          createdAt: at,
          blocks: settled.ok.blocks,
        })
        let captured: JsonObject | undefined
        const productionMeter = createZaiCommercialInputMeter(model)
        const replay = await planRequest(
          {
            ...request,
            messages: [...request.messages, assistant, message('user', 'Continue.', 'followup')],
          },
          [model],
          {
            ...productionMeter,
            measureFull(value) {
              captured = value.body
              return productionMeter.measureFull(value)
            },
          },
          { signal: new AbortController().signal },
          testImagePreparerFor(planRequest),
        )
        // Released at mp4-18: the same-route merged detail is metered as visible reasoning.
        expect(replay).toMatchObject({
          planned: { measurement: { mode: 'full', precision: 'estimated' } },
        })
        expect(captured?.messages).toMatchObject([
          { role: 'system' },
          { role: 'user' },
          { role: 'user' },
          { role: 'assistant', content: row.content, reasoning_details: [row.detail] },
          { role: 'user' },
        ])
        const otherId =
          row.model === 'z-ai/glm-5.3-prime' ? 'z-ai/glm-5.3-flashx' : 'z-ai/glm-5.3-prime'
        const other = definition(otherId)
        const otherMeter = createZaiCommercialInputMeter(other)
        let otherCalls = 0
        const changed = await planRequest(
          {
            ...historyInput(otherId),
            messages: [...request.messages, assistant, message('user', 'Continue.', 'followup')],
          },
          [other],
          {
            ...otherMeter,
            measureFull(value) {
              otherCalls++
              return otherMeter.measureFull(value)
            },
          },
          { signal: new AbortController().signal },
          testImagePreparerFor(planRequest),
        )
        // The other route has no projector for this opaque unit: reject, never degrade to
        // plaintext, and never reach its meter.
        expect(changed).toEqual({ rejected: 'unavailable' })
        expect(otherCalls).toBe(0)
        expect(host.requests).toHaveLength(1)
      } finally {
        await host.close()
      }
    },
  )

  it('refuses a lossy same-route opaque A plus independent plain B before HTTP', async () => {
    const modelId = 'z-ai/glm-5.3-flashx'
    const model = definition(modelId)
    const request = historyInput(modelId)
    const assistant = judgedMessage({
      type: 'assistant',
      id: 'mixed',
      response: 'mixed-response',
      ending: 'complete',
      createdAt: at,
      blocks: [
        {
          id: 'a',
          kind: 'thinking',
          text: 'opaque A',
          opaque: toOpaqueJson({
            routeName: modelId,
            reasoning_details: [{ type: 'reasoning.text', text: 'opaque A', index: 0 }],
          }),
          visibility: { toModel: true, toHuman: true },
        },
        {
          id: 'b',
          kind: 'thinking',
          text: 'unique plain B',
          visibility: { toModel: true, toHuman: true },
        },
      ],
    })
    const original = JSON.stringify(assistant)
    const complete = { ...request, messages: [...request.messages, assistant] }
    const host = await fixture(
      cert.tls,
      response => response.end('unexpected network request'),
      {},
      undefined,
      [model],
    )
    try {
      expect(
        await planRequest(
          complete,
          [model],
          createZaiCommercialInputMeter(model),
          {
            signal: new AbortController().signal,
          },
          testImagePreparerFor(planRequest),
        ),
      ).toEqual({
        rejected: 'unavailable',
      })
      expect(await host.transport.plan(complete, { signal: new AbortController().signal })).toEqual(
        { rejected: 'unavailable' },
      )
      const invocation = invokeModel({
        ...complete,
        transport: host.transport,
        credential: 'local-zai-replay-secret',
        signal: new AbortController().signal,
        policy: policy(),
      })
      expect(await invocation.outcome).toEqual({ rejected: 'unavailable' })
      expect(host.requests).toHaveLength(0)
      expect(JSON.stringify(assistant)).toBe(original)
      expect(assistant.blocks[0]).toMatchObject({ text: 'opaque A' })
      expect(assistant.blocks[1]).toMatchObject({ text: 'unique plain B' })
    } finally {
      await host.close()
    }
  })

  it('retains the supported plain-only path and does not mistake one opaque block for two', async () => {
    const modelId = 'z-ai/glm-5.3-flashx'
    const model = definition(modelId)
    const request = historyInput(modelId)
    const makeAssistant = (opaque: boolean) =>
      judgedMessage({
        type: 'assistant',
        id: opaque ? 'single-opaque' : 'plain-only',
        response: 'reasoning-response',
        ending: 'complete',
        createdAt: at,
        blocks: [
          {
            id: 'a',
            kind: 'thinking',
            text: 'one thought',
            ...(opaque
              ? {
                  opaque: toOpaqueJson({
                    routeName: modelId,
                    reasoning_details: [{ type: 'reasoning.text', text: 'one thought', index: 0 }],
                  }),
                }
              : {}),
            visibility: { toModel: true, toHuman: true },
          },
        ],
      })
    for (const opaque of [false, true]) {
      let captured: JsonObject | undefined
      const meter = createZaiCommercialInputMeter(model)
      const result = await planRequest(
        { ...request, messages: [...request.messages, makeAssistant(opaque)] },
        [model],
        {
          ...meter,
          measureFull(value) {
            captured = value.body
            return meter.measureFull(value)
          },
        },
        { signal: new AbortController().signal },
        testImagePreparerFor(planRequest),
      )
      expect(captured).toBeDefined()
      const messages = captured?.messages
      if (!Array.isArray(messages)) throw new Error('no captured messages')
      const assistantWire = messages.find(value => object(value) && value.role === 'assistant')
      if (opaque) {
        expect(assistantWire).toHaveProperty('reasoning_details')
        expect(assistantWire).not.toHaveProperty('reasoning')
        // This hand-built detail lacks the captured `format` key: unexplained, refused.
        expect(result).toMatchObject({
          rejected: 'invalidInput',
          reason: 'input_size_unavailable',
        })
      } else {
        expect(assistantWire).toMatchObject({ reasoning: 'one thought' })
        expect(assistantWire).not.toHaveProperty('reasoning_details')
        expect(result).toHaveProperty('planned')
      }
    }
  })
})

tests/zai-reasoning-history.spec.ts.source:
import { testImagePreparerFor } from './image-transport-support.ts'
import { describe, expect, it } from 'vitest'
import { toOpaqueJson, writeJsonLossless, type JsonObject } from '@omne-harness-lite/content-blocks'
import { parseOpaqueIdentifier, unwrap } from '@omne-harness-lite/identity-values'
import { judgeMessage, type Message } from '@omne-harness-lite/messages'
import type { PlanInput } from '@omne-harness-lite/model-request-runtime'
import { createOfficialProfileContent } from '../src/configuration.ts'
import type { ModelDefinition } from '../src/definitions.ts'
import type { InputMeter } from '../src/input-meter.ts'
import { createGlm52InputMeter } from '../src/input-meters/zai-glm52.ts'
import { createGlm53InputMeter } from '../src/input-meters/zai-glm53.ts'
import { zaiDefinitions } from '../src/official-models/zai.ts'
import { planRequest } from '../src/plan.ts'

const at = '2026-09-28T00:00:00Z'
const modelIds = ['z-ai/glm-5.2', 'z-ai/glm-5.3', 'z-ai/glm-5.3-flash'] as const

function judged(raw: unknown): Message {
  const result = judgeMessage(raw)
  if ('rejected' in result) throw new Error(result.rejected)
  return result.ok
}

function definition(modelId: string): ModelDefinition {
  const selected = zaiDefinitions.find(item => item.modelId === modelId)
  if (!selected) throw new Error(`missing official definition: ${modelId}`)
  return selected
}

function input(model: ModelDefinition, opaque: boolean): PlanInput {
  const provider = 'z-ai/fp8'
  const profile = createOfficialProfileContent(model, {
    providers: [provider],
    allowFallback: false,
    configuration: { revision: '1', values: { cache: { mode: 'automatic' } } },
  })
  if ('rejected' in profile) throw new Error(profile.rejected)
  const thinking = 'Consider the exact arithmetic before answering.'
  const assistant = judged({
    type: 'assistant',
    id: 'previous-assistant',
    response: 'previous-response',
    ending: 'complete',
    createdAt: at,
    blocks: [
      {
        id: 'reasoning',
        kind: 'thinking',
        text: thinking,
        ...(opaque
          ? {
              opaque: toOpaqueJson({
                routeName: model.modelId,
                reasoning_details: [{ type: 'reasoning.text', text: thinking, index: 0 }],
              }),
            }
          : {}),
        visibility: { toHuman: false, toModel: true },
      },
      {
        id: 'answer',
        kind: 'text',
        text: 'The answer is 42.',
        visibility: { toHuman: true, toModel: true },
      },
    ],
  })
  const reminder = judged({
    type: 'system_reminder',
    id: 'reminder',
    createdAt: at,
    nature: 'event',
    source: { kind: 'attempt_started', attempt: 1, reason: 'first', at },
    blocks: [
      {
        id: 'reminder-text',
        kind: 'text',
        text: 'Keep the earlier answer in context.',
        visibility: { toHuman: true, toModel: true },
      },
    ],
  })
  const user = judged({
    type: 'user',
    id: 'follow-up',
    createdAt: at,
    blocks: [
      {
        id: 'question',
        kind: 'text',
        text: 'What was the answer?',
        visibility: { toHuman: true, toModel: true },
      },
    ],
  })
  return {
    calibration: { kind: 'none' as const, reason: 'no_observation' as const },
    outputHistory: [],
    tokenMargin: { multiplier: 1.2, reserveTokens: 32 },
    target: {
      kind: 'model_call',
      callId: unwrap(parseOpaqueIdentifier('zai-history-oracle', 'ModelCallId')),
      dispatch: 1,
    },
    routeName: model.modelId,
    provider,
    snapshot: {
      adaptation: profile.ok.adaptation,
      providers: profile.ok.providers,
      allowFallback: profile.ok.allowFallback,
      inputModalities: profile.ok.inputModalities,
      outputModalities: profile.ok.outputModalities,
      maxInputTokens: profile.ok.maxInputTokens,
      maxOutputTokens: profile.ok.maxOutputTokens,
      inputConstraints: profile.ok.inputConstraints,
      upstreamInputLimits: profile.ok.upstreamInputLimits,
      updatedAt: at,
    },
    parameters: { maxOutputTokens: 64 },
    messages: [assistant, reminder, user],
    tools: [],
  }
}

function meter(model: ModelDefinition): InputMeter {
  return model.modelId === 'z-ai/glm-5.2'
    ? createGlm52InputMeter(model)
    : createGlm53InputMeter(model)
}

describe('Z.AI complete historical reasoning at the public planning boundary', () => {
  it.each(
    modelIds.flatMap(modelId => [
      { modelId, opaque: false },
      { modelId, opaque: true },
    ]),
  )(
    '$modelId opaque=$opaque retains history; only a released plain string is estimated',
    async ({ modelId, opaque }) => {
      const model = definition(modelId)
      const actual = meter(model)
      let finalBody: JsonObject | undefined
      const observing: InputMeter = {
        ...actual,
        measureFull(request) {
          finalBody = request.body
          expect(request.serialized).toBe(writeJsonLossless(request.body))
          return actual.measureFull(request)
        },
      }
      const result = await planRequest(
        input(model, opaque),
        [model],
        observing,
        {
          signal: new AbortController().signal,
        },
        testImagePreparerFor(planRequest),
      )
      // All three leaves are released at mp4-18 (visible history; GLM-5.3 and Flash after
      // ZV0). This hand-built detail lacks the captured `format` key: always refused.
      expect(model.implementation.revision).toBe('mp4-18')
      if (!opaque) {
        expect(result).toMatchObject({
          planned: { measurement: { mode: 'full', precision: 'estimated' } },
        })
      } else
        expect(result).toEqual({
          rejected: 'invalidInput',
          reason: 'input_size_unavailable',
          metrics: ['maxInputTokens'],
        })
      expect(finalBody?.messages).toMatchObject([
        {
          role: 'assistant',
          content: 'The answer is 42.',
          ...(opaque
            ? {
                reasoning_details: [
                  {
                    type: 'reasoning.text',
                    text: 'Consider the exact arithmetic before answering.',
                    index: 0,
                  },
                ],
              }
            : { reasoning: 'Consider the exact arithmetic before answering.' }),
        },
        {
          role: 'user',
          content: [
            { text: '[system_reminder "reminder"]' },
            { text: 'Keep the earlier answer in context.' },
          ],
        },
        { role: 'user', content: [{ text: 'What was the answer?' }] },
      ])
    },
  )
})

